-- Falas de Pokemon Gold em portugues brasileiro.
-- Chave = ponteiro da ROM USA, no formato que o gen1recomp usa.
-- Vazio ou ausente = cai em ingles.
return {
  ["00:2815"] = "Evento de objeto.",
  ["40:4615"] = "Bom dia!\nBem-vindo ao nosso\vCENTRO POKéMON.",
  ["40:4640"] = "Olá!\nBem-vindo ao nosso\vCENTRO POKéMON.",
  ["40:4664"] = "Boa noite!\nSaiu tarde, hein?\fBem-vindo ao nosso\nCENTRO POKéMON.",
  ["40:469f"] = "Podemos curar seus\nPOKéMON até a\vsaúde perfeita.\fCuramos os seus\nPOKéMON?",
  ["40:46e2"] = "Certo, posso ver\nseus POKéMON?",
  ["40:46fc"] = "Obrigada por\nesperar.\fSeus POKéMON estão\ncurados.",
  ["40:4730"] = "Esperamos ver você\nde novo.",
  ["40:474b"] = "Esperamos ver você\nde novo.",
  ["40:4766"] = "Seus POKéMON pare-\ncem ter formas de\fvida minúsculas\ngrudadas neles.\fSeus POKéMON estão\nsaudáveis e bem\vde modo geral.\fMas não podemos\ndizer mais nada\fnum CENTRO\nPOKéMON.",
  ["40:4801"] = "Está cheia de\nlivros difíceis.",
  ["40:481f"] = "Uma coleção\ninteira de livros\vde POKéMON!",
  ["40:484a"] = "Revistas de POKé-\nMON… POKéMON PAL,\fPOKéMON HANDBOOK,\nPOKéMON GRAPH…",
  ["40:4880"] = "JURAMENTO ROCKET\fRoubar POKéMON\npor lucro!\fExplorar POKéMON\npor lucro!\fPOKéMON existem\npara a glória da\vTEAM ROCKET!",
  ["40:48ef"] = "O que é isto?\fAh, é um\nincensário!",
  ["40:4919"] = "Um monte de produ-\ntos de POKéMON!",
  ["40:4934"] = "É o TOWN MAP.",
  ["40:4947"] = "Meu reflexo!\nTô bonito!",
  ["40:4965"] = "É uma TV.",
  ["40:4970"] = "POKéMON JOURNAL\nPÁGINA INICIAL…\fNão foi\natualizada…",
  ["40:49a0"] = "POKéMON RADIO!\fLigue e peça a\nsua música!",
  ["40:49cd"] = "Não tem nada\naqui dentro…",
  ["40:49e6"] = "Um POKéMON talvez\nconsiga mover.",
  ["40:4a08"] = "Talvez um POKéMON\nquebre isto.",
  ["40:4a26"] = "Cure Seus POKéMON!\nCENTRO POKéMON",
  ["40:4a43"] = "Tudo Que Seu\nPOKéMON Precisa\fLOJA POKéMON",
  ["40:4a66"] = "Vamos agora julgar\nos POKéMON que\vvocê pegou.\f……\n……\fJá escolhemos os\nvencedores!\fVocê está pronto\npara isto?",
  ["40:4ac8"] = "Uau! Você é bem\ndurão.\fMe dá o seu número\nde telefone?\fEu ligo para você\npara a revanche.",
  ["40:4b1d"] = "Registrar o número\nde telefone?",
  ["40:4b39"] = "{PLAYER} registrou\n{STRBUF}.",
  ["40:4b48"] = "{STRBUF}.",
  ["40:4b56"] = "Eu ligo se rolar\nalguma coisa.",
  ["40:4b7a"] = "Ah, tá…\nFale comigo se\fquiser o meu\nnúmero.",
  ["40:4bb7"] = "O seu telefone não\ntem memória para\vmais números.",
  ["40:4bef"] = "Eu estava esperan-\ndo. Vamos lutar!",
  ["40:4c14"] = "Uau, você é bom\nde batalha.\fQuer me dar o seu\nnúmero?\fEu ligo para outra\nbatalha.",
  ["40:4c77"] = "Registrar o número\nde telefone?",
  ["40:4c93"] = "{PLAYER} registrou\n{STRBUF}.",
  ["40:4cb0"] = "Eu ligo se rolar\nalguma coisa.",
  ["40:4cd0"] = "Ah, tudo bem…\nSe quiser o meu\fnúmero, é só\nme falar.",
  ["40:4d12"] = "O seu telefone não\ntem memória para\vmais números.",
  ["40:4d4a"] = "Eu esperei você.\nVamos lutar!",
  ["40:4d6a"] = "{PLAYER} ganha o\nprêmio {STRBUF},\vum {STRBUF}!",
  ["40:4d7b"] = "prêmio {STRBUF},\vum {STRBUF}!",
  ["40:4d90"] = "{PLAYER} recebeu\n{STRBUF}.",
  ["40:4da3"] = "Volte para o\npróximo Concurso!",
  ["40:4dc9"] = "Todos os outros\nganham uma BERRY\vde consolação!",
  ["40:4dff"] = "Esperamos que vá\nmelhor na próxima",
  ["40:4e21"] = "Vamos devolver o\nPOKéMON que\fguardamos.\nAqui está!",
  ["40:4e55"] = "Seu grupo está\ncheio, então o\fPOKéMON foi para\na BOX do BILL.",
  ["40:4e96"] = "{STRBUF}\nGINÁSIO POKéMON",
  ["40:4ea4"] = "LÍDER: {STRBUF}\fTREINADORES QUE\nVENCERAM: {PLAYER}",
  ["40:4ec7"] = "Bem-vindo ao\nGAME CORNER.",
  ["40:4ee4"] = "Precisa de fichas\nde jogo?\fAh, você não tem\numa COIN CASE\vpara elas.",
  ["40:4f2b"] = "Precisa de umas\nfichas de jogo?\fSão ¥1000 por\n50 fichas. Quer\vcomprar?",
  ["40:4f78"] = "Obrigado!\nAqui, 50 fichas.",
  ["40:4f97"] = "Obrigado! Aqui\nestão 500 fichas.",
  ["40:4fb7"] = "Você não tem\ndinheiro.",
  ["40:4fd4"] = "Opa! Sua COIN\nCASE está cheia.",
  ["40:4ff5"] = "Sem fichas hoje?\nVolte sempre!",
  ["40:5014"] = "Ué? Sua BOLSA está\ncheia.\fVamos guardar isto\npor hoje, então\fvolte quando tiver\nespaço para ele.",
  ["40:5072"] = "Uau! Você e seu\nPOKéMON são muito\vunidos!",
  ["40:509c"] = "POKéMON ficam mais\namigos se você\fpassar tempo\ncom eles.",
  ["40:50d1"] = "Você não domou\no seu POKéMON.\fSe não for legal,\nele emburra.",
  ["40:510c"] = "{PLAYER} pegou\n¥{NUM}!",
  ["40:538d"] = "{NUM}\npor vencer!",
  ["40:53cb"] = "{NUM}\npor vencer!\vMandei para MÃE!",
  ["40:5459"] = "{RIVAL}: Isso!\nAcho que escolhi\vum bom POKéMON!",
  ["40:54a4"] = "{STRBUF}.\f{PLAYER} vai\ntrocar POKéMON?",
  ["40:54d1"] = "Não há vontade de\nlutar!",
  ["40:567f"] = "O {STRBUF}\nselvagem come!",
  ["40:569d"] = "{STRBUF}\nestá furioso!",
  ["40:58bc"] = "{STRBUF} está\vDISABLED!",
  ["40:5b39"] = "{STRBUF} caiu\vem {NUM}!",
  ["40:5c2c"] = "{STRBUF} não\vsobe mais!",
  ["40:5c49"] = "{STRBUF} não\vcai mais!",
  ["40:5dd7"] = "{STRBUF} ficou\vDISABLED!",
  ["40:5f99"] = "{STRBUF}\vde seu inimigo!",
  ["41:4a99"] = "Alô?\fAh, oi, {PLAYER}!\nTrabalhando duro?",
  ["41:4aba"] = "Ah, você está em\n{STRBUF}…\fNão é ali que\n{STRBUF}\ffica? Você foi\ndar uma olhada?",
  ["41:4b04"] = "Sério, você está\nem {STRBUF}?\fNunca fui lá.\nQue legal isso,\v{PLAYER}.",
  ["41:4b4a"] = "O quê? Você está\nem {STRBUF}?\fVenha ver sua MÃE\num dia desses!",
  ["41:4b7d"] = "Você está visitan-\ndo {STRBUF}?\fQue tal vir para\ncasa um pouco?",
  ["41:4bb5"] = "Uau, você está em\n{STRBUF}?\fBoa sorte na sua\nmissão POKéMON!",
  ["41:4be9"] = "Isso parece bem\ndifícil.\fMas, {PLAYER}, eu\nsei que você é\fdeterminado. Vai\nficar bem, né?",
  ["41:4c40"] = "A propósito, você\ntem ¥{STRBUF}.\fQuer continuar\nguardando?",
  ["41:4c83"] = "É importante\nguardar dinheiro.",
  ["41:4ca6"] = "Ah, {PLAYER},\nvocê não está\fguardando nada.\nQuer guardar?",
  ["41:4ce2"] = "A propósito, você\ntem ¥{STRBUF}.\fQuer voltar a\nguardar?",
  ["41:4d22"] = "Certo. Eu guardo\nseu dinheiro.",
  ["41:4d3c"] = "Certo. Paro de\nguardar.",
  ["41:4d5d"] = "{PLAYER}, continue\nassim! Estou\vtorcendo, filho!",
  ["41:4d87"] = "Alô?\fAh, oi, {PLAYER}!\nO PROF.ELM não\vestava esperando?",
  ["41:4dba"] = "Alô?\fAh, oi, {PLAYER}!\nVocê está numa\fmissão do PROF.\nELM? Se comporte!",
  ["41:4dfc"] = "Alô?\fOi, {PLAYER}! Se\njá terminou o\fseu recado, volte\npara casa, filho.",
  ["41:4e3e"] = "Alô?\f…… {PLAYER}?\nO PROF.ELM me\fdisse que você foi\nnuma viagem longa\fQueria que tivesse\nme contado…\fE o dinheiro?\nEu guardo?",
  ["41:4ec4"] = "Bom dia!\fAqui é o SERVIÇO\nDE ADMINISTRAÇÃO\fDO SISTEMA DE\nARMAZENAMENTO.",
  ["41:4f0d"] = "Boa tarde!\fAqui é o SERVIÇO\nDE ADMINISTRAÇÃO\fDO SISTEMA DE\nARMAZENAMENTO.",
  ["41:4f52"] = "Boa noite!\fAqui é o SERVIÇO\nDE ADMINISTRAÇÃO\fDO SISTEMA DE\nARMAZENAMENTO.",
  ["41:4f9b"] = "Quem fala?\f{PLAYER}, é você?\nUm segundinho…\f……\n……",
  ["41:4fc7"] = "Obrigado por\nesperar!\f{PLAYER}, sua BOX\ntem espaço para\vmais {STRBUF}!\fVá lá e encha\nela!",
  ["41:5024"] = "Obrigado por\nesperar!\f{PLAYER}, sua BOX\nsó tem lugar\vpara {STRBUF}.\fTalvez seja hora\nde trocar de BOX.",
  ["41:508a"] = "Obrigado por\nesperar!\f{PLAYER}, sua BOX\nestá cheia!\fVai ter que trocar\nde BOX se quiser\fpegar mais\nPOKéMON.",
  ["41:50ef"] = "Oi, {PLAYER}?\nSou eu, o BILL!\fObrigado por usar\no STORAGE SYSTEM.\fO último POKéMON\nque você mandou\vencheu sua BOX.\fVai ter que trocar\nde BOX se quiser\fpegar mais\nPOKéMON.\fAté mais!",
  ["41:5199"] = "Alô, {PLAYER}?\fTente não exage-\nrar.\fCure seus POKéMON\nsempre que eles\vse machucarem.",
  ["41:51e6"] = "Alô, {PLAYER}?\fEncontrou o MR.\nPOKéMON? Ótimo!\vVolte em paz!",
  ["41:5221"] = "{PLAYER}? Estou\nmuito chateado.\fRoubaram um\nPOKéMON daqui.\fComo alguém faz\numa coisa dessas?",
  ["41:5272"] = "Alô, {PLAYER}?\fEstamos checando o\nEGG. Ele parece\fmesmo ser um\nEGG de POKéMON.",
  ["41:52b9"] = "Alô, {PLAYER}?\fViu meu assisten-\nte? Ele está no\fCENTRO POKéMON de\nVIOLET CITY.",
  ["41:5305"] = "Alô, {PLAYER}?\fComo está o EGG?\nMudou algo?\fSe acontecer algo,\npor favor ligue.",
  ["41:5358"] = "Alô, {PLAYER}?\nComo está o EGG?\fO quê? Chocou?\nUau! Que tipo de\vPOKéMON é?\fVenha me mostrar\nagora!",
  ["41:53bc"] = "Alô, {PLAYER}?\fAcabei de fazer\numa descoberta.\fO tempo que um\nEGG leva para\fchocar depende do\nPOKéMON.",
  ["41:541f"] = "Alô, {PLAYER}?\fAinda é um\nmistério que\fgolpes um POKéMON\nchocado sabe.\fEstamos investi-\ngando isso agora.",
  ["41:5484"] = "Alô, {PLAYER}?\fDescobri uma\ncoisa estranha.\fParece que existe\numa coisa chamada\fPOKéRUS que in-\nfecta POKéMON.\fSim, é como um\nvírus, por isso\vse chama POKéRUS.\fEle se multiplica\nrápido e infecta\foutros POKéMON.\nMas é só isso.\fNão parece fazer\nnada, e some\fcom o tempo\nsozinho.\fAcho que não é\nnada para se\vpreocupar. Tchau!",
  ["41:55b4"] = "A-alô? {PLAYER}?\nÉ um desastre!\fAh, hum, é\nterrível!\fO que eu faço?\nIsso… Ai, não…\fPor favor volte\npara cá agora!",
  ["41:5624"] = "Alô, {PLAYER}?\nDescobrimos uma\fcoisa sobre o\nEGG!\fMeu assistente\nestá no CENTRO\fPOKéMON de VIOLET\nCITY. Pode falar\vcom ele?",
  ["41:56a3"] = "{PLAYER}, como\nvão as coisas?\fLiguei porque tem\nalgo estranho\facontecendo com as\ntransmissões.\fEstavam falando\nda TEAM ROCKET.\f{PLAYER}, você\nsabe de alguma\vcoisa?\fSerá que a TEAM\nROCKET voltou?\fNão, isso não pode\nser verdade.\fDesculpe incomodar\nSe cuide!",
  ["41:57a6"] = "Alô, {PLAYER}?\fTenho uma coisa\naqui para você.\fPode dar uma\npassada no LAB?\fAté mais!",
  ["41:57fa"] = "Alô, {PLAYER}?\nComo vai?\fConsegui uma\ncoisa bacana.\fPasse no meu LAB\ne pegue!\fAté mais!",
  ["41:5862"] = "Alô. Aqui é\n{STRBUF}…\fBom dia,\n{PLAYER}!",
  ["41:588a"] = "Alô. Aqui é\n{STRBUF}…\fComo vai,\n{PLAYER}?",
  ["41:58b3"] = "Alô. Aqui é\n{STRBUF}…\fBoa noite,\n{PLAYER}!",
  ["41:58db"] = "Oi. Aqui é\n{STRBUF}.\fOi, {PLAYER}!\nBom dia.",
  ["41:5904"] = "Oi. Aqui é\n{STRBUF}.\fOi, {PLAYER}!\nTudo bem?",
  ["41:592c"] = "Oi. Aqui é\n{STRBUF}.\fOi, {PLAYER}!\nBoa noite.",
  ["41:5955"] = "{PLAYER}, bom\ndia!\fÉ {STRBUF}.\nComo você está?",
  ["41:5989"] = "{PLAYER}, oi!\fÉ {STRBUF}.\nO tempo está bom?",
  ["41:59b5"] = "{PLAYER}, boa\nnoite!\fÉ {STRBUF}.\nTem um minuto?",
  ["41:59e4"] = "Bom dia,\n{PLAYER}.\fAqui é {STRBUF}.\nEu te acordei?",
  ["41:5a15"] = "Alô, {PLAYER}.\fAqui é {STRBUF}.\nComo vai tudo?",
  ["41:5a3f"] = "Boa noite,\n{PLAYER}.\fAqui é {STRBUF}.\nEstava acordado?",
  ["41:5a70"] = "Como estão seus\nPOKéMON?\fMeu {STRBUF} é\nmuito animado.\vDá trabalho!",
  ["41:5ab5"] = "Como estão seus\nPOKéMON?\fEu mantenho meu\n{STRBUF} em dia\findo sempre aos\nCENTROS POKéMON.",
  ["41:5b0d"] = "Meu {STRBUF}\nestá lindo.\fQueria poder\nte mostrar.",
  ["41:5b42"] = "Eu enfeitei meu\n{STRBUF}.\fFicou ainda mais\nfofo que antes.",
  ["41:5b7b"] = "Ah, sim, consegui\nvencer um\v{STRBUF} durão.\fPreciso deixar meu\ntime mais forte.",
  ["41:5bcb"] = "Você tem que ouvir\nisso! Eu lutei\fcom {STRBUF}\noutro dia.\fFoi fácil! Tinha\nvantagem de tipo.",
  ["41:5c27"] = "Ei, escuta!\nQuase peguei\f{STRBUF} outro\ndia.\fAh, foi por muito\npouco!",
  ["41:5c76"] = "Adivinha o que\nrolou outro dia.\fPerdi o {STRBUF}\nde novo.\fTalvez eu não seja\nbom nisso…",
  ["41:5cdb"] = "Quer batalhar?\nNão vai ser igual\fà última vez que\na gente se viu.\fVou estar perto de\n{STRBUF}.",
  ["41:5d37"] = "Você quer\nbatalhar? Eu vou\vganhar desta vez!\fVou estar te\nesperando lá em\f{STRBUF}.\nMe procure, tá?",
  ["41:5da0"] = "Alô? Aqui é\n{STRBUF}…\fOpa… Você não é\no KAZ! Desculpe,\vnúmero errado.",
  ["41:5de2"] = "Alô, aqui é\n{STRBUF}. Como\vvai, AUDREY?\fHã? {PLAYER}?\nOpa! Foi engano!",
  ["41:5e48"] = "Você tem que ver\nisso! É doido!\fUm monte de\n{STRBUF}\fapareceu perto de\n{STRBUF}!",
  ["41:5e9c"] = "É incrível!\fEm {STRBUF},\n{STRBUF} estão\fmordendo como se\nnão houvesse fim.\f{PLAYER}, traga\nsua ROD, amigo!",
  ["41:5efa"] = "Um amigo acabou\nde me contar.\fEle viu um monte\nde {STRBUF} em\v{STRBUF}.\f{PLAYER}, vá\ndar uma olhada.",
  ["41:5f50"] = "Estão fazendo o\nConcurso de\fCaptura Insetos\nhoje no PARK.\f{PLAYER}, você\nvai?",
  ["41:5fa4"] = "{PLAYER}, você\nsabia?\fOuvi dizer que\nRADIO TOWER foi\ftomada pela TEAM\nROCKET.\fMas o que é\na TEAM ROCKET?",
  ["41:6014"] = "{PLAYER}, você\nouviu a notícia?\fA TEAM ROCKET\ntomou a RADIO\fTOWER de\nGOLDENROD CITY.\fEstarão bem os\nfuncionários?",
  ["41:608d"] = "Oi, {PLAYER}!\nNossas vendas de\fBICYCLE foram\nàs nuvens!\fTudo graças à\nsua propaganda,\fandando por aí\nna nossa BICYCLE.\fComo forma de\nagradecer, fique\fcom essa BICYCLE.\nValeu de novo!",
  ["42:4087"] = "Todos os seres\nvivos coexistem\vem cooperação.\fDevemos sempre ser\ngratos por isso.",
  ["42:40dc"] = "Só quem chega ao\ntopo é que ganha\vum HM.",
  ["42:410e"] = "A SPROUT TOWER foi\nerguida há muito\fcomo lugar de\ntreino POKéMON.",
  ["42:414d"] = "Um BELLSPROUT de\nmais de 30 metros\fDizem que ele\nvirou o pilar\vcentral daqui.",
  ["42:41a1"] = "Viu o pilar\ntremendo?\fEstão treinando\nlá em cima.",
  ["42:41da"] = "Estátua POKéMON…\fParece muito\nimponente.",
  ["42:42e3"] = "Lutei duro, mas\nsou fraco demais.",
  ["42:4303"] = "A coluna flexível\nprotege a TOWER\fmesmo contra\nterremotos.",
  ["42:4345"] = "…Balance como\nfolhas ao vento…",
  ["42:4373"] = "Tentei copiar os\nmovimentos gentis\fdo BELLSPROUT\npara a batalha…\fMas não treinei\nbem o bastante.",
  ["42:43cc"] = "Estátua de POKé-\fMON… Ela parece\nmuito distinta.",
  ["42:452b"] = "ELDER: Você é\nmuito habilidoso\vcomo treinador.\fComo prometi,\naqui está a HM.\fMas quero dizer:\nvocê deve cuidar\fbem dos seus\nPOKéMON.\fSeu jeito de\nbatalhar é duro\fPOKéMON não são\narmas de guerra…",
  ["42:45f0"] = "…\n…Humf!\fEle se diz o\nELDER, mas é\vfraco.\fFaz sentido.\nJamais perderia\fpra tolos que\nfalam de ser\flegais com os\nPOKéMON.\fSó me importam\nPOKéMON fortes,\vque sabem vencer.\fNão me importo\nnem um pouco com\vPOKéMON fracos.",
  ["42:46cc"] = "{RIVAL} usou uma\nCORDA DE FUGA!",
  ["42:46e4"] = "Que bom você\nter vindo!\fA SPROUT TOWER,\nlugar de treino.\fPessoas e POKéMON\ntestam seus laços\fpara construir\num futuro juntos.\fSou o teste\nfinal.\fDeixe-me ver\nos laços entre\fvocê e seus\nPOKéMON!",
  ["42:47b6"] = "Ah, excelente!",
  ["42:47c6"] = "Você e seus POKé-\nMON não terão\fproblema em\nusar esse golpe.\fLeve esta HM de\nFLASH.",
  ["42:4817"] = "FLASH ilumina\naté os lugares\vmais escuros.\fMas, para usar\nfora de batalha,\fprecisa do BADGE\nde VIOLET CITY.",
  ["42:488c"] = "Espero que você\naprenda e cresça\vcom a jornada.",
  ["42:48ba"] = "Treino para achar\niluminação nos\vPOKéMON!",
  ["42:48e2"] = "Derrotado por\numa mera criança!",
  ["42:48fb"] = "Quando os POKéMON\nficam fortes, o\vtreinador também.\fEspera. Quando o\ntreinador fica\fforte, os POKéMON\ntambém.",
  ["42:4961"] = "Deixe-me ver o\nquanto você confia\vnos seus POKéMON.",
  ["42:498b"] = "Sim, a sua\nconfiança é real!",
  ["42:49a5"] = "Não é longe até\no ELDER.",
  ["42:49c2"] = "O HM do ELDER\nilumina até a\vescuridão total.",
  ["42:49f4"] = "É a minha cabeça\nque é brilhante!",
  ["42:4a13"] = "Que haja luz\nna sua jornada.",
  ["42:4a38"] = "É uma pintura\npoderosa de um\vBELLSPROUT.",
  ["42:4a62"] = "Estátua de POKé-\fMON… Ela parece\nmuito distinta.",
  ["42:4b20"] = "Tento descobrir o\nsegredo do\fPOKéMON lendário\nque dizem pousar\vaqui.\fContam que esse\nPOKéMON voa sem\fparar desde que a\nTORRE do Oeste\vpegou fogo.\fEntão pensei: se\neu tivesse o que\fesse POKéMON tem,\nele seria atraído\vpelo item.\fAcho que esse item\ndeve ser…\fUma RAINBOW WING!\fMas onde eu acho\numa dessas?",
  ["42:4f24"] = "…… …… ……\f…Ah, é você.\fVocê queria ficar\nmais forte, então\fveio atrás do\nPOKéMON lendário\fque dizem estar\naqui. É essa a sua\vhistória, né?\fPois isso não vai\nacontecer.\fPorque eu vou\npegar ele!\fEu vou ser o maior\ntreinador do mun-\vdo, então um\vPOKéMON lendário\vseria perfeito\vpara mim.\f…Enfim, tanto faz\nJá estou cansado\fde ter um banana\ncomo você sempre\vaparecendo.",
  ["42:5093"] = "…Hunf!\fÉ por isso que eu\nodeio lutar com\fbananas. Não tem\ndesafio nenhum.",
  ["42:50da"] = "…Ah, tanto faz.\fVocê nunca ia\nconseguir pegar\fPOKéMON lendário\nmesmo.",
  ["42:5124"] = "…Hunf!\fÉ por isso que eu\nodeio lutar com\fbananas. É só\nperda de tempo.",
  ["42:516d"] = "Ei, estou treinan-\ndo aqui escondido\fNão me constranja\nficando olhando!",
  ["42:51ac"] = "Queimei até virar\ncinzas brancas…",
  ["42:51cb"] = "Eu estava tão con-\ncentrado que\facabei caindo\nneste buraco.",
  ["42:5202"] = "Minha alma está\nem chamas. Vou\fmostrar como isso\nqueima!",
  ["42:5236"] = "Ainda não esquenta\no bastante…",
  ["42:524d"] = "Antigamente,\nhavia POKéMON\fque corriam pela\ngrama em super\valta velocidade.\fDizem que correm\ncomo o vento.\fSe você esbarrar\nem um na grama,\vele vai fugir.",
  ["42:552a"] = "Bando de DIGLETT\npulou do chão!\fIsso foi\nchocante!",
  ["42:562d"] = "…… …… ……\fFaz tempo, hein,\n{PLAYER}.\f…Desde que perdi\npra você, pensei\fno que faltava\naos meus\vPOKéMON…\fE chegamos a\numa resposta.\f{PLAYER}, agora\nvamos te mostrar!",
  ["42:56c5"] = "…… …… ……\fPensei que meus\nPOKéMON eram\fos melhores que\npodiam ser…\f…Mas ainda\nnão bastou…",
  ["42:5722"] = "…… …… ……\f…Você venceu,\nde forma justa.\fAdmito. Mas\nisto não é\vo fim.\fVou me tornar o\nmaior treina-\vdor de POKéMON.\fPorque esses caras\nestão comigo.\f…Escute, {PLAYER}.\fUm dia desses,\nvou provar\fo quanto sou bom\nderrotando você.",
  ["42:5808"] = "…… …… ……\fQuitei minha\ndívida com você.\fCom meus POKéMON,\nvou derrotar o\fCAMPEÃO e me\ntornar o melhor\vdo mundo.",
  ["42:5a87"] = "Espera aí.\f…Vai encarar o\ndesafio da LIGA\vPOKéMON?\f…Não me faça\nrir.\fVocê é bem mais\nfraco que eu.\fNão sou como\nantes.\fAgora tenho os\nmelhores e mais\ffortes POKéMON.\nSou invencível!\f{PLAYER}!\nEu te desafio!",
  ["42:5b65"] = "…Não venci…\fDei tudo o que\ntinha…\fO que você tem,\ne o que me falta…\fComeço a entender\no que aquele\fmestre de dragões\nme disse…",
  ["42:5bf6"] = "…Não desisti\nde me tornar o\vmaior treinador…\fVou descobrir\npor que não\fconsigo vencer\ne ser mais forte…\fQuando descobrir,\neu te desafio.\fE vou te derrotar\ncom toda a minha\vforça.\f…Humf! Continue\naté lá.",
  ["42:5cd2"] = "…Humf!\fNo fim das\ncontas, nada\vvence a força.\fNão preciso de\nmais nada.",
  ["42:8b49"] = "i.",
  ["42:a000"] = "oga! Eu tenho\nPOKéMONS inúteis!",
  ["42:e248"] = " vou dividir\nessa PEDRA DO REI\vcom você.",
  ["42:e342"] = "dor de OLIVINE.\fO FAROL foi\nconstruído em\vhomenagem a estes\vPOKéMONS.",
  ["42:e700"] = "E você?",
  ["43:4196"] = "Olhe! Veja a minha\nbolsa!\fImprimi os meus\nfavoritos da\fPOKéDEX e colei\nna minha bolsa.",
  ["43:41f1"] = "Esta é uma MAIL da\nminha filha.\vEla me anima.",
  ["43:4228"] = "Atenção, por\nfavor!\f…Opa, preciso\nparar de pensar\fcomo professora o\ntempo todo.\fVocê deve ser um\ntreinador POKéMON\fJá que se esforça\ntanto, quero que\fvocê fique com\nisto.",
  ["43:42d0"] = "Dê essa QUICK CLAW\na um POKéMON.\fÀs vezes ele ataca\nprimeiro na\vbatalha.",
  ["43:4320"] = "Estou brincando\ncom adesivos que\vtirei da POKéDEX.",
  ["43:4352"] = "Se eu ganhar, fico\ncom o adesivo da\vPOKéDEX dele.",
  ["43:437f"] = "Eu passeio pelo\nPARK, mas nunca\fentro no meio do\nmato.\fTreinadores sempre\nquerem batalhar…",
  ["43:43d9"] = "PERSIAN: Fufusha!",
  ["43:43ed"] = "Estou imprimindo a\nminha POKéDEX.\fDá para imprimir\noutras coisas,\fcomo MAIL e suas\nBOXES do PC.",
  ["43:4441"] = "O mundo POKéMON\né profundo.\fAinda existem\nmuitas coisas que\vnão sabemos.\fMas eu sei mais\ndo que você!",
  ["43:44b6"] = "Há muito\no que aprender.\fPor exemplo…\fExistem 50 tipos\nde TM.\fPOKéMON trocados\nsobem mais rápido",
  ["43:4514"] = "Meus POKéMON são\ntão fofos. Vou\vmostrar a você.",
  ["43:4547"] = "Talvez eu não\nte vença na luta…\fMas os meus são\nbem mais bonitos.",
  ["43:4584"] = "Minha amiga tem um\nMARILL. É tão\ffofo! Queria ter\num MARILL.",
  ["43:45c1"] = "Adoramos nossos\nPOKéMON, mesmo que\veles não gostem.\fÉ isso que é\nser um FAN.",
  ["43:461d"] = "Perdi a batalha,\nmas meus POKéMON\fganham o prêmio\npor serem fofos.",
  ["43:4662"] = "Olá? Por que você\nfica me olhando?\fAh, uma batalha?",
  ["43:469b"] = "Pelo seu olhar,\npensei que você\vgostava de mim.\fAfinal, eu sou\nfofa!",
  ["43:46e4"] = "PRAÇA DO DESCANSO\nNATIONAL PARK",
  ["43:4705"] = "O que diz este\naviso?\fBatalhe somente no\nmato, por favor.\fNATIONAL PARK\nSEDE DA GUARDA",
  ["43:4745"] = "SEDE DA GUARDA\nDO PARK",
  ["43:475a"] = "TRAINER TIPS\fPara imprimir uma\nMAIL, abra ela e\vaperte START.",
  ["43:48e0"] = "DON: Vou\nvencer! Não me\vatrapalhe.",
  ["43:4907"] = "ED: Meu PARASECT\nfaz POKéMON\vdormir com SPORE.",
  ["43:4937"] = "NICK: Crio\nPOKéMON rápidos\vpara batalhas.",
  ["43:4960"] = "WILLIAM: Não me\nimporto em\vvencer.\fSó procuro\nPOKéMON raros.",
  ["43:49a9"] = "BENNY: Ssh!\nVai espantar o\fSCYTHER. Falo\ncom você depois.",
  ["43:49e6"] = "BARRY: Você\ndeve enfraquecer\fPOKéMON inseto,\njogue POKé BALL.",
  ["43:4a25"] = "CINDY: O que foi?\fAcha engraçado\numa garota\fcaçando POKéMON\ninseto?",
  ["43:4a70"] = "JOSH: Coleciono\nPOKéMON inseto\fdesde que era\nbem criança.\fNão tem jeito,\nvou vencer!",
  ["43:4acd"] = "SAMUEL: Se tem\ntempo para\fconversar, procure\nPOKéMON inseto.",
  ["43:4b0c"] = "KIPP: Estudei\nmuito sobre\vPOKéMON inseto.\fVou vencer\ncom certeza.",
  ["43:4b4f"] = "RELAXATION SQUARE\nNATIONAL PARK",
  ["43:4b70"] = "O que é este\naviso?\fBatalhe apenas\nna grama.\fNATIONAL PARK\nWARDEN'S OFFICE",
  ["43:4bc5"] = "DICAS DE TREINO\fImprima MAIL\nabrindo-o e\vapertando START.",
  ["43:4e1f"] = "Bem-vindo!",
  ["43:4e29"] = "Olá. Sinto muito,\nmas hoje não temos\vvisitas guiadas\vdisponíveis.",
  ["43:4e62"] = "Oi, você veio pelo\nLUCKY NUMBER\vSHOW?\fQuer que eu veja\nos números de ID\vdos seus POKéMON?\fSe der sorte, você\nganha um prêmio.",
  ["43:4ee2"] = "O ID da semana é\n{STRBUF}.",
  ["43:4f02"] = "Vamos ver se você\nacertou algum.",
  ["43:4f21"] = "……\n……",
  ["43:4f26"] = "Volte semana que\nvem para o próximo\vLUCKY NUMBER.",
  ["43:4f5d"] = "Uau! Você acertou\nos cinco números\vem cheio!\fTemos um ganhador\ndo grande prêmio!\fVocê ganhou uma\nMASTER BALL!",
  ["43:4fcb"] = "Ei! Você acertou\nos três últimos\vnúmeros!\fGanhou o segundo\nprêmio, um EXP.\vSHARE!",
  ["43:501e"] = "Ooh, você acertou\nos dois últimos\vnúmeros.\fGanhou o terceiro\nprêmio, um PP UP.",
  ["43:5068"] = "Não, nenhum dos\nseus IDs combina.",
  ["43:508e"] = "Não há espaço para\no seu prêmio.\fAbra espaço e\nvolte logo aqui.",
  ["43:50d5"] = "Temos uma promoção\nde quiz especial\vrolando agora.\fAcerte cinco per-\nguntas e ganhe um\vRADIO CARD.\fEncaixe ele na sua\nPOKéGEAR e toque\fo rádio a qualquer\nhora e lugar.\fQuer responder ao\nquiz?",
  ["43:519a"] = "Pergunta 1:\fO TOWN MAP pode\nser exibido em uma\vPOKéGEAR?",
  ["43:51d1"] = "Correto!\nPergunta 2:\fNIDORINA pode ser\nsomente fêmea?",
  ["43:5204"] = "Na mosca!\nPergunta 3:\fO KURT, artesão de\nPOKé BALLS, usa\vAPRICORNS?",
  ["43:524d"] = "Até aqui tudo bem!\nPergunta 4:\fMAGIKARP não sabe\naprender TM?",
  ["43:528b"] = "Uau! Certo de novo\nEsta é a última\vpergunta:\fPROF.OAK'S POKéMON\nTALK é um programa\vmuito popular.\fA MARIE é a co-\napresentadora?",
  ["43:530b"] = "Bingo! Acertou!\nParabéns!\fEste é seu prêmio,\num RADIO CARD!",
  ["43:5350"] = "A POKéGEAR de\n{PLAYER} agora toca\vrádio também!",
  ["43:5375"] = "Sintonize nossos\nshows de rádio.",
  ["43:5399"] = "Ah, que pena.\nSinto muito, mas\fvocê errou.\nTente de novo!",
  ["43:53d3"] = "Ah. Entendo. Tente\nde novo se mudar\vde ideia.",
  ["43:5403"] = "O BEN é um DJ\nfabuloso.\fA voz doce dele\nme derrete!",
  ["43:5439"] = "Adoro a MARY, do\nPOKéMON TALK.\fSó conheço a voz\ndela, mas nunca\va vi.",
  ["43:5481"] = "Finalmente\nassumimos a\vRADIO TOWER!\fAgora todos vão\nconhecer o terror\fde verdade da\nTEAM ROCKET!\fVamos mostrar\ncomo assustamos!",
  ["43:550f"] = "Muito forte! Nós\ntemos que vigiar…",
  ["43:552f"] = "É forte demais.\fNosso plano pode\nruir. Preciso\vavisar os outros…",
  ["43:5574"] = "1F RECEPÇÃO\n2F VENDAS\f3F PESSOAL\n4F PRODUÇÃO\f5F SALA DO\n   DIRETOR",
  ["43:55be"] = "LUCKY CHANNEL!\fGanhe com os IDs\ndos seus POKéMON!\fTroque POKéMON e\ncolecione IDs\vdiferentes!",
  ["43:570e"] = "Você pode ouvir\na radio em\vqualquer lugar.",
  ["43:5740"] = "Canções de ninar\nna radio podem\vfazer dormir.",
  ["43:576d"] = "Por que eles\nquerem tomar conta\vda RADIO TOWER?",
  ["43:57a0"] = "JIGGLYPUFF:\nJiggly…",
  ["43:57b5"] = "Desculpe. Somente\npessoal autorizado\valém daqui.\fNão era assim\nantes.\fAlgo esta errado\ncom o DIRETOR\v…",
  ["43:582e"] = "Sinta-se livre\npara olhar.\fO DIRETOR esta\nbom de novo,\vcomo era antes.",
  ["43:5885"] = "Há três anos, a\nTEAM ROCKET foi\vobrigada a parar.\fMas agora a volta\nvem com tudo!",
  ["43:58db"] = "Ugh! Não fica\nengraçadinho!",
  ["43:58f1"] = "Não vamos deixar\nvocê arruinar os\vnossos planos!",
  ["43:5923"] = "Somos TEAM ROCKET,\nos que exploram\vos POKéMON!\fAmamos ser\nmalvados! Medo?",
  ["43:596a"] = "Você acha que é\num herói?",
  ["43:5983"] = "Não somos sempre\nmalvados. Fazemos\vo que gostamos.",
  ["43:59b7"] = "Ei, ei! Sai do\nnosso caminho!",
  ["43:59d7"] = "Argh. Desisto.",
  ["43:59ea"] = "Nossos EXECUTIVOS\nestão tentando\vtomar este lugar.\fEles têm um plano\ngrande. Queria\vsaber o que é.",
  ["43:5a4e"] = "Hahaha!\fQue tédio.\nFoi fácil\fdemais tomar\neste lugar!\fVamos, me\ndivirta!",
  ["43:5aba"] = "Você me venceu e\nnão vou esquecer!",
  ["43:5ade"] = "2F VENDAS",
  ["43:5ae8"] = "TALK POKéMON\nDO PROF.OAK\fO Show Mais Quente\nno Ar!",
  ["43:5b1b"] = "Em Qualquer Lugar\nPOKéMON Radio",
  ["43:5cbf"] = "Temos gravações\ndos gritos de\ftodos os POKéMON\nencontrados.\fDevemos ter uns\n200 tipos.",
  ["43:5d20"] = "Para treinadores,\nPOKéMON são\vseus parceiros.\fE terrível como a\nTEAM ROCKET esta\ftentando controlar\nPOKéMON.",
  ["43:5d89"] = "Trabalhamos 24h\npor dia para\ftransmitir\nprogramas legais.\fVou dar o meu\nmelhor para\vtrabalhar!",
  ["43:5df2"] = "O chefe da TEAM\nROCKET trancou\vele mesmo lá.\fMas o DIRETOR\npode abrir.\fEle esta no\nquinto andar.\fSalve-o!",
  ["43:5e69"] = "O DIRETOR\nesta seguro?",
  ["43:5e80"] = "Obrigado!\nVocê e meu herói!\fIsto e um simbolo\nde gratidão.",
  ["43:5ebf"] = "E SUNNY DAY.\nFortalece\vmovimentos de fogo\vpor um tempo.",
  ["43:5efa"] = "Você foi\nmaravilhoso!",
  ["43:5f16"] = "Recebi ordens\nrígidas.\fVou esmagar quem\ndesafiar a TEAM\vROCKET!",
  ["43:5f6e"] = "Falhei no meu\ntrabalho…\fVou ter desconto\nno meu salário…",
  ["43:5fa2"] = "É ótimo mandar\nos POKéMON\vcometer crimes.",
  ["43:5fd2"] = "Tá brincando!",
  ["43:5fe2"] = "Estou péssimo por\nter perdido!\fDroga! Odeio\nPOKéMON inúteis!",
  ["43:601b"] = "Por que a persiana\nabriu? Você tem\falgo a ver com\nisso?",
  ["43:6060"] = "Estou feito!",
  ["43:606e"] = "O quê?! Passou\npelos nossos,\vno UNDERGROUND?\fComo conseguiu?",
  ["43:60b2"] = "Uma criança\nperdida por aqui?\fQuem é você?",
  ["43:60e1"] = "Tsk! Eu te\nsubestimei!",
  ["43:60ff"] = "Bwahahaha…\fPosso transmitir\num sinal tão forte\vcomo eu precisar.",
  ["43:6100"] = "Bwahahaha…\fPosso transmitir\num sinal forte\vdaqui em diante.",
  ["43:6142"] = "E o slot da\nCHAVE-CARTAO.",
  ["43:615a"] = "{PLAYER} inseriu\na CHAVE-CARTAO.",
  ["43:6174"] = "3F PESSOAL",
  ["43:6182"] = "MÚSICA POKéMON\ncom o DJ BEN",
  ["43:62b0"] = "Ouvi a radio\nquando estava\vnas RUÍNAS.\fOuvi uma\ntransmissão lá.",
  ["43:6306"] = "MARY: Por que?\nPor que tenho que\vsofrer com isso?\fMEOWTH me ajuda!",
  ["43:6349"] = "MARY: Oh! Você e\nmeu salvador!\fVai aceitar isso\ncomo obrigada?",
  ["43:638d"] = "MARY: E perfeito\npara POKéMON\fque conhecem\nataques normais.",
  ["43:63ca"] = "MARY: Por favor,\nsintonize no\fmeu programa\nTALK POKéMON.",
  ["43:6404"] = "MEOWTH: Meowth…",
  ["43:6415"] = "Pretende salvar\no DIRECTOR?\fIsso não será\npossível, pois vou\vte derrotar!",
  ["43:646d"] = "Não pode ser!",
  ["43:6480"] = "Não acredito!\nFui derrotado!",
  ["43:64a2"] = "Pare! Sou\nconhecido como a\vfortaleza da TEAM\fROCKET! Você\nnão vai passar!",
  ["43:64ee"] = "A fortaleza\ncaiu!",
  ["43:6507"] = "Você ganhou meu\nrespeito, então\vvai um conselho.\fNão é tarde.\nVocê ainda pode\vvoltar.",
  ["43:6562"] = "Não acho os\nPOKéMON fofos?\fVou achar os meus\nfofos, depois que\fderrotarem os\nseus!",
  ["43:65b3"] = "Ah, não! Eles são\ntão inúteis!",
  ["43:65cf"] = "Eu amo a minha\nbeleza!\fQuem liga para\nos POKéMON?",
  ["43:6600"] = "Excelente.\fEsta RADIO TOWER\nira realizar\vnosso plano.",
  ["43:6641"] = "Hmmm…\fOs grandes planos\ntêm percalços.",
  ["43:665f"] = "Eu não acho que\nPOKéMONS são\vbonitos?\fAcharei meus\nPOKéMONS bonitos\vdepois de vencerem\vos seus!",
  ["43:6669"] = "Você acredita\nmesmo que pode\vparar a TEAM?",
  ["43:669c"] = "4F PRODUCAO",
  ["43:66ab"] = "4F ESTUDIO 2",
  ["43:686a"] = "V-Você! Você veio\nme resgatar?",
  ["43:6889"] = "Era isso que você\nesperava?\fErrado!\nSou um impostor!\fFingi ser o\nverdadeiro para\fpreparar\nnossa tomada.\fQuer saber onde\nescondemos o\vDIRETOR mesmo?\fClaro, vou te\ncontar. Mas só\vse me vencer!",
  ["43:6965"] = "Tudo bem. Vou te\ncontar.",
  ["43:6988"] = "Escondemos o\nDIRETOR real\fno ARMAZEM\nSUBTERRANEO.\fE na ponta do\nSUBTERRANEO.\vMas duvido\fque você\nchegue lá.",
  ["43:6a0d"] = "Oi, garoto.\nLembra de mim do\fHIDEOUT em\nMAHOGANY TOWN?\fEu perdi lá, mas\nagora não perco.",
  ["43:6a59"] = " não.",
  ["43:6a70"] = "Isso não pode\nser verdade!\fLutei duro, mas\nainda perdi…",
  ["43:6aaa"] = "{PLAYER}, não é?\fUm pirralho como\nvocê não vai\fapreciar a\nmagnificência da\fTEAM ROCKET.\nQue pena. Eu\vadmiro seu poder.",
  ["43:6b23"] = "Oh? Você conseguiu\nchegar até aqui?\fVocê deve ser um\nbom treinador.\fNossos planos são\ntomar esta RADIO\fESTACAO e anunciar\nnosso retorno.\vIsso deve trazer\fnosso chefe\nGIOVANNI de volta\fde seu treinamento\nsolo.\fVamos recuperar\nnossa glória\vanterior.\fNão vou permitir\nque você atrapalhe\vnossos planos.",
  ["43:6c45"] = "Não! Perdoe-me,\nGIOVANNI!",
  ["43:6c60"] = "Como pode ser?\fNossos sonhos se\ntornaram nada.\fNão fui a altura\nda tarefa afinal.\fComo GIOVANNI fez\nantes de mim,\fvou dissolver a\nTEAM ROCKET hoje.\fAdeus.",
  ["43:6d04"] = "DIRETOR: {PLAYER},\nobrigado!\fSuas ações\ncorajosas\fsalvaram POKéMON\nem todo o pais.\fSei que não e\nmuito, mas por\vfavor, aceite.",
  ["43:6d7e"] = "Costumava haver\numa torre bem aqui\vem GOLDENROD CITY\fMas era velha e\nrangida.\fEntão a troca-\nmos pela RADIO\vTOWER. Na demoli-\fcão, encontramos\nisso no topo.\vOuvi que um\fPOKéMON gigante\ncostumava voar\fsobre GOLDENROD.\nTalvez tenha\fcaido de um\nPOKéMON.\fTalvez como o que\naparece na\fTIN TOWER em\nECRUTEAK CITY.\fBom, vou ao meu\nESCRITORIO.",
  ["43:6ee3"] = "Costumava haver\numa torre bem aqui\vem GOLDENROD CITY\fMas era velha e\nrangida.\fEntão a troca-\nmos pela RADIO\vTOWER. Na demoli-\fcão, encontramos\nisso no topo.\vOuvi que um\fPOKéMON gigante\ncostumava voar\fsobre GOLDENROD.\nTalvez tenha\fcaido de um\nPOKéMON. Talvez\fcomo o que\nveio das WHIRL\fISLANDS perto de\nCIANWOOD.\fBom, vou ao meu\nESCRITORIO.",
  ["43:7049"] = "DIRETOR: Ola,\n{PLAYER}!\fSabe, eu amo\nPOKéMON.\fConstrui esta\nRADIO TOWER para\fexpressar meu amor\npor POKéMON.\fSeria bom se as\npessoas curtissem\vnossos programas.",
  ["43:706a"] = "uê?!",
  ["43:70e3"] = "BEN: Você ouve\nnossa música?",
  ["43:7105"] = "5F ESCRITORIO\nDO DIRETOR",
  ["43:711e"] = "5F ESTUDIO 1",
  ["43:8900"] = "o\vtumbas de reis.\fComo as pirâmides,\npor exemplo.",
  ["43:8e00"] = "nhos nas\vRUÍNAS?\fEles se parecem\nmuito com aqueles\vdesenhos das\vparedes de lá.\fHum…Isso deve\nsignificar que\vexistem muitos\vtipos deles…",
  ["43:9346"] = "FLASH!",
  ["43:9d00"] = "descontar toda\vminha raiva em\vvocê!",
  ["43:a200"] = "quipado com a\vPEDRA DO REI é\vmuitas vezes\vmordido por um\vSHELLDER.\fEi, eu vou dividir\nessa PEDRA DO REI\vcom você.",
  ["43:a744"] = "IVINE, \veu vou ao GINÁSIO.\fO tipo de POKéMON\nda LÍDER DO\vGINÁSIO mudou e\veu nem havia\vpercebido.",
  ["43:a95a"] = "IA\vem CIANWOOD.",
  ["43:d200"] = "\vneste lugar agora.\fTemos planos\nmaiores.\fEm breve\nvocê apreciará o\vverdadeiro poder\vda EQUIPE ROCKET.\fDivirta-se\nenquanto puder…\fHahahaha…",
  ["43:d25f"] = ",\vvocê poderia ser\vEXECUTIVO.",
  ["43:d759"] = " para se\ntornar um MESTRE\vPOKéMON é longa e\vdifícil.\fSabendo disso,\nvocê pretende\vcontinuar?\f…\fEntendo. Não, você\ntem razão.\fSe desistisse\nfacilmente, você\vnunca teria\vseguido o sonho do\vprimeiro lugar.\fEu espero vê-lo\nnovamente!",
  ["43:e600"] = "…\fEssa idéia me\nentusiasma!",
  ["44:409f"] = "Hm? Isso é uma\nPOKéDEX, não é?\vPosso ver?\fHá muitos\ntipos de POKéMON.\fHm? O que é isto?\fQue POKéMON\né este?\fParece a escrita\nestranha nas\fparedes das\nRUINS.\fSe esses desenhos\nsão mesmo POKé-\vMON, deve haver\vmuitos mais.\fSei! Vou\natualizar sua\vPOKéDEX. Siga-me.",
  ["44:41bd"] = "O que você quer?\nEstou estudando,\vnão me atrapalhe!",
  ["44:41ef"] = "Desculpe…\nEstou frustrado\fpela nossa falta\nde entendimento…",
  ["44:4228"] = "As RUÍNAS são de\nuns 1500 anos\vatrás.\fNinguém sabe quem\nconstruiu.\fTambém não se sabe\nse as estátuas de\vPOKéMON têm algum\vsignificado.\fÉ tudo um grande\nmistério…",
  ["44:42c3"] = "Hmmm… Este é um\nlugar estranho.",
  ["44:42e6"] = "Gosto de pensar\naqui.",
  ["44:42fd"] = "MYSTERY STONE\nPANEL CHAMBER",
  ["44:431a"] = "RUÍNAS DE ALPH\nBem-vindos!",
  ["44:433a"] = "RUÍNAS DE ALPH\nCENTRO PESQUISA\fA Autoridade nas\nRUÍNAS DE ALPH",
  ["44:443c"] = "É uma réplica\nde um POKéMON\vantigo.",
  ["44:4461"] = "Um POKéMON que\nvoava com\felegância em\nasas coloridas.",
  ["44:4516"] = "Bem-vindo a esta\ncâmara.\fHá painéis\ndeslizantes que\fretratam um\nPOKéMON antigo.\fDeslize os\npainéis para\vformar a figura.\fÀ direita, a\ndescrição do\vPOKéMON.",
  ["44:4553"] = "m POKéMON.\fMova o painel para\nformar uma figura.\fAo lado direito,\nhá a descrição\vdesse POKéMON.",
  ["44:45cb"] = "É uma réplica\nde um POKéMON\vantigo.",
  ["44:45f0"] = "Um POKéMON que\nse escondia no\ffundo do mar.\nolhos nas costas.",
  ["44:46bb"] = "É uma réplica\nde um POKéMON\vantigo.",
  ["44:46e0"] = "Este POKéMON\nflutuava no mar,\fgirando seus\ndez tentáculos.",
  ["44:4795"] = "É uma réplica\nde um POKéMON\vantigo.",
  ["44:47ba"] = "Este POKéMON\nvoador atacava\fa presa com\ndentes de serra.",
  ["44:484a"] = "Há uma presença\nestranha aqui…",
  ["44:486d"] = "Esta sala é\ngrande, mas não\vhá nada aqui.",
  ["44:489b"] = "Este lugar tem\numa qualidade\vmística.\fParece até\netéreo.",
  ["44:48e5"] = "Prédios antigos\nsão túmulos de\vreis.\fComo as\npirâmides.",
  ["44:4900"] = "o\vtumbas de reis.\fComo as pirâmides,\npor exemplo.",
  ["44:4933"] = "É uma réplica\nde um POKéMON\vantigo.",
  ["44:4b1e"] = "Pronto!\fModifiquei sua\nPOKéDEX.\fAdicionei uma\nPOKéDEX opcional\fpara guardar\ndados de UNOWN.\fEla registra\nna ordem em\vque os pegou.",
  ["44:4bb7"] = "Os UNOWN que\nvocê pegar serão\vtodos registrados\fVerifique quantos\ntipos existem.",
  ["44:4c05"] = "Você pegou todos\nos UNOWN?\fQue grande\nconquista!\fPreparei a\nimpressora para\vlidar com UNOWN.\fUse quando\nquiser.",
  ["44:4c93"] = "As RUÍNAS tem\ncerca de 1500 anos\vMas não se sabe\fpor que foram\nconstruídas, \vnem por quem.",
  ["44:4ceb"] = "Quantas espécies\nPOKéMON estão nas\vRUÍNAS, será?",
  ["44:4d1e"] = "POKéMON apareceram\nnas RUÍNAS?\fQue noticia\nincrível!\fVamos precisar\ninvestigar isso.",
  ["44:4d71"] = "Há padrões\ndesenhados nas\fparedes das\nRUÍNAS.\fDevem ser a chave\npara desvendar\vo mistério\vdas RUÍNAS.",
  ["44:4ded"] = "Os POKéMON\nque você viu nas\vRUÍNAS?\fParecem muito com\nos desenhos nas\fparedes de lá.\n…Hm…\fIsso quer dizer\fexistem muitas\nespécies\vdeles…",
  ["44:4e8b"] = "RUÍNAS DE ALPH\fExploração\nAno 10",
  ["44:4eae"] = "POKéMON misterioso\nNome: UNOWN\fUm total de 26\ntipos achados.",
  ["44:4ee3"] = "Parece que ainda\nnão funciona.",
  ["44:4f02"] = "UNOWN podem\nser impressos.",
  ["44:4f1d"] = "É uma foto do\nfundador do\fCENTRO DE PESQUISA\nPROF.SILKTREE.",
  ["44:4f5b"] = "Ha muitos livros\nacademicos.\fRuínas Antigas…\nMistérios dos\vAntigos…",
  ["44:50bd"] = "Muito bem, então!\nEu decidi.\fNão vou sair daqui\naté meus POKéMON\vficarem fortes!",
  ["44:5106"] = "Eu ando por toda\nparte procurando\vPOKéMON.\fVocê também está\nprocurando?\fEntão você é meu\nrival de coleção!",
  ["44:516c"] = "Ugh. Meus pobres\nPOKéMON…",
  ["44:5182"] = "Toda sexta dá para\nouvir rugidos de\fPOKéMON lá do\nfundo da caverna.",
  ["44:51c4"] = "Uau! Que\nsurpresa!\fNão esperava ver\nninguém aqui!",
  ["44:51ff"] = "Uau! Fui derrotado\nfeio!",
  ["44:521a"] = "Fui enganado e\ncomprei uma SLOW-\vPOKETAIL.\fTenho pena do\npobre POKéMON.",
  ["44:5266"] = "O SUPERSONIC dos\nZUBAT vive dei-\vxando eu confuso.\fIsso me irrita\nmuito mesmo!",
  ["44:52c0"] = "No fim de semana\ndá para ouvir\frugidos estranhos\nlá no fundo.",
  ["44:5300"] = "Com luz, caverna\nnão assusta.\fSe você é forte,\nPOKéMON também\vnão assustam.",
  ["44:534d"] = "É o fogo do meu\nPOKéMON que acende\vesta caverna.",
  ["44:54c4"] = "Estou perdido faz\nmuito tempo…\fNão me importo de\nficar aqui, mas\vque fome!",
  ["44:5510"] = "Veja só!\nUma visita!",
  ["44:552e"] = "Uahahah! Você é\ndanado!",
  ["44:554c"] = "Eu moro aqui.\fVocê também pode,\nse quiser.\fTem espaço de\nsobra, sabe.",
  ["44:559b"] = "Quem está aí?\fDeixe eu e meus\nPOKéMON em paz!",
  ["44:55d2"] = "Só eu e os meus\nPOKéMON. Estou\vlouco de alegria.",
  ["44:5601"] = "Vim de tão longe\npara fazer minha\vpesquisa POKéMON.\fDeixe eu mostrar\no que descobri\vnuma luta real!",
  ["44:5668"] = "Você demonstrou\nem mim!",
  ["44:5681"] = "Devo reunir e\ndivulgar o que\vdescobri.\fQuem sabe eu fique\nfamoso como o\vPROF.ELM.",
  ["44:5826"] = "Você tem um\nestilo brilhante!",
  ["44:5841"] = "Seu estilo POKéMON\né impressionante\ve colorido, sim.\fVocê só vai\nmelhorar!",
  ["44:5859"] = "no chão\né um lixo.\fLeve-o se você\nquiser!",
  ["44:5895"] = "Estou treinando.\nTopa uma partida?",
  ["44:58b8"] = "Aah, não! Você é\nbom demais.",
  ["44:58d9"] = "Vou treinar\nsozinho até eu\vmelhorar.",
  ["44:5907"] = "Se o POKéMON que\neu gosto estivesse\vlá, eu iria.\fÉ o que um treina-\ndor faz.",
  ["44:5958"] = "Prefiro fazer\ncarinho neles!",
  ["44:597c"] = "Uma vez por semana\num POKéMON vem\vaté a beira.\fEu queria ver\nesse POKéMON…",
  ["44:5b06"] = "KURT: Olá aí,\n{PLAYER}!\fOs guardas lá em\ncima fugiram\vquando eu gritei.\fMas aí eu caí\npoço abaixo\vaqui.\fBati as costas\ncom força e agora\vnão consigo andar\fDroga! Se eu\nestivesse bem, o\fPOKéMON teria dado\no troco…\fAh, não tem\njeito.\f{PLAYER}, mostre a\neles a sua coragem\vno meu lugar!",
  ["44:5c1d"] = "KURT: Muito bem,\n{PLAYER}!\fA TEAM ROCKET\nfoi embora.\fMinhas costas\nmelhoraram. Vamos\vsair daqui.",
  ["44:5c78"] = "Droga! Eu estava\nde guarda lá em\fcima quando um\nvelho gritou.\fMe assustou tanto\nque eu caí aqui\vembaixo.\fAcho que vou\ndescontar a raiva\vem você!",
  ["44:5d1f"] = "Arrgh! Hoje NÃO é\no meu dia!",
  ["44:5d3b"] = "Sim, a gente vem\ncortando o rabo\fdos SLOWPOKE e\nvendendo elas.\fTudo o que fazemos\né por lucro.\fIsso mesmo!\nSomos a TEAM\fROCKET, e fazemos\ntudo por grana!",
  ["44:5dde"] = "O que você quer?\fSe atrapalhar o\nnosso trabalho,\vnão terá piedade!",
  ["44:5e23"] = "Você foi bem hoje\npirralho, mas es-\vpere a próxima!",
  ["44:5e54"] = "É, a TEAM ROCKET\nfoi desfeita\vhá três anos.\fMas continuamos\ncom as atividades\vescondidos.\fAgora divirta-se\nvendo a gente\vaprontar!",
  ["44:5ee5"] = "Parar de tirar\nSLOWPOKETAILS?\fSe obedecêssemos,\na fama da TEAM\vROCKET acabava!",
  ["44:5f00"] = " RABOS DOS\vSLOWPOKES?\fSe a EQUIPE ROCKET\nte obedecer, nossa\vreputação seria\varruinada!",
  ["44:5f37"] = "Simplesmente…\nForte demais…",
  ["44:5f4a"] = "A gente precisa da\ngrana, mas vender\vSLOWPOKETAILS?\fÉ duro ser um\nROCKET GRUNT!",
  ["44:5f9b"] = "Parar as TAILS?\fÉ, tente vencer\ntodos nós então!",
  ["44:5fd3"] = "Seu pirralho!",
  ["44:5fe5"] = "SLOWPOKETAILS\ncrescem rápido!\fQual o problema\nde vender elas?",
  ["44:6023"] = "Um SLOWPOKE com a\nTAIL cortada…\fHã? Tem uma MAIL.\nLer?",
  ["44:6061"] = "{PLAYER} leu a\nMAIL.\fSeja bom e cuide\nda casa com o\fvovô e o\nSLOWPOKE.\fCom amor, papai",
  ["44:60b9"] = "Um SLOWPOKE com a\nTAIL cortada…",
  ["44:6182"] = "Espero o momento\nde evolução do\vSLOWPOKE.\fPelas minhas\nobservações,\vdescobri algo.\fUm SLOWPOKE com\numa KING'S ROCK\fé mordido por\num SHELLDER.\fAqui, vou te\ndar uma KING'S\vROCK.",
  ["44:624a"] = "Vou ser como\no SLOWPOKE.\fEsperarei com\npaciência para\vver um evoluir.",
  ["44:62c5"] = "As pessoas treinam\nneste LIGHTHOUSE.\fNão é fácil subir\npor causa de todos\vos treinadores.",
  ["44:631a"] = "Antigamente, POKé-\nMON iluminavam\fo mar em volta de\nOLIVINE à noite.\fO LIGHTHOUSE foi\nfeito em honra a\vesses POKéMON.",
  ["44:64af"] = "Que força!\nQue tal você\fnavegar os mares\ncomigo?",
  ["44:64e9"] = "Hm? Aqui não é\nlugar de brincar.",
  ["44:650c"] = "Ah! Dá para ver\nque você é sério.",
  ["44:652f"] = "Lá em cima tem um\nPOKéMON que mantém\vo farol aceso.\fMas ouvi que ele\nestá doente e\fnão sara com\nremédio comum.",
  ["44:666e"] = "Você se importa\nde verdade…",
  ["44:6689"] = "Como diabos se\nsobe aqui?\fQuero visitar o\nPOKéMON doente,\fmas não consigo\nchegar lá…",
  ["44:66dd"] = "Marinheiros são\nbons e fortes.\vE você?",
  ["44:670f"] = "Você é bom e\nforte também…",
  ["44:672e"] = "Toda vez que volto\na OLIVINE, eu\vvisito o GINÁSIO.\fO tipo de POKéMON\nda LÍDER mudou\fsem que eu\npercebesse.",
  ["44:679e"] = "Viajo o mundo\npara treinar meus\vPOKéMON. Quero\vbatalhar com você",
  ["44:67e1"] = "…suspiro… Preciso\ntreinar mais…",
  ["44:6801"] = "A JASMINE usava\nPOKéMON de pedra\vcomo o ONIX.",
  ["44:690f"] = "Eu também não\nconsigo sorrir…",
  ["44:692e"] = "Falando em doente,\nouvi que tem\fuma boa farmácia\nem CIANWOOD.",
  ["44:696f"] = "A JASMINE é a\nLÍDER daqui.\fPretendo trazer\nela de volta.\fÉ melhor ninguém\natrapalhar!",
  ["44:69d5"] = "Aaai! POKéMON!",
  ["44:69e6"] = "Certo. Qualquer um\nficaria preocupado\vse o POKéMON dele\vestivesse ferido.\fVou rezar pelo\nPOKéMON daqui,\fpara a JASMINE\nvoltar ao GINÁSIO",
  ["44:6b3a"] = "Uau, uau. Você é\narrasador!",
  ["44:6b5b"] = "Um LÍDER não é só\nquestão de ser\fforte. Um LÍDER\ntambém precisa ter\vcompaixão.",
  ["44:6bb0"] = "Estamos bem alto\naqui. Meus\fPOKéMON pássaro\nem plena forma.",
  ["44:6beb"] = "Opa…Eles caíram…",
  ["44:6bff"] = "Meu POKéMON apren-\ndeu a usar FLY em\vCIANWOOD.\fBom, como eu perdi\nvou usar FLY para\vcruzar o mar…",
  ["44:6c51"] = "a voando.",
  ["44:6dbd"] = "JASMINE: … Este\nPOKéMON sempre\fmanteve o mar\naceso à noite.\f…Mas ele\nadoeceu… Está\vofegando…\f…Sei que há\numa ótima\fPHARMACY em\nCIANWOOD…\fMas isso fica\nalém do mar…\fE não posso\ndeixar o AMPHY…",
  ["44:6ea0"] = "…Pode buscar\num remédio para\vmim? Por favor?",
  ["44:6ed5"] = "JASMINE: …Este\nremédio curará\vo AMPHY?",
  ["44:6eff"] = "{PLAYER} entregou\na SECRETPOTION\va JASMINE.",
  ["44:6f26"] = "JASMINE: …Hum,\nnão se ofenda,\vpor favor…\f…AMPHY não\naceitará nada\vde mais ninguém…",
  ["44:6f80"] = "JASMINE: …\fAMPHY, como você\nse sente?",
  ["44:6fa8"] = "JASMINE: …Oh,\nque alívio…\fÉ tão\nmaravilhoso…\fMuito, muito\nobrigada.\f…Voltarei\nao GYM…",
  ["44:701b"] = "JASMINE: …Vejo…",
  ["44:702d"] = "…AMPHY, aguenta!",
  ["44:7055"] = "A respiração\nestá difícil…",
  ["44:9f00"] = "e\vpoderoso…",
  ["44:a000"] = "me atrapalha…\fMe contou que eu\nnão amo e confio\vnos POKéMONS o\vbastante.\fEstou furioso por\nperder para um\vcoração mole como\vele.\f…Humph!\fEu não tenho tempo\npara os seus\vgostos!",
  ["44:a164"] = "sumir\vo comando.\n    \fPor isso estamos\nem alerta.\fNão deixarei\nninguém perturbar\vesse lugar!",
  ["44:c455"] = "essa PEDRA DO REI\vcom você.",
  ["44:d500"] = "ra\vdestruir a EQUIPE\vROCKET.",
  ["44:d569"] = "uele olhar\vassustado.\fEu vou lhe\ndar algo que o\vassustará!",
  ["45:4126"] = "Arrgh… Você achou\na escada\vsecreta…",
  ["45:414f"] = "Heheh! O experi-\nmento funcionou\vque é uma beleza.\fMAGIKARP não valem\nnada, mas\fGYARADOS dão muito\ndinheiro.",
  ["45:41bc"] = "Urrgh…\fOs POKéMON dragão\ndele são fortes…",
  ["45:41e5"] = "LANCE: DRAGONITE,\nHYPER BEAM.",
  ["45:4204"] = "Por que demorou,\n{PLAYER}?\fComo eu pensei, o\nsinal de rádio\festranho vem\ndaqui.",
  ["45:4259"] = "A escada está\nbem aqui.",
  ["45:4275"] = "LANCE: {PLAYER},\nvamos nos separar\fpara vasculhar.\nEu vou primeiro.",
  ["45:47cd"] = "Ei!\nInvasor à vista!",
  ["45:47e3"] = "Droga… Eu falhei…",
  ["45:47f4"] = "Minha vez!\nNão tem saída!",
  ["45:4814"] = "Tem câmeras nas\nestátuas de\vPOKéMON.\fVamos aparecendo\naté você achar um\vbotão secreto.",
  ["45:4876"] = "Isto já foi um\nesconderijo ninja\fTem armadilhas\npara confundir\vinvasores.",
  ["45:48d1"] = "Está bem. Vou\ncontar um segredo\vdo esconderijo.\fAquilo no chão ali\nna frente é um\vpainel de salto\fSe você pisar,\nvai ser mandado\fde volta para a\nentrada.",
  ["45:4900"] = "jo.\fAquilo no chão\nafrente é o painel\vde teletransporte.\fSe pisá-lo, você\nvoltará para a\ventrada.",
  ["45:4972"] = "Heheh. Está se\nachando sortudo?\fVai lá, dê mais\num passo.\fTemos armadilhas\npostas no chão!",
  ["45:49d6"] = "Eu nem sei onde\nas armadilhas\vestão.\fVocê vai ter que\njuntar coragem\ve caminhar.",
  ["45:4a37"] = "É uma estátua de\nPERSIAN…\fOs olhos dela são\nmuito brilhantes.",
  ["45:4a68"] = "Um botão secreto!\nMelhor apertar.",
  ["45:4a8b"] = "O botão está\ndesligado.",
  ["45:4f65"] = "Pare bem\naí!",
  ["45:4f7b"] = "Não podemos ter um\npirralho como você\vsolto por aí.\fFaz mal para o\norgulho da TEAM\vROCKET, sabe.\fPor mais forte que\nseja, não dá para\fencarar nós dois\nao mesmo tempo.\fSinto muito, bebê.\nPrepare-se para\vapanhar.",
  ["45:5044"] = "Ei! Não seja tão\negoísta. Divida a\vdiversão.",
  ["45:5075"] = "O quê? Você tinha\num cúmplice?\fCadê o seu\nsenso de honra?\fComo chefe\ninterino no lugar\fdo GIOVANNI, vou\nmostrar o erro\fque é se meter\ncom a TEAM ROCKET",
  ["45:5114"] = "Tch, você é forte\nmesmo.\fQue pena.\fSe você entrasse\nna TEAM ROCKET,\fpodia virar um\nEXECUTIVO.",
  ["45:517e"] = "…Este esconderijo\njá era…\fMas tudo bem.\nO experimento de\vtransmissão foi um\vsucesso total.\fNão importa mais\no que acontece\vcom este lugar.\fTemos planos bem\nmaiores.\fVocê vai conhecer\no verdadeiro\fpoder da TEAM\nROCKET em breve.\fAproveite enquanto\npode…\fFufufufu…",
  ["45:5290"] = "LANCE: É isso.\nDerrotamos todos\fos ROCKETS\ndaqui.\fMas estou preocu-\npado com o rapaz\fcom quem batalhei\nno caminho…",
  ["45:5306"] = "Desculpe, {PLAYER}\nVi como você ia\fbem, então eu só\nfiquei de fora.\fAgora só falta\numa coisa:\fdesligar aquele\nsinal de rádio.",
  ["45:5387"] = "É esta máquina\nque está causando\vtodo o problema.\fNão vejo nenhum\nbotão nela…\fNão temos escolha.\nVamos ter que\fderrubar todos os\nELECTRODE.\fIsso deve impedir\na máquina de\ftransmitir aquele\nsinal estranho.\fOs POKéMON não têm\nculpa, então isso\fme deixa com\nremorso.\f{PLAYER}, vamos\ndividir a tarefa.",
  ["45:54a2"] = "LANCE: Deixe este\nlado comigo.",
  ["45:54c1"] = "LANCE: Aquele\nsinal estranho\vfinalmente parou.\fO LAKE deve estar\nnormal de novo.\fVocê é o herói!\nMuito obrigado\fem nome de todos\nos POKéMON.\fAh, sim. Você\ndevia levar isto.\fAchei aqui, mas\nnão tenho uso\vnenhum para isso.",
  ["45:559e"] = "{PLAYER} recebeu\no HM06.",
  ["45:55b0"] = "É o WHIRLPOOL.\nEnsine para um\fPOKéMON e cruze\náguas revoltas.\fMas lembre-se\nde uma coisa.\fSó dá para usar\nfora de batalha\fcom a BADGE do\nGINÁSIO MAHOGANY.",
  ["45:564c"] = "{PLAYER}…\fO caminho até se\ntornar MESTRE\fPOKéMON é longo e\ndifícil.\fSabendo disso,\nvocê vai seguir?\f…\fEntendo. Não, você\ntem razão.\fSe desistisse\nassim tão fácil,\fnunca teria\ncorrido atrás\fdesse sonho para\ncomeçar.\fEspero ver você\nde novo!",
  ["45:574f"] = "LANCE: Você está\nbem?\fSeus POKéMON estão\nmachucados.\fTome, dê um pouco\ndo meu remédio\vpara eles.",
  ["45:57af"] = "LANCE: {PLAYER},\nvamos dar o nosso\vmelhor por eles.",
  ["45:57da"] = "A porta não\nabre?\fOra, claro.\nPrecisa de uma\fsenha que só a\nTEAM ROCKET sabe.",
  ["45:5840"] = "Heh, eu sou só um\nGRUNT.\fEu não sei a\nsenha. Azar\vo seu.",
  ["45:5882"] = "Ah, uma criança?\nNão gosto disso,\fmas tenho que\neliminar você.",
  ["45:58d2"] = "Eu apanhei de uma\ncriança na última\vmissão também.\fQuando a gente\nestava roubando\fPOKéMON, um garoto\nruivo de olhar\fmau me\narrasou…",
  ["45:5968"] = "Seu pestinha\ninsuportável!",
  ["45:5989"] = "Heh, só o chefe\nsabe a senha\vdaquela porta.\fOnde está o chefe?\nSei lá. Vá\vprocurar você.",
  ["45:59f1"] = "A porta fechou…\fPrecisa de senha\npara abrir.",
  ["45:5a23"] = "A porta fechou…\f{PLAYER} digitou\na senha.\fA porta abriu!",
  ["45:5a5f"] = "É o transmissor\nde rádio que está\fmandando o sinal\nsinistro.\fEstá funcionando\na todo vapor.",
  ["45:5abb"] = "O transmissor de\nrádio finalmente\fparou a transmis-\nsão maligna.",
  ["45:5e2f"] = "LANCE: Precisa de\nduas senhas para\fentrar na sala\ndo chefe.\fSó uns poucos\nROCKETS conhecem\vessas senhas.\fAquele ROCKET ali\nteve a bondade\vde me contar.\f{PLAYER}, vamos\nbuscar as senhas.",
  ["45:5eeb"] = "Urrggh… O cara\nde capa é\vforte demais…",
  ["45:5f1d"] = "…\fEu não disse que\neu ia\fdestruir a TEAM\nROCKET?\f…Me diga, quem era\no cara de capa\fque usava POKéMON\ndragão?\fMeus POKéMON não\nforam páreo.\fNão ligo de ter\nperdido. Eu venço\fele com POKéMON\nmais fortes.\fO que me incomoda\né o que ele falou\fEle disse que eu\nnão amo e não\fconfio o bastante\nnos meus POKéMON.\fFico furioso de\nter perdido para\vum bonzinho.\f…Hunf! Não tenho\ntempo para gente\vcomo você!",
  ["45:60b6"] = "O quê? Quem é você\nEsta é a sala\fdo nosso líder,\nGIOVANNI.\fDesde que acabou\ncom a TEAM ROCKET\fhá três anos, ele\nestá treinando.\fMas temos certeza\nque ele volta\fum dia para\nassumir de novo.\fPor isso estamos\nde guarda.\fNão vou deixar\nninguém mexer\vneste lugar!",
  ["45:61c7"] = "Eu… Eu não pude\nfazer nada…\fGIOVANNI, por\nfavor me perdoe…",
  ["45:61fe"] = "Não, não posso\ndeixar isso me\fabalar. Preciso\navisar os outros…",
  ["45:623b"] = "MURKROW: A senha\né…\fSALVE GIOVANNI.",
  ["45:6265"] = "Se eu sei a\nsenha?\fTalvez.\fMas nenhum fracote\nvai conseguir!",
  ["45:62a7"] = "Está bem. Pare.\nEu conto.",
  ["45:62c7"] = "A senha da sala\ndo chefe é\fSLOWPOKETAIL.\fMas não adianta\nse você não tiver\vas duas senhas.",
  ["45:6327"] = "Ruarrr-rarr-rarr!\fVocê está me\ndesafiando?\fHah! Você é louco,\nmas tem coragem!\fDisso eu gosto!\fSe me vencer, eu\nconto para você\fuma senha da sala\ndo chefe!",
  ["45:63cd"] = "Ruarrr-rarr-rarr!\nVocê é bom!",
  ["45:63ed"] = "Ruarrr-rarr-rarr!\fA senha da sala\ndo chefe…\fAhn…, eu acho que\né RATICATE TAIL.",
  ["45:6443"] = "Eu trabalhava na\nSILPH, mas agora\fchefio a pesquisa\nda TEAM ROCKET.\fUma criança xereta\ncomo você precisa\vser punida.",
  ["45:64b8"] = "Um mero erro de\ntática me custou…",
  ["45:64d8"] = "Um sinal de rádio\nque enlouquece os\vPOKéMON…\fMeu experimento é\num sucesso total.\fMinha promoção\nestá garantida.\fEsta derrota não\nsignifica nada.",
  ["45:6562"] = "Não ligo se os\nPOKéMON sofrem\vcom a experiência",
  ["45:6595"] = "Pensar é o meu\nforte, não\vbatalhar.",
  ["45:65c0"] = "Se aumentarmos a\npotência do sinal\fde rádio para\ntransmitir longe…\fSó de pensar já\nme anima!",
  ["45:6626"] = "A porta fechou…\fPrecisa de duas\nsenhas para abrir",
  ["45:6659"] = "A porta fechou…\f{PLAYER} digitou\nas duas senhas.\fA porta abriu!",
  ["45:6a44"] = "Ah, cara… Meu\nchefe vai ficar\vfurioso…\fO FARFETCH'D que\nusa CUT nas\fárvores para o\ncarvão fugiu.\fNão dá para eu\nprocurar ele aqui\vna ILEX FOREST.\fÉ grande, escura\ne assustadora…",
  ["45:6b01"] = "Nossa! Muito\nobrigado mesmo!\fO POKéMON do meu\nchefe não me obe-\vdece porque eu não\vtenho BADGE.",
  ["45:6b57"] = "É o POKéMON que\nsumiu!",
  ["45:6b6e"] = "FARFETCH'D: Kwaa!",
  ["45:6b81"] = "Ah! O FARFETCH'D!\fVocê achou ele\npara nós, garoto?\fSem ele, a gente\nnão conseguiria\fusar CUT para\nfazer carvão.\fObrigado, garoto!\fComo posso\nagradecer…\fJá sei! Tome,\nfique com isto.",
  ["45:6c29"] = "É o HM de CUT.\nEnsine a um\fPOKéMON para\ncortar arvoretas.\fClaro, você\nprecisa da BADGE\fdo GINÁSIO de\nAZALEA para usar.",
  ["45:6ca8"] = "Quer virar meu\naprendiz\fde carvoeiro\ncomigo?\fEm dez anos você\nestará craque!",
  ["45:6d03"] = "O que eu faço?\fSacudo árvores\ncom HEADBUTT.\fÉ divertido. Tente\nvocê também!",
  ["45:6d55"] = "Sacuda as árvores\ncom HEADBUTT. Às\vvezes cai um\vPOKéMON dormindo.",
  ["45:6d97"] = "A ILEX FOREST tem\ntanta árvore que\fnão dá para ver\no céu.\fFique de olho em\nitens que possam\vter caído por aí.",
  ["45:6e11"] = "SANTUÁRIO da ILEX\nFOREST…\fÉ em honra ao\nprotetor da\vfloresta…",
  ["45:9d00"] = "osso confiar.\fPor favor, salve\na TORRE DE RÁDIO…\fE toda a nação\nPOKéMON!",
  ["45:a762"] = "or preciso.",
  ["45:cd49"] = "u, certo?",
  ["45:cd63"] = "\najuda golpes do\vtipo escuro.",
  ["46:4334"] = "Acho que tenho que\nfazer as coisas\vdireito…",
  ["46:4362"] = "Você leva o tipo\nem conta durante\va batalha?\fSe souber as\nvantagens do tipo\fvai se sair melhor\nna batalha.",
  ["46:43d8"] = "Eu sei as vanta-\ngens de tipo.\fMas eu só uso um\ntipo de POKéMON.",
  ["46:441a"] = "Meus POKéMON\nacabaram de tosar\fVou mostrar como\neles são fortes!",
  ["46:4462"] = "Seus POKéMON vão\ngostar mais de\fvocê se der um\ntrato no pelo.",
  ["46:449b"] = "Acho que você tem\nuns POKéMON raros\vaí com você.\fDeixe eu ver!",
  ["46:44d7"] = "Gaah! Eu perdi!\nQue raiva!",
  ["46:44f9"] = "Está fazendo uma\nPOKéDEX? Aqui vai\vuma dica boa.\fO HIKER da ROUTE\n33, o ANTHONY, é\vgente boa.\fEle te liga se vir\nalgum POKéMON\vraro.",
  ["46:4500"] = "ompletando a\vPOKéDEX?\fAqui vai uma dica!\fO ANDARILHO\nANTHONY, na ROTA\v33, é um bom\vrapaz.\fEle te ligará se\nvir algum POKéMON\vraro!",
  ["46:457a"] = "Porta trancada…",
  ["46:458d"] = "Porta aberta.",
  ["46:45a0"] = "A CHAVE DO PORAO\nabriu a porta.",
  ["46:45c3"] = "Bem-vindo!\fEu administro o\nPOKéMON SALON!\fSou o mais velho e\nmelhor dos dois\vHAIRCUT BROTHERS.\fPosso deixar seu\nPOKéMON bonito\vpor apenas R$500.\fGostaria\ndisso?",
  ["46:4664"] = "Qual POKéMON\ndevo arrumar?",
  ["46:4682"] = "Certo! Observe\nficar bonito!",
  ["46:46a2"] = "Pronto! Feito!",
  ["46:46b4"] = "E isso mesmo?\nQue pena!",
  ["46:46d3"] = "Você precisa de\nmais grana.",
  ["46:46f5"] = "Faco apenas um\ncorte por dia.\vJá acabei.",
  ["46:4726"] = "Bem-vindo ao\nPOKéMON SALON!\fSou o mais jovem\ne menos caro\vdos dois IRTOS\vCABELEIREIROS.\fVou arrumar seu\nPOKéMON por\vapenas R$300.\fComo vai?",
  ["46:47bb"] = "Certo, qual\nPOKéMON?",
  ["46:47d8"] = "Certo! Vou\ndeixar legal!",
  ["46:47f4"] = "Pronto!\nTudo feito!",
  ["46:480c"] = "Não?\nQue pena!",
  ["46:4825"] = "Você esta um pouco\nsem dinheiro.",
  ["46:4845"] = "Faco apenas um\ncorte por dia.\fDesculpe, mas já\nacabei.",
  ["46:4889"] = "{STRBUF} parece\nmais feliz.",
  ["46:48a6"] = "{STRBUF} parece\nfeliz.",
  ["46:48b8"] = "{STRBUF} parece\nradiante!",
  ["46:48ce"] = "Não estamos\nabertos hoje.",
  ["46:48e4"] = "NÃO ENTRE\nALEM DESTE PONTO",
  ["46:4e67"] = "Espera aí!\fTe vi, então\nte segui.\fNão preciso de\nvocê atrapalhando\fenquanto cuido\nda TEAM ROCKET.\f…Espera aí.\nVocê me venceu\vantes, não foi?\fAquilo foi\nsó sorte.\fMas eu pago\nminhas dívidas!",
  ["46:4f27"] = "…Por quê…\nPor que perco?\fJuntei os POKéMON\nmais fortes.\fNão aliviei\nno ritmo.\fPor que perco?",
  ["46:4f8c"] = "…Não enten-\ndo…\fÉ verdade o que\no LANCE disse?\fQue não trato\nbem os POKéMON?\fAmor…\fConfiança…\fSão mesmo\no que me falta?\fSerá que me\nimpedem?\fEu… só não\nentendo.\fMas não vai\nterminar aqui.\fAgora não.\nNão por isso.\fNão vou desistir\ndo sonho de\fser o melhor\nmestre POKéMON!",
  ["46:50cc"] = "Humf. Este é o\nmeu poder real.\fVou acabar com\na TEAM ROCKET.\fE vou\nesmagar o LANCE\vsob meus pés.",
  ["46:5140"] = "Fui desafiado\npara uma batalha\vlá embaixo.\fÉ perigoso\nlá. Melhor\vtomar cuidado.",
  ["46:519a"] = "Há lojas\nlá embaixo…\fMas também\nhá treinadores.\fTenho medo\nde descer.",
  ["46:51f5"] = "Abre uma persiana,\noutra fecha.\fAposto que não\nchega onde quer!",
  ["46:5239"] = "Droga! Afundei\npor indecisão!",
  ["46:525a"] = "Eu também estou\nconfuso… O botão\fda ponta é o que\nse aperta antes…",
  ["46:52a2"] = "Kwahaha!\fConfuso com as\npersianas, né?\fEu conto um\nsegredo se você\vme vencer!",
  ["46:5311"] = "Certo. Uma dica!\fMude a ordem em\nque você aperta.\fIsso muda o jeito\nque as persianas\vabrem e fecham.",
  ["46:5378"] = "Passe as suas\ncoisas para cá!",
  ["46:5399"] = "Roubar e vender!\nÉ o básico do\vcrime, colega!",
  ["46:53c5"] = "Abandonaram esta\nobra antes de\vterminar.\fEstou procurando\no que sobrou.",
  ["46:5425"] = "UNDERGROUND WARE-\nHOUSE?\fPara que você\nquer ir lá?\fNão tem nada\nlá embaixo.",
  ["46:547c"] = "Não ligo se você\nestá perdido.\fApareceu aqui,\nvirou vítima e\vpronto!",
  ["46:54c6"] = "Urk! É, se acha\nesperto, hein?",
  ["46:54e9"] = "Você tem sangue\nde gelo para\vpeitar a ROCKET.",
  ["46:551e"] = "Está escrito\nSWITCH 1.",
  ["46:5535"] = "Está perdido? Não,\nnão pode estar.\fVocê não tem\ncara de assustado\fVou te dar\num motivo para\vse assustar!",
  ["46:55b0"] = "Vá para onde você\nquiser! Some!\vNão estou nem aí!",
  ["46:55e1"] = "Está DESLIGADO.\nLigar?",
  ["46:55f7"] = "Está LIGADO.\nDesligar?",
  ["46:560d"] = "Está escrito\nSWITCH 2.",
  ["46:5624"] = "Está escrito\nSWITCH 3.",
  ["46:563b"] = "Está escrito\nEMERGÊNCIA.",
  ["46:5795"] = "Ei, garoto!\nVocê nos atrasa!\fNosso esquema\né trabalhar\fnos bastidores,\nonde ninguém vê!",
  ["46:57f7"] = "Perco a vontade\nde trabalhar se\valguém me vê.\fAnda, garoto,\ncai fora!",
  ["46:5840"] = "Oohah! Oohah!\fAs coisas no\nchão são lixo.\fLeve-as se\nquiser!",
  ["46:59fd"] = "Ele acabou comigo",
  ["46:5a00"] = "le me liquidou…",
  ["46:5a11"] = "A TEAM ROCKET vai\nseguir em frente,\vesperando a volta\vdo GIOVANNI.\fFaremos o que for\npreciso.",
  ["46:5a70"] = "Você não passa\ndaqui!\fNão tenho piedade\ndos inimigos, nem\vdos pirralhos!",
  ["46:5aca"] = "Eu perdi…\fPor favor me\nperdoe, GIOVANNI!",
  ["46:5af0"] = "Hyuck-hyuck-hyuck!\nLembro de você!\fVocê me pegou\nno esconderijo!",
  ["46:5b34"] = "Hyuck-hyuck-hyuck!\nEntão é assim?",
  ["46:5b57"] = "Hyuck-hyuck-hyuck!\nFoi demais!\vVou me lembrar!",
  ["46:5b8f"] = "DIRECTOR: Quem?\nO quê? Você veio\vme resgatar?\fObrigado!\fA RADIO TOWER!\fO que está\nacontecendo lá?\fTomada pela\nTEAM ROCKET?\fAqui. Pegue\na CARD KEY.",
  ["46:5c24"] = "DIRECTOR: Use-a\npara abrir as\vpersianas do 3F.",
  ["46:5c56"] = "Imploro sua\najuda.\fNão dá pra saber\no que farão\fse controlarem\no transmissor.\fEles podem\naté controlar\fPOKéMON com\num sinal especial\fVocê é o único\nem quem confio.\fPor favor, salve\na RADIO TOWER…\fE todos os\nPOKéMON do país!",
  ["46:5f3d"] = "Ei!\fEu sou o KARATE\nKING!\fTreino sozinho\naqui no escuro!\fVocê!\nBatalhe comigo!\fHwaaarggh!",
  ["46:5f99"] = "Waaaarggh!\nFui derrotado!",
  ["46:5fb0"] = "Estou arrasado…\fMeu treino\nainda não bastou.\fMas derrota é\nderrota. Admito.\fComo prova de\nque você venceu,\fvou lhe dar um\nPOKéMON lutador.",
  ["46:6045"] = "{PLAYER} recebeu\nTYROGUE.",
  ["46:605a"] = "TYROGUE é do\ntipo lutador.\fEle evolui e\nfica mais forte.\fContinue firme\nno treino. Eu\vtambém sigo.\fAdeus!",
  ["46:60cf"] = "Você não tem\nespaço no time!",
  ["46:6267"] = "Está cravado\nno gelo.",
  ["46:9153"] = "OGUE.",
  ["46:ca00"] = "do\vmundo.",
  ["46:cb43"] = "Era a\nÁGUA MÍSTICA.\fEu não preciso\ndela, você a quer?",
  ["46:d744"] = "tavam passeando\vem algum lugar.",
  ["47:438b"] = "Uau! Você me\nassustou!\fEstava com\nBLACKGLASSES,\fentão não\nte notei.\fO que estou\nfazendo aqui?\fEi, não se\npreocupe.\fVou te dar\num BLACKGLASSES,\ventão esqueça\vque me viu, ok?",
  ["47:4458"] = "BLACKGLASSES\naumenta o poder\vde golpes",
  ["47:459c"] = "CLAIR: Tudo bem.\nReconheço seu\fverdadeiro poder.\nEste BADGE é seu",
  ["47:45e1"] = "{PLAYER} recebeu\nRISINGBADGE.",
  ["47:45fa"] = "RISINGBADGE fará\nseus POKéMON\fusarem o golpe\nde escalar\vcachoeiras.\fAlém disso, todos\nos POKéMON vão\fte reconhecer\ncomo treinador\fe obedecer\nseus comandos.\fTambém quero\nque leve esta TM.",
  ["47:46c4"] = "{PLAYER} recebeu\nTM24.",
  ["47:46d6"] = "Isto contém\nDRAGONBREATH.\fNão, não tem\nnada a ver com\vminha respiração.\fSe você não\nquiser, não\vprecisa levar.",
  ["47:4754"] = "Então, você\nconseguiu todos\vos BADGES.\fSeu destino\né a LIGA POKéMON\fno INDIGO\nPLATEAU.\fSabe como\nchegar lá?\fDaqui, vá\na NEW BARK TOWN.\fDepois SURF\npara o leste.\vA rota é dura.\fNão ouse\nperder na\vLIGA POKéMON!\fSe perder,\nvou me sentir\fpior por ter\nperdido pra você.",
  ["47:4881"] = "SANTUÁRIO DRAGÃO\fUm santuário em\nhonra aos POKéMON\fdragão que viveu\nno DRAGON'S DEN.",
  ["47:48d6"] = "…\nO quê? {PLAYER}?\f…Não, não vou\nbatalhar agora…\fMeus POKéMON\nnão estão prontos\fNão posso\nforçá-los agora.\fPreciso ser\ndisciplinado\fpara me tornar\no maior treinador",
  ["47:4980"] = "…\fUfa…\fAprenda a\nse afastar.",
  ["47:49a6"] = "{PLAYER} achou um\n{STRBUF}!",
  ["47:49b8"] = "Mas {PLAYER}\nnão pode levar\vmais itens.",
  ["48:4101"] = "Uau, sua POKéGEAR\né incrível!\fFoi sua mãe quem\nlhe deu ela?",
  ["48:413e"] = "Espere, {PLAYER}!",
  ["48:4148"] = "O que você pensa\nque está fazendo?",
  ["48:4168"] = "É perigoso sair\nsem um\vPOKéMON!\fPOKéMON selvagens\npulam do mato\fno caminho para\na próxima cidade.",
  ["48:41ce"] = "Oh! Seu POKéMON\né adorável!\vQueria ter um!",
  ["48:41fc"] = "Oi, {PLAYER}!\nSaindo de novo?\fVocê devia avisar\nsua mãe quando\vsair.",
  ["48:4240"] = "Ligue para sua mãe\nna POKéGEAR para\fcontar como você\nestá indo.",
  ["48:427e"] = "Ei, {PLAYER}!\fSoube que o PROF.\nELM descobriu\vnovos POKéMON.",
  ["48:42b0"] = "……\fEntão este é o\nfamoso LAB POKéMON\vdo ELM…",
  ["48:42d7"] = "…O que você está\nolhando?",
  ["48:42f2"] = "CIDADE NEW BARK\fA cidade onde\nos ventos do\vrecomeço sopram",
  ["48:4332"] = "Casa de {PLAYER}",
  ["48:433c"] = "LAB POKéMON ELM",
  ["48:434a"] = "CASA DO ELM",
  ["48:45ae"] = "Você é um\ntreinador novato,\vné? Dá para ver!\fTudo bem! Todo\nmundo já foi\vnovato um dia!\fSe quiser, posso\nte ensinar umas\vcoisas.",
  ["48:463a"] = "Certo, então!\nMe siga!",
  ["48:4650"] = "Este é um CENTRO\nPOKéMON. Curam\fseu POKéMON num\ninstante.\fVocê vai depender\nmuito deles,\fé bom aprender\nsobre eles.",
  ["48:46cf"] = "Esta é uma LOJA\nPOKéMON.\fVendem BALLS para\npegar POKéMON\fselvagens e outros\nitens úteis.",
  ["48:4724"] = "A ROUTE 30 fica\npor aqui.\fTreinadores lutam\ncom seus POKéMON\fpreferidos lá.\nVale ver.",
  ["48:4772"] = "Este é o mar,\ncomo você vê.\fAlguns POKéMON só\nsão achados\vna água.",
  ["48:47b7"] = "Aqui…\fÉ a minha casa!\nObrigado pela\vcompanhia.\fDeixe eu lhe dar\num presentinho.",
  ["48:4803"] = "A POKéGEAR de\n{PLAYER} tem MAPA!",
  ["48:481c"] = "A POKéGEAR fica\nmais útil quando\vvocê põe CARDS.\fBoa sorte na sua\njornada!",
  ["48:486a"] = "Oh… É algo que\ngosto de fazer…\fTudo bem. Venha\nquando quiser.",
  ["48:48ad"] = "…\fVocê pegou um\nPOKéMON no LAB.\fQue desperdício.\nUm fraco desses.\f…\fNão entendeu o\nque eu disse?\fPois eu tenho um\nPOKéMON bom.\fVou te mostrar\no que eu digo!",
  ["48:4942"] = "Hunf. Feliz por\nter ganhado?",
  ["48:4961"] = "…\fMeu nome é ???.\fEu vou ser o\nmelhor treinador\vPOKéMON do\vmundo.",
  ["48:49a5"] = "Hunf. Isso foi\nperda de tempo.",
  ["48:49c7"] = "…\fMeu nome é ???.\fEu vou ser o\nmelhor treinador\vPOKéMON do\vmundo.",
  ["48:4a0b"] = "Você falou com o\nvelho perto do\vCENTRO POKéMON?\fEle põe um MAPA de\nJOHTO na sua\vPOKéGEAR.",
  ["48:4a63"] = "Com POKéMON por\nperto, qualquer\vlugar é bom.",
  ["48:4a91"] = "A casa do\nMR.POKéMON fica\vmais adiante.",
  ["48:4abc"] = "Eu lutei com os\ntreinadores da\vestrada.\fMeus POKéMON\nperderam feio!\fPreciso levar eles\nao CENTRO POKéMON",
  ["48:4b21"] = "Um POKéMON que eu\npeguei tinha algo\fAcho que é\nMYSTIC WATER.\fNão preciso dele,\nvocê quer?",
  ["48:4b7c"] = "Volto a pescar,\nentão.",
  ["48:4b9b"] = "CHERRYGROVE CITY\fA cidade das\nflores perfumadas",
  ["48:4bd0"] = "CASA DO GUIA",
  ["48:4d29"] = "Olá!\nVocê treinador?\fLutar com LÍDER,\nganhar você?",
  ["48:4d62"] = "Ooh, la la!\nMuito bom mesmo!",
  ["48:4d81"] = "É mesmo? Então\nestudar você deve!\vMe siga!",
  ["48:4daf"] = "Aqui, professor eu\nsou. Bom é você\vestudar aqui!",
  ["48:4ddf"] = "Dizem que aparecem\nfantasmas na\vSPROUT TOWER.\fDiziam que ataques\nnormais não pegam\fnos fantasmas.\nNada mesmo.",
  ["48:4e49"] = "Ei, você é\ntreinador POKéMON\fSe vencer o LÍDER\nde GINÁSIO daqui,\fvai estar pronto\npara valer!",
  ["48:4ea5"] = "FALKNER, do\nGINÁSIO POKéMON\fde VIOLET, é um\nótimo treinador!\fEle herdou o\nginásio do pai\fe fez um belo\ntrabalho nele.",
  ["48:4f1b"] = "Vi uma árvore que\nse mexe adiante!\fSe você tocar,\nela se contorce\ve dança! Legal!",
  ["48:4f68"] = "VIOLET CITY\fA cidade dos\naromas de outrora",
  ["48:4f92"] = "VIOLET CITY\nGINÁSIO POKéMON\vLÍDER: FALKNER\fO elegante mestre\ndo tipo voador",
  ["48:4fda"] = "SPROUT TOWER\fConheça o caminho\ndos POKéMON",
  ["48:5003"] = "ACADEMIA POKéMON\nDO EARL",
  ["48:51e7"] = "…Me diga uma\ncoisa.\fÉ verdade que a\nTEAM ROCKET\vvoltou?\fO quê? Você\nvenceu? Hah! Pare\vde mentir.\fNão brinca?\nEntão vamos ver o\vquanto você vale.",
  ["48:5280"] = "… Hunf! POKéMON\ninútil!\fEscute aqui. Você\nsó ganhou porque\fmeus POKéMON\nestavam fracos.",
  ["48:52cd"] = "Odeio os fracos.\fPOKéMON, treinado-\nres. Não importa\vquem nem o quê.\fVou ficar forte e\nvarrer os fracos\vdo mapa.\fIsso vale para\na TEAM ROCKET.\fEles se acham em\nbando.\fMas sozinhos,\neles são\vfracos.\fOdeio todos eles.\fFique fora do meu\ncaminho. Um fraco\fcomo você só\natrapalha.",
  ["48:53f5"] = "…Hunf! Eu sabia\nque você mentia.",
  ["48:5415"] = "Não é seguro\nentrar ali, então\vfico de guarda.\fNão sou um bom\nsamaritano?",
  ["48:5461"] = "Conhece a\nSLOWPOKETAIL?\vDizem que é boa!\fNão está feliz de\neu ter contado?",
  ["48:54b5"] = "Os SLOWPOKE\nsumiram da\vcidade…\fOuvi que as TAILS\ndeles estão à\vvenda por aí.",
  ["48:550d"] = "Os SLOWPOKE\nvoltaram.\fConhecendo eles,\nsó estavam de\fbobeira em algum\ncanto.",
  ["48:5568"] = "Veio pedir para o\nKURT fazer umas\vBALLS?\fMuita gente vem\nsó para isso.",
  ["48:55b4"] = "Corte por AZALEA\ne você chega à\vILEX FOREST.\fMas essas árvores\nfinas tornam\fimpossível\npassar.\fO POKéMON do\nCARVOEIRO usa CUT\vnas árvores.",
  ["48:564a"] = "SLOWPOKE: …\f…… …… ……",
  ["48:565d"] = "…… ……Bocejo?",
  ["48:5667"] = "WOOSTER: Gugyoo…",
  ["48:5679"] = "AZALEA TOWN\nOnde pessoas e\fPOKéMON vivem em\nfeliz harmonia",
  ["48:56b2"] = "CASA DO KURT",
  ["48:56c0"] = "AZALEA TOWN\nGINÁSIO POKéMON\vLÍDER: BUGSY\fA enciclopédia\nambulante de\vPOKéMON inseto",
  ["48:5706"] = "SLOWPOKE WELL\fTambém chamado de\nPOÇO DA CHUVA.\fO povo daqui crê\nque o bocejo do\vSLOWPOKE dá chuva\fConsta que um\nbocejo dele\fpôs fim a uma seca\nhá 400 anos.",
  ["48:57ac"] = "FORNO DE CARVÃO",
  ["48:57bb"] = "ILEX FOREST\fEntre pelo\nportão.",
  ["48:5936"] = "Você atravessou o\nmar para chegar?\fDeve ter sido\nbem difícil.\fSeria bem mais\nfácil se o seu\fPOKéMON soubesse\nusar FLY…",
  ["48:59a8"] = "Mas não dá para\nusar FLY sem a\vBADGE daqui.\fSe vencer o LÍDER\ndo GINÁSIO daqui,\vvenha me ver.\fVou ter um belo\npresente pra você",
  ["48:5a28"] = "Essa é a BADGE do\nGINÁSIO daqui!\fEntão você deve\nlevar este HM.",
  ["48:5a62"] = "Ensine FLY ao seu\nPOKéMON.\fVocê vai poder\nvoar na hora\fpara qualquer lu-\ngar já visitado.",
  ["48:5abc"] = "Meu marido perdeu\npara você, então\vtem que treinar.\fAinda bem, porque\nele estava ficando\vmeio gordinho.",
  ["48:5b24"] = "Se usar o FLY,\ndá para voltar\fpara OLIVINE na\nhora.",
  ["48:5b5e"] = "As pedras ao norte\nda cidade podem\vser quebradas.\fElas podem estar\nescondendo algo.\fSeu POKéMON pode\nusar ROCK SMASH\vpara quebrar.",
  ["48:5bd9"] = "O CHUCK, LÍDER do\nGINÁSIO, treina\fcom os POKéMON\nlutadores dele.",
  ["48:5c11"] = "Existem várias\nilhas entre\vaqui e OLIVINE.\fUma criatura\nmítica do mar\vvive lá.",
  ["48:5c78"] = "CIANWOOD CITY\fUm Porto Cercado\npor Mares Bravios",
  ["48:5ca7"] = "CIANWOOD CITY\nGINÁSIO POKéMON\fLÍDER: CHUCK\fQuem Fala São os\nPunhos Dele",
  ["48:5cee"] = "500 Anos de\nTradição\fCIANWOOD CITY\nFARMÁCIA\fTire Suas Dúvidas\nsobre Remédios",
  ["48:5d3d"] = "CIANWOOD CITY\nESTÚDIO DE FOTO\fTire um Retrato\nde Lembrança!",
  ["48:5ec6"] = "Construíram a nova\nRADIO TOWER para\ftrocar a velha,\nque rangia.",
  ["48:5f06"] = "Sei que tem uma\nBIKE SHOP nova,\fmas não acho ela\nem lugar nenhum.",
  ["48:5f43"] = "Aquele homem de\npreto se veste\fcomo a TEAM ROCKET\nQue bobagem!",
  ["48:5f8a"] = "Aquele de preto\nera mesmo da\fTEAM ROCKET? Não\nacredito nisso!",
  ["48:5fd0"] = "A RADIO TOWER de\nGOLDENROD CITY é\vum cartão-postal.\fEstão com uma\npromoção\vrolando agora.\fEles modificam\na sua POKéGEAR,\fpara ela virar\num rádio também.",
  ["48:6071"] = "Oh, sua POKéGEAR\ntoca rádio agora!",
  ["48:6093"] = "E-he-he-he…\fLevei bronca\npor brincar no\fsubsolo da\nDEPT.STORE.",
  ["48:60e0"] = "O homem daquela\ncasa avalia os\vnomes que você dá\fEle até renomeia\no seu POKéMON.",
  ["48:612c"] = "Ufa! Esta cidade\né grande. Não sei\fonde fica\nnada.",
  ["48:616a"] = "Então esta é a\nRADIO TOWER…",
  ["48:6187"] = "O que você quer,\npentelho? Some!",
  ["48:61ab"] = "Saia do caminho!\nCai fora!",
  ["48:61ca"] = "Tomar a RADIO\nTOWER…\fO quê? Não é da\nsua conta!",
  ["48:6207"] = "POKéMON? Não são\nnada além de\fferramentas para\nganhar dinheiro!",
  ["48:623f"] = "Nosso sonho logo\nvai se realizar…\fFoi uma luta tão\nlonga…",
  ["48:627c"] = "Ei, pirralho! Você\nnão é daqui!\vSuma!",
  ["48:62a8"] = "Venha provar o\nverdadeiro terror\vda TEAM ROCKET!",
  ["48:62d4"] = "GOLDENROD CITY\nESTAÇÃO",
  ["48:62ec"] = "GOLDENROD CITY\nRADIO TOWER",
  ["48:6308"] = "Tudo em produtos\nPOKéMON!\fGOLDENROD CITY\nDEPT.STORE",
  ["48:6341"] = "GOLDENROD CITY\nGINÁSIO POKéMON\vLÍDER: WHITNEY\fA garota\nlinda demais!",
  ["48:6386"] = "GOLDENROD CITY\fA cidade festiva\nde muito charme",
  ["48:63b8"] = "O mundo é uma\nciclovia!\vBIKE SHOP",
  ["48:63de"] = "Seu parquinho!\fGOLDENROD CITY\nGAME CORNER",
  ["48:640b"] = "NAME RATER\fAvalie os apelidos\ndos seus POKéMON",
  ["48:6435"] = "ENTRADA DO\nSUBTERRÂNEO",
  ["48:644b"] = "ENTRADA DO\nSUBTERRÂNEO",
  ["49:40d7"] = "…\fVocê de novo?\fNão precisa entrar\nem pânico. Eu não\fperco tempo com\nbananas como você\fFalando em fracos,\na LÍDER daqui\fdo GINÁSIO não\nestá aqui.\fDizem que está\ncuidando de um\fPOKéMON doente no\nLIGHTHOUSE.\fHunf! Bu-hu-hu!\nÉ só largar os\vPOKéMON doentes!\fUm POKéMON que não\npode batalhar não\vvale nada!\fPor que você não\nvai treinar no\vLIGHTHOUSE?\fVai que. Talvez te\ndeixe um pouco\vmenos fraco!",
  ["49:4235"] = "Estradas escuras\nsão perigosas\vde noite.\fMas na escuridão\ntotal da noite,\fo mar é ainda\nmais traiçoeiro!\fSem a luz do farol\ndo LIGHTHOUSE\fpara guiar, navio\nnenhum navega.",
  ["49:42e1"] = "Essa coisa que\nvocê tem, é uma\vPOKéGEAR, né? Uau,\vque legal.",
  ["49:431e"] = "Uau, você tem uma\nPOKéDEX!\fIsso é simplesmen-\nte demais.",
  ["49:434e"] = "Olá, rapazinho!\nO mar é doce!\fCante comigo!\nEi-ô! Puxa a corda\vcom força!…",
  ["49:439a"] = "OLIVINE CITY\fO Porto Mais Perto\nde Outras Terras",
  ["49:43ca"] = "OLIVINE PORT\nPÍER DO FAST SHIP",
  ["49:43e7"] = "OLIVINE CITY\nGINÁSIO POKéMON\vLÍDER: JASMINE\fA Garota Blindada\nda Defesa",
  ["49:442a"] = "OLIVINE LIGHTHOUSE\nTambém Conhecido\vpor GLITTER",
  ["49:4604"] = "ECRUTEAK já teve\nduas torres:\fuma a leste e\noutra a oeste.",
  ["49:4646"] = "Ah, jovem.\nVocê aprendeu\fa dançar como as\nKIMONO GIRLS?\fSe for ao DANCE\nTHEATER delas, um\fvelhinho esquisito\ndá algo bacana\vpara você, ouvi.",
  ["49:46de"] = "Vou treinar lá no\nDANCE THEATER.\fQuer vir junto\ncomigo?",
  ["49:471d"] = "Aquela torre era\nbem mais alta,\fmas pegou fogo e\nacabou queimada.",
  ["49:4761"] = "Três POKéMON gran-\ndes fugiram cada\vum para um lado.\vO que eram eles?",
  ["49:47a4"] = "Ouvi um boato\nsobre o OLIVINE\vLIGHTHOUSE.\fO POKéMON que\nserve de farol\fficou doente.\nParece que estão\vcom problemas.",
  ["49:481d"] = "O POKéMON do\nOLIVINE LIGHTHOUSE\vfoi curado.\fOs barcos já podem\nsair ao mar de\vnoite em paz.",
  ["49:487e"] = "Ouvi que POKéMON\nestão em fúria no\fLAKE OF RAGE. Eu\nqueria ver isso.",
  ["49:48c3"] = "ECRUTEAK CITY\nCidade Histórica\fOnde o Passado\nEncontra o Hoje",
  ["49:4905"] = "TIN TOWER\fDizem que um POKé-\nMON lendário pousa\vaqui.",
  ["49:493a"] = "ECRUTEAK CITY\nGINÁSIO POKéMON\vLÍDER: MORTY\fO Vidente Místico\ndo Futuro",
  ["49:497e"] = "ECRUTEAK DANCE\nTHEATER",
  ["49:4996"] = "BURNED TOWER\fFoi destruída por\num incêndio\vmisterioso.\fFique longe, pois\nnão é seguro.",
  ["49:4b65"] = "Oi, garotinho! Vi\nque você é novo em\vMAHOGANY TOWN.\fJá que é novo aqui\ntem que provar um\fdelicioso RAGE-\nCANDYBAR!\fAgora mesmo, é seu\npor apenas\v¥300! Quer um?",
  ["49:4c03"] = "Ótimo! Aproveite!",
  ["49:4c14"] = "Você não tem\ndinheiro.",
  ["49:4c31"] = "Ah, tudo bem…",
  ["49:4c41"] = "Você não tem\nespaço para isto.",
  ["49:4c5f"] = "O RAGECANDYBAR\nesgotou.\fEstou fechando.\nNão me amole,\vgarotinho.",
  ["49:4ca2"] = "Vai lá ver o\nGYARADOS em fúria\vno LAKE?",
  ["49:4cda"] = "Os MAGIKARP\nvoltaram para o\vLAKE OF RAGE.\fDeve ser uma boa\nnotícia para os\vpescadores de lá.",
  ["49:4d33"] = "Já que veio até\naqui, aproveite\fpara passear um\npouco.\fVá para o norte\ne dê uma olhada\fno LAKE OF RAGE\nagora mesmo.",
  ["49:4daf"] = "Visite a loja da\nVovó. Ela vende\fcoisas que mais\nninguém tem.",
  ["49:4deb"] = "MAHOGANY TOWN\fBem-vindo ao Lar\ndos Ninjas",
  ["49:4e1b"] = "Em MAHOGANY TOWN,\nProve um\vRAGECANDYBAR!",
  ["49:4e4e"] = "MAHOGANY TOWN\nGINÁSIO POKéMON\vLÍDER: PRYCE\fO Mestre da\nDureza do Inverno",
  ["49:5063"] = "Este lago está\ncheio de GYARADOS\ve mais nada…\fEntão os MAGIKARP\nestão sendo força-\vdos a evoluir…",
  ["49:50c0"] = "Você veio aqui\npor causa dos\vboatos?\fVocê é {PLAYER}?\nSou LANCE, um\vtreinador igual.\fOuvi uns boatos\ne vim aqui para\vinvestigar…\fVi o jeito que\nvocê batalhou,\v{PLAYER}.\fDá para ver que\nvocê é treinador\fde bastante\nhabilidade.\fSe não se importa,\nquer me ajudar a\vinvestigar?",
  ["49:5155"] = "batalha,\v{PLAYER}.\fPosso lhe dizer\nque é um treinador\vcom grandes\vhabilidades.\fSe não se\nimportar, poderia\vme ajudar a\vinvestigar?",
  ["49:51d2"] = "LANCE: Excelente!\fParece que estão\nforçando os\fMAGIKARP do LAKE\na evoluir.\fUma transmissão de\nrádio misteriosa\fvinda de MAHOGANY\né a causa.\fEspero por você,\n{PLAYER}.",
  ["49:527d"] = "Ah… Bem, se você\nmudar de ideia,\vme ajude.",
  ["49:52b1"] = "LANCE: Hm? Você\nvai me ajudar?",
  ["49:52d7"] = "GYARADOS: Gyasha!",
  ["49:52eb"] = "{PLAYER} conseguiu\numa RED SCALE.",
  ["49:5304"] = "Os GYARADOS estão\nfuriosos!\fÉ mau agouro!",
  ["49:532d"] = "Hahah! Os MAGIKARP\nestão mordendo!",
  ["49:5350"] = "Ouvi que este lago\nfoi feito por\vGYARADOS em fúria\fSerá que tem\nalguma ligação\fcom esse surto\ntodo de agora?",
  ["49:53c7"] = "Meus olhos me\nenganaram? Eu vi\fum GYARADOS ver-\nmelho no LAKE…\fMas eu achava que\nGYARADOS eram\vazuis, não?",
  ["49:542e"] = "Deixe-me batalhar\ncom o POKéMON que\vacabei de pegar!",
  ["49:545a"] = "Sou bom pescador,\nmas péssimo como\ftreinador de\nPOKéMON…",
  ["49:549b"] = "Não perco como\npescador! Pesco\vPOKéMON todo dia",
  ["49:54cc"] = "Não importa o que\nfaça, só pego os\fmesmos POKé-\nMON…",
  ["49:5503"] = "Minha linha está\ntoda embaraçada…",
  ["49:551d"] = "Por que não pego\nbons POKéMON?",
  ["49:553e"] = "Se um treinador vê\noutro, ele tem\fque fazer um\ndesafio. Esse\fé o nosso\ndestino.",
  ["49:5594"] = "Ufa…\nBoa batalha.",
  ["49:55a8"] = "POKéMON e o dono\nficam fortes\fcom batalha\nconstante.",
  ["49:55eb"] = "O que aconteceu\ncom o GYARADOS\fvermelho? Sumiu?\fDroga. Vim\nà toa?\fJá sei, vamos\nbatalhar!",
  ["49:565e"] = "Pensando bem,\nvi um BUTTERFREE\vrosa.",
  ["49:5690"] = "WESLEY: Olá, como\nvai você?\fJá que hoje é\nquarta-feira,\fsou o WESLEY da\nquarta.",
  ["49:56e9"] = "Prazer em te\nconhecer. Aceite\vuma lembrança.",
  ["49:5717"] = "WESLEY: BLACKBELT\naumenta a força\vde golpes lutador",
  ["49:5750"] = "WESLEY: Se me\nachou, deve ter\fconhecido meus\nirmãos e irmãs.\fOu foi só\nsorte sua?",
  ["49:57b5"] = "WESLEY: Hoje não\né quarta-feira.\vQue pena.",
  ["49:57e3"] = "LAKE OF RAGE,\ntambém chamado de\vGYARADOS LAKE.",
  ["49:580f"] = "CASA DO\nFISHING GURU",
  ["49:5994"] = "Me desculpe.\fNosso LÍDER esta\ntreinando na\vcaverna lá atrás.\fNão tenho ideia\nquando nosso LÍDER\vvai voltar.",
  ["49:5a01"] = "Nosso LÍDER esta\nte esperando.\fPorém, seria\nimpossível para\fum treinador comum\nvencer.",
  ["49:5a54"] = "vencê-la.",
  ["49:5a6b"] = "Você derrotou\nnosso LÍDER?\vIsso e incrível!\fCom seu poder,\nvocê deve ter\fsucesso na\nLIGA POKéMON.",
  ["49:5ad0"] = "Só usuarios de\ndragão podem\ftreinar aqui.\nPor favor, va.",
  ["49:5b0e"] = "Como CLAIR, a\nmestra do dragão,\fpermitiu, você\npode entrar.",
  ["49:5b4e"] = "Meu radio esta\nquebrado?\vSó esse sinal.",
  ["49:5b87"] = "Arooo! Vocês na\nminha cabeça!\fHae? Estou ouvindo\nmeu radio!",
  ["49:5bc1"] = "Você vai fazer\nseu POKéMON\vesquecer golpes?",
  ["49:5bf5"] = "Vou me tornar\num usuário de\vdragão CLAIR.",
  ["49:5c1f"] = "SANTOS: …\fÉ sábado…\fSou SANTOS\ndo sábado…",
  ["49:5c4f"] = "Fique com isso…",
  ["49:5c63"] = "SANTOS: …\fSPELL TAG…\fGolpes do tipo\nfantasma ficam\fmais fortes…\nVai te assustar…",
  ["49:5cae"] = "SANTOS: …\fAté outro\nsábado…\fNão vou ter\nmais presentes…",
  ["49:5cf8"] = "SANTOS: Hoje não\né sábado…",
  ["49:5d16"] = "Uau, você veio\npela ICE\vPATH?\fVocê deve ser\num treinador!",
  ["49:5d5f"] = "BLACKTHORN CITY\fUm Refugio\nMontanhoso",
  ["49:5d89"] = "BLACKTHORN CITY\nPOKéMON GYM\vLÍDER: CLAIR\fA Abencoadora\nDragão",
  ["49:5dd1"] = "CASA DO\nAPAGADOR GOLPES",
  ["49:5de7"] = "DRAGON'S DEN\nA FRENTE",
  ["49:5dfb"] = "TRAINER TIPS\fUm POKéMON\nsegurando uma\fMIRACLEBERRY\ncura qualquer\vproblema status.",
  ["49:5f27"] = "MT.SILVER",
  ["49:d600"] = "e\ngolpes que eu não\vsabia que ele\vtinha.\fIsso me confundiu\npor completo.",
  ["49:ea00"] = "m POKéMONS na\vclasse!",
  ["4a:41b7"] = "Vai ser difícil\nvencer na LEAGUE.\vPreciso treinar\fmais.\nOuvi dizer que a\fELITE FOUR é\nmais difícil que\fos LÍDERES de\nGINÁSIO.",
  ["4a:4246"] = "Passando por\nbatalhas duras,\vvocê ganha poder.",
  ["4a:4276"] = "Aaah! A vida é\ntão difícil!",
  ["4a:4293"] = "Para chegar à\nLEAGUE POKéMON,\ftem que atravessar\na VICTORY ROAD.\fMas a VICTORY ROAD\né difícil.\fQuase ninguém\nvai lá!",
  ["4a:430b"] = "Já que você chegou\naté aqui, deve ser\vbom.\fVou dar nessa\nbatalha tudo o\vque tenho!",
  ["4a:436c"] = "Não! Eu não\nacredito nisso!",
  ["4a:4386"] = "Eu derrotei\noito LÍDERES,\fentão estava\nconfiante.\fVou ter que\nme esforçar mais.",
  ["4a:43e5"] = "Perdi para o\n{RIVAL}.\fEle era muito\nforte, mas…\fEra como se ele\nquisesse vencer\va qualquer custo.\fSenti pena dos\nPOKéMON dele.",
  ["4a:446e"] = "POKéMON não são\narmas de guerra.",
  ["4a:4488"] = "POKéMON são\nvaliosos parceiros\vpara a vida toda.",
  ["4a:44b3"] = "Uau, olha todas\nessas BADGES!\vImpressionado.\fMas você não\nse satisfaz só\fcoletando elas,\nné?",
  ["4a:4527"] = "Pessoas e POKéMON\ncrescem com suas\vexperiências.\fNão fique parado\ne acomodado.",
  ["4a:4573"] = "Estou me sentindo\nótimo hoje!\fSinto que poderia\nvencer até\vo CAMPEÃO!",
  ["4a:45bc"] = "Não! Não nesta\nbatalha!",
  ["4a:45d5"] = "Como na pesca,\nem POKéMON está\ftudo perdido se\nvocê desistir.",
  ["4a:4613"] = "ROUTE 26\fPOKéMON LEAGUE\nRECEPTION GATE",
  ["4a:486a"] = "Ei!",
  ["4a:4870"] = "Sabe o que você\nacabou de fazer?\fVocê deu seu\nprimeiro passo\vem KANTO.\fConfira no\nmapa da POKéGEAR",
  ["4a:48d8"] = "Você parece\nbem forte.\vVamos batalhar!",
  ["4a:490a"] = "Se você vencer\nesta trilha dura,\fa verdade será\nrevelada!\fHeh, desculpa, só\nqueria dizer\valgo legal.",
  ["4a:4955"] = " Eu só\nqueria falar\valgo legal.",
  ["4a:497b"] = "Hm? Você é bom,\nnão é?",
  ["4a:4997"] = "Como eu pensei!",
  ["4a:49ab"] = "Um bom treinador\nreconhece outros\vbons treinadores.",
  ["4a:49de"] = "Você não deveria\nsubestimar os\fPOKéMON selvagens\ndestas bandas.",
  ["4a:4a18"] = "Ah! Você é\nforte demais!",
  ["4a:4a34"] = "Você é um garoto,\nmas não dá para\fte subestimar.\nNem de longe.",
  ["4a:4a72"] = "É raro ver\nalguém por aqui.\fVocê treina\nsozinho?",
  ["4a:4ab3"] = "Ah! Você é\nrealmente forte!",
  ["4a:4acd"] = "Analiso os POKéMON\nantes e depois da\vevolução.\fEvoluir de verdade\ndeixa os POKéMON\vmais fortes.\fMas as formas\nevoluídas também\vaprendem depois.",
  ["4a:4b54"] = "Não diga nada!\fDeixe-me adivinhar\no que você pensa.\fMmmmmmm…\fAchei! Você está\nno desafio da\vLEAGUE POKéMON!",
  ["4a:4bc0"] = "Você é demais!",
  ["4a:4bd1"] = "Com sua força,\nvocê vai bem na\vLEAGUE.\fÉ o que diz minha\npremonição.",
  ["4a:4c21"] = "Tweet! Tweet!\nTetweet!",
  ["4a:4c41"] = "BIRD KEEPERS, nós\nimitamos assobios\fpara comandar\nos POKéMON.",
  ["4a:4c7e"] = "TOHJO FALLS\fA ligação entre\nKANTO e JOHTO",
  ["4a:4d53"] = "ROUTE 28",
  ["4a:4ed2"] = "POKéMON se\nescondem no mato.\fNunca se sabe\nquando saltam…",
  ["4a:4f0a"] = "Já te vi umas\nvezes. Quantos\fPOKéMON você já\npegou?\fQuer que eu mostre\ncomo pegar\vPOKéMON?",
  ["4a:4f78"] = "É assim que se\nfaz.\fSe enfraquecer\nantes, o POKéMON\vé mais fácil.",
  ["4a:4fc2"] = "Ah. Tudo bem.\fEnfim, se quer\npegar POKéMON,\fvocê tem que\nandar bastante.",
  ["4a:500e"] = "Hã? Quer que eu\nmostre como\vpegar POKéMON?",
  ["4a:503f"] = "E aí. Como estão\nseus POKéMON?\fSe estão fracos\ne sem preparo,\ffique fora do\nmato.",
  ["4a:5097"] = "Viu aqueles\nbarrancos? Dá medo\vpular deles.\fMas dá para ir a\nNEW BARK sem\fpassar pelo\nmato.",
  ["4a:5104"] = "Quis dar uma\npausa, e salvei\fpara guardar meu\nprogresso.",
  ["4a:5141"] = "Estou esperando\nos POKéMON que\fsó aparecem de\ndia.",
  ["4a:5177"] = "Estou esperando\nPOKéMON que\fsó aparecem à\nnoite.",
  ["4a:51a7"] = "Estou esperando\nPOKéMON que\fsó aparecem de\nmanhã.",
  ["4a:51dd"] = "TUSCANY: Creio eu\nque esta é a\fprimeira vez que\nnos vemos?\fPermita-me que eu\nme apresente.\fSou TUSCANY, de\nterça-feira.",
  ["4a:5200"] = "z que nos encotramos?\fPermita que eu me apresente a você.\fEu sou TUSCANY da Terça.",
  ["4a:525a"] = "Como apresentação,\naceite este\fpresente, um\nPINK BOW.",
  ["4a:529a"] = "TUSCANY: Não acha\nque ele é mesmo\vadorável?\fEle fortalece\nataques normais.\fTenho certeza que\nserá útil.",
  ["4a:5312"] = "TUSCANY: Conhece\nMONICA, minha\virmã mais velha?\fOu meu irmão\ncaçula, WESLEY?\fSou a segunda de\nsete filhos.",
  ["4a:5384"] = "TUSCANY: Hoje não\né terça-feira.\vQue pena…",
  ["4a:53b9"] = "ROUTE 29\fCHERRYGROVE CITY -\nNEW BARK TOWN",
  ["4a:53e4"] = "ROUTE 29\fCHERRYGROVE CITY -\nNEW BARK TOWN",
  ["4a:55ad"] = "Vai, RATTATA!\fTACKLE!",
  ["4a:55c3"] = "O quê? Esta é uma\nbatalha séria!\vMe deixe em paz!",
  ["4a:55f0"] = "Acabei de perder,\nvou procurar\vmais POKéMON.\fEspera! Você\nparece fraco!\vVamos batalhar!",
  ["4a:5600"] = "lha e agora\vestou procurando\vPOKéMONS.\fAh! Você é novato!\nVamos batalhar!",
  ["4a:5649"] = "Ugh. Não tenho\nmais POKéMON.",
  ["4a:566a"] = "Preciso ter\nmais POKéMON para\vbatalhas.\fVou pegar mais\num pouco!",
  ["4a:56ae"] = "Você é um\ntreinador, certo?\fEntão você tem que\nbatalhar!",
  ["4a:56e5"] = "Estranho.\nEu venci antes.",
  ["4a:5703"] = "Virar um bom\ntreinador é\vdifícil.\fVou batalhar\ncom outras pessoas\vpara melhorar.",
  ["4a:575e"] = "Em vez de um\nPOKéMON, achei\vum treinador!",
  ["4a:5789"] = "Argh! Você é\nforte demais!",
  ["4a:57a2"] = "Fiquei sem POKé\nBALLS enquanto\vcapturava POKéMON\fDevia ter trazido\nmais…",
  ["4a:57f0"] = "A casa do\nMR.POKéMON? Fica\vum pouco adiante.",
  ["4a:581a"] = "Todo mundo se\ndiverte lutando!\vFaça o mesmo!",
  ["4a:584a"] = "Não sou treinador\fMas se olhar nos\nolhos de um,\vprepare-se.",
  ["4a:5891"] = "ROUTE 30\fVIOLET CITY -\nCHERRYGROVE CITY",
  ["4a:58ba"] = "CASA DO MR.POKéMON\nEm frente!",
  ["4a:58db"] = "LAR DE MR.POKéMON",
  ["4a:58ec"] = "DICA AO TREINADOR\fNão roube POKéMON\ndos outros!\fPOKé BALLS só se\njogam em POKéMON\vselvagens!",
  ["4a:5b1e"] = "DARK CAVE…\fSe um POKéMON\niluminasse, eu\vexploraria.",
  ["4a:5b54"] = "Peguei um monte\nde POKéMON. Vamos\vbatalhar com você",
  ["4a:5b90"] = "Você pode pegar\nPOKéMON mesmo se\fvocê tiver seis.\nSe pegar um, ele\fvai para a sua\nBOX\vautomaticamente.",
  ["4a:5bf8"] = "… Hnnn… Hã?\fAndei demais hoje\nprocurando\vPOKéMON.\fMeus pés doem e\nestou com sono…\fSe eu fosse um\nPOKéMON selvagem,\vseria fácil…\f…Zzzz…",
  ["4a:5c80"] = "…Zzzz… Hã?\fO que é isso? Tem\nMAIL para mim?",
  ["4a:5caf"] = "{PLAYER} entregou\no POKéMON que\vsegurava a MAIL.",
  ["4a:5cd9"] = "Vejamos…\f…DARK CAVE leva\na outra estrada…\fBom saber\ndisso.\fObrigado por\ntrazer isto.\fMeu amigo é gente\nboa, e você\vtambém é!\fQuero fazer algo\nde bom em troca\vtambém!\fJá sei! Quero que\nfique com isto!",
  ["4a:5dbb"] = "TM50 é NIGHTMARE.\fÉ um golpe cruel\nque rói devagar\fo PS de um inimigo\nadormecido.\fOoooh…\nQue medo…\fNão quero ter\npesadelos.",
  ["4a:5e46"] = "Esta MAIL não é\npara mim.",
  ["4a:5e5e"] = "Por que este\nPOKéMON é raro?\fEle não tem\nMAIL nenhuma.",
  ["4a:5e97"] = "O quê? Você não\nquer nada?",
  ["4a:5eb6"] = "Se eu levar esse\nPOKéMON de você,\fo que vai usar\nna batalha?",
  ["4a:5efa"] = "Achei um bom\nPOKéMON na DARK\vCAVE.\fVou criar ele\npara encarar o\vFALKNER.\fEle é o líder do\nGINÁSIO de VIOLET",
  ["4a:5f6a"] = "ROUTE 31\fVIOLET CITY -\nCHERRYGROVE CITY",
  ["4a:5f93"] = "DARK CAVE",
  ["4a:875b"] = "ha possa\vmudar as coisas\vpara mim.",
  ["4a:9749"] = " fique\nconvencido, a\vKATE é poderosa!",
  ["4a:a000"] = " nariz!",
  ["4a:ab41"] = "Eu conheço minhas\nfraquezas.",
  ["4a:c800"] = ", eu\vacalmo os meus\vnervos!",
  ["4a:d100"] = "   Não me atrapalhe.\nEstou segurando\vnum POKéMON\vaquático!",
  ["4b:42a5"] = "Espera aí!\nQual é a pressa?",
  ["4b:42c0"] = "{PLAYER}, né?\nUm cara de óculos\festava procurando\npor você.\fVá ver você mesmo.\nEle espera por\fvocê no CENTRO\nPOKéMON.",
  ["4b:4335"] = "Você já foi à\nSPROUT TOWER?\fSe você visitar\nVIOLET CITY,\fvão esperar que\ntreine lá.\fÉ o básico para\ntreinadores. Vá à\vSPROUT TOWER!",
  ["4b:43c5"] = "Você já foi ao\nGINÁSIO POKéMON?\fDá para testar seu\nPOKéMON e você\vmesmo lá.\fÉ um rito de\npassagem para todo\vtreinador!",
  ["4b:4400"] = "N\vno GINÁSIO.\fTodos treinadores\nprecisam ir até\vlá!",
  ["4b:443a"] = "Você tem bons\nPOKéMON aí.\fDeve ser do treino\nque você deu\fneles por\nVIOLET CITY.\fO treino no\nGINÁSIO deve ter\fajudado bastante.\nSem dúvida.\fComo lembrança de\nVIOLET CITY, leve\visto.\fAumenta a força\ndos ataques de\vplanta.",
  ["4b:452a"] = "O que viveu em\nVIOLET CITY\fdeve ser útil na\nsua jornada.",
  ["4b:456e"] = "Que tal levar\nesta gostosa e\fnutritiva\nSLOWPOKETAIL?\fPara você agora,\nsó ¥1.000.000!\fVai querer!",
  ["4b:45e4"] = "Tsc! Pensei que\na molecada de hoje\vtinha dinheiro…",
  ["4b:4600"] = "hoje eram\vricos…",
  ["4b:4611"] = "Não quer? Então\nfora daqui. Xô!",
  ["4b:4636"] = "Uau!\fVocê me fez perder\naquele peixe!",
  ["4b:4663"] = "Calmo, concentrado\nA essência da\fpesca e dos POKé-\nMON é a mesma.",
  ["4b:46a4"] = "Sou um bom pesca-\ndor, mas um\vtreinador melhor!",
  ["4b:46d3"] = "Tch! Quis apressar\nas coisas…",
  ["4b:46f1"] = "Pescar é paixão\nde uma vida.\fPOKéMON são amigos\nde uma vida!",
  ["4b:4730"] = "Só pego o mesmo\nPOKéMON sempre…\fTalvez uma batalha\nvire o jogo\vpara mim.",
  ["4b:477f"] = "Nada dá certo\npara mim agora…",
  ["4b:47a4"] = "Como o cara do\nmeu lado pega\vPOKéMON bons?",
  ["4b:47d4"] = "Heh, estou com\nsorte hoje. Que\vtal lutar, moço?",
  ["4b:4807"] = "Ufa. Não tive\nsorte dessa vez.",
  ["4b:4826"] = "Você precisa de\numa ROD boa se\fquiser pegar\nPOKéMON bons.",
  ["4b:4863"] = "Meus POKéMON?\nRecém-pescados!",
  ["4b:4886"] = "POKéMON recém-\npegos não são\fpáreo para os bem\ncriados.",
  ["4b:48c2"] = "Nunca vi você\npor aqui antes.\fEntão você se acha\nbem durão?",
  ["4b:4916"] = "Vou tentar ser o\nmelhor com os\vmeus favoritos.\fNão uso os mesmos\nPOKéMON fortes que\vtodo mundo usa.",
  ["4b:497c"] = "Achei uns POKéMON\nbons ali no\vmato!\fAcho que eles vão\ndar conta!",
  ["4b:49bf"] = "Droga. Achei que\nia ganhar.",
  ["4b:49dd"] = "O mato está cheio\nde coisa grudenta",
  ["4b:4a02"] = "Aquele olhar…\nÉ intrigante.",
  ["4b:4a20"] = "Hmmm. Que\ndecepção.",
  ["4b:4a3e"] = "Se não quiser\nbatalhar, evite\volhar nos olhos.",
  ["4b:4a73"] = "Aham. É, e\nsabe como é…\fComo? Batalhar?\nEstou ao telefone\fAh, tá bom. Mas\nseja rápido.",
  ["4b:4ad2"] = "Vai com calma!\nQue maldade!",
  ["4b:4aed"] = "E eu estava numa\nboa conversa.",
  ["4b:4b0c"] = "Essa BADGE! É de\nVIOLET CITY!\fVenceu o FALKNER?",
  ["4b:4b41"] = "Eu sei quais são\nminhas fraquezas.",
  ["4b:4b61"] = "Eu devia treinar\nde novo no GINÁSIO\vde VIOLET CITY.",
  ["4b:4b92"] = "Os pescadores\ngritaram comigo\vpor amolar eles…",
  ["4b:4bc0"] = "WROOOAR!\nGENTE FOGE QUANDO\fEU RUJO! MAS VOCÊ\nVEIO ATRÁS!\fISSO ME AGRADA!\nAGORA PEGUE ISTO!",
  ["4b:4c19"] = "WROOOAR!\nÉ O ROAR!\fATÉ POKéMON FOGEM\nDE UM BOM ROAR!",
  ["4b:4c4e"] = "FRIEDA: Oba!\nÉ sexta-feira!\fSou a FRIEDA de\nsexta!\fPrazer!",
  ["4b:4c91"] = "Aqui, um POISON\nBARB para você!",
  ["4b:4caf"] = "FRIEDA: Dê a um\nPOKéMON que tenha\vataques venenosos\fOh!\fÉ cruel!\fVai se espantar\ncom o quanto\vmelhora eles!",
  ["4b:4d27"] = "FRIEDA: Oi! Que\ndia você gosta?\fAmo sexta-feira.\nSem dúvida!\fVocê não acha\nótimo também?",
  ["4b:4d8c"] = "FRIEDA: Hoje não\né sexta-feira?\fÉ tão sem graça\nquando não é!",
  ["4b:4dc7"] = "ROUTE 32\fVIOLET CITY -\nAZALEA TOWN",
  ["4b:4deb"] = "RUINS OF ALPH\nENTRADA LESTE",
  ["4b:4e08"] = "UNION CAVE\nEm frente",
  ["4b:4fab"] = "(Eu vim pelo\ntúnel, mas ainda\ftenho energia\nde sobra.",
  ["4b:4ff1"] = "Uau, garoto! Você\ntem mais gás.",
  ["4b:5011"] = "Nós HIKERS somos\nmelhores nas\vmontanhas.",
  ["4b:503e"] = "ROUTE 33",
  ["4b:530f"] = "O que aconteceu?",
  ["4b:531f"] = "Vou treinar ainda\nmais forte.\fAfinal, quero\nvirar LÍDER de\vGINÁSIO.",
  ["4b:536c"] = "Sou o melhor da\nturma em POKéMON.",
  ["4b:538e"] = "Não! Tem treina-\ndores melhores…",
  ["4b:53b0"] = "Me esforço para\nser o destaque\vda minha turma.",
  ["4b:53e2"] = "Tenho confiança\nna minha forma\vde criar POKéMON.\fQuer ver?",
  ["4b:541a"] = "Eu não fiz um\ntrabalho bom?",
  ["4b:5439"] = "Talvez eu devesse\ndeixar um no DAY-\vCARE.\vO que eu faço?",
  ["4b:5473"] = "Você é treinador?\fVamos fazer uma\nbatalha de treino",
  ["4b:54a4"] = "Ah, não! Eu não\nconsigo ganhar…",
  ["4b:54be"] = "Você é forte\ndemais para ser\vmeu parceiro.",
  ["4b:54ea"] = "Quem vem lá?\nO que você está\vaprontando?",
  ["4b:550f"] = "Você é um garoto\ndurão.",
  ["4b:552a"] = "É, não vejo nada\nde errado hoje.\fComporte-se e não\narrume confusão.",
  ["4b:5570"] = "Estou de ronda\natrás de gente\vsuspeita.",
  ["4b:559c"] = "Acabei de pegar\nmeu POKéMON de\vvolta no DAY-CARE\fVamos ver o quanto\nele ficou forte!",
  ["4b:55e7"] = "Por que termina\nassim?",
  ["4b:5602"] = "Meu POKéMON sabia\ngolpes que eu nem\vsabia que tinha.\fIsso me confundiu\ndemais!",
  ["4b:5649"] = "IRENE: Aaaai!\nUm menino achou!",
  ["4b:5669"] = "IRENE: Ooooh!\nEle é forte!",
  ["4b:5688"] = "IRENE: Minha irmã\nKATE vai te pegar\vpor isso!",
  ["4b:56b6"] = "IRENE: Esta praia\nnão é ótima?\fÉ o nosso refúgio\nsecreto!",
  ["4b:56f4"] = "JENN: Não dá para\nvencer a IRENE e\vficar impune!",
  ["4b:5722"] = "JENN: Me desculpe,\nIRENE! Maninha!",
  ["4b:573f"] = "JENN: Não se ache\ndemais! Minha irmã\vKATE é durona!",
  ["4b:576f"] = "JENN: A luz do sol\ndeixa o corpo\vmais forte.",
  ["4b:5799"] = "KATE: Você foi bem\nmalvado com as\vminhas irmãzinhas",
  ["4b:57c9"] = "KATE: Não! Não\nacredito nisso.",
  ["4b:57eb"] = "KATE: Você é forte\ndemais. Eu não\vtive chance.\fTome. Você merece\nisto.",
  ["4b:5800"] = "orte. Eu não\vtive chance.\fEi! Você merece\nisso.",
  ["4b:5834"] = "KATE: Desculpe ter\npulado em cima.\fNunca esperamos\nque alguém nos\fachasse aqui. Você\nnos assustou.",
  ["4b:5893"] = "ILEX FOREST\nPelo Portão",
  ["4b:58b1"] = "ROUTE 34\fGOLDENROD CITY -\nAZALEA TOWN\fILEX FOREST\nEm algum ponto",
  ["4b:58f6"] = "TRAINER TIPS\fÁrvores de BERRY\ndão BERRIES novas\vtodo dia.\fAnote que árvore\ndá qual tipo de\vBERRY.",
  ["4b:5946"] = "s por\vcada árvore.",
  ["4b:595a"] = "DAY-CARE\fNós Criamos o Seu\nPOKéMON por Você!",
  ["4b:5c4d"] = "A música do rádio\nmuda o humor dos\vPOKéMON selvagens",
  ["4b:5c81"] = "Vou mostrar para\nminha namorada que\veu sou bom!",
  ["4b:5cac"] = "Queria que você\ntivesse perdido…",
  ["4b:5cd0"] = "Fui humilhado\nna frente da minha\vnamorada…",
  ["4b:5cfd"] = "Meu namorado é\nfraco, não dá para\vcontar com ele.",
  ["4b:5d29"] = "Nossa! Você é\ntão forte!",
  ["4b:5d43"] = "Confio mais nos\nmeus POKéMON que\vno meu namorado.",
  ["4b:5d73"] = "Você vai para o\nGINÁSIO? Eu vou!",
  ["4b:5d96"] = "Ah. Eu não\nconsegui…",
  ["4b:5daa"] = "As BADGES de\nGINÁSIO são lindas\vEu coleciono.",
  ["4b:5dd6"] = "Que tipo de POKé\nBALL você usa?",
  ["4b:5df8"] = "Eita! Não fui\nrápido o bastante",
  ["4b:5e11"] = "Alguns POKéMON\nfogem na hora.\fTente pegar eles\ncom a FAST BALL\vdo KURT.\fSempre que acho um\nWHT APRICORN, eu\vlevo para o KURT.\fEle faz uma POKé\nBALL sob medida.",
  ["4b:5eaa"] = "Veja como eu sou\nbom com a BALL!",
  ["4b:5ece"] = "Ufa! Que choque\nfoi esse!",
  ["4b:5ee6"] = "Eu ia deslumbrar\nvocê com o meu\vPOKéMON premiado.\fMas a sua força\nme eletrizou!",
  ["4b:5f36"] = "Eu vou a qualquer\nlugar onde apareça\vPOKéMON inseto.",
  ["4b:5f61"] = "Entendi. Então\nvocê luta assim.",
  ["4b:5f81"] = "Meu VENONAT ganhou\no Concurso de\fCaptura Insetos\nno NATIONAL PARK.",
  ["4b:5fc3"] = "Estou treinando\nmeu sopro de fogo",
  ["4b:5fe5"] = "Ai! Queimei a\nponta do nariz!",
  ["4b:6009"] = "A POKéMON March\nno rádio atrai\vPOKéMON do mato.",
  ["4b:6037"] = "O perigo espreita\nà noite!",
  ["4b:6053"] = "Opa!",
  ["4b:605c"] = "Sabe, a noite tem\nas diversões dela\vtambém.\fMas não exagere,\ntá bom?",
  ["4b:60a3"] = "Seus POKéMON são\nbem fortes.\fVocê pode ir a\nqualquer lugar.",
  ["4b:60e1"] = "ROUTE 35",
  ["4b:6321"] = "E uma árvore\nestranha?",
  ["4b:6346"] = "{PLAYER} usou o\nSQUIRTBOTTLE.",
  ["4b:6360"] = "A árvore estranha\nnão gosta do\vSQUIRTBOTTLE!\fA árvore estranha\natacou!",
  ["4b:63a7"] = "Wa-hey!\fEu ia quebrar\nessa árvore\fcom meu soco\ndireto.\fMas não consegui!\nSou um fracasso!",
  ["4b:6408"] = "Você tirou\naquela árvore?\fImpressionado!\nQuero que você\vtenha isso.",
  ["4b:6452"] = "{PLAYER} recebeu\nTM08.",
  ["4b:6464"] = "Isso e ROCK SMASH.\nVocê pode quebrar\fpedras com um\nsó golpe bem\fmirado.\nSe houver pedras\fno seu caminho,\napenas quebre\vtodas!",
  ["4b:64f0"] = "Uma árvore\nestá bloqueando\vo caminho para\fGOLDENROD CITY.\nEstá me impedindo\fde comprar.\nAlguém deve agir.",
  ["4b:6568"] = "Aquela árvore\ndesapareceu sem\vrastro.\fAh! Aquela árvore\nera um POKéMON?",
  ["4b:65b7"] = "Vou ler os\nseus pensamentos!",
  ["4b:65e8"] = "Eu seria forte\nse pudesse saber\fo que meu oponente\nestá pensando.",
  ["4b:6600"] = " pudesse\vcontar o que meu\voponente pensa.",
  ["4b:662a"] = "Graças aos meus\nestudos, encaro\vqualquer POKéMON!",
  ["4b:665a"] = "Ops! Erro de\ncálculo?",
  ["4b:6674"] = "Droga. Estudo 5\nhoras/dia também.\fHá muita coisa\nque não se aprende\vsó lendo livros.",
  ["4b:66cc"] = "ARTHUR: Quem e\nvocê?\fSou ARTHUR de\nquinta-feira.",
  ["4b:66f9"] = "Aqui. Você pode\nficar com isso.",
  ["4b:6713"] = "ARTHUR: Um POKéMON\nque usa golpes\fdo tipo pedra\ndeveria guardar\fisso.\nGolpes de pedra.",
  ["4b:6776"] = "ARTHUR: Sou ARTHUR\nde quinta-feira.\fSou o segundo\nde sete crianças.",
  ["4b:67bf"] = "ARTHUR: Hoje não\né quinta-feira.\vQue decepção.",
  ["4b:67f0"] = "ROTA 36",
  ["4b:67fa"] = "RUÍNAS DE ALPH\nENTRADA NORTE",
  ["4b:6818"] = "TRAINER TIPS\fStatus de POKéMON\nvariam ,  mesmo\vdentro da mesma\fespécie.\nSeus status podem\fser parecidos.\nMas as diferenças\fse tornar claras\nconforme crescem.",
  ["4b:68ba"] = "TRAINER TIPS\fUse DIG para ir\nà entrada de\vqualquer lugar.\fÉ conveniente\npara explorar\fcavernas e outros\nlugares assim.",
  ["4b:9000"] = "paz jovem\ncomo você deveria\vnadar.\fNão SURFE em cima\ndo seu POKéMON.",
  ["4b:9700"] = "s me\nmantém fora do\valcance daquela\vilha.",
  ["4b:c600"] = "\fSe os tipos\nforem diferentes,\fum POKéMON mais\nalto pode perder.\fSaiba quais tipos\nsão fortes e\ffracos contra o\ntipo do seu.",
  ["4b:c957"] = "ro?",
  ["4b:ca00"] = "e\vPOKéMONS pássaros\vlendários?",
  ["4b:cc00"] = "POKéMON, e eu\nposso ver que\vvocê também é.",
  ["4b:d24a"] = "isa que já\vme aconteceu\vfoi descobrir\vPOKéMONS.",
  ["4b:d346"] = "espeito.",
  ["4b:da00"] = "gares\ndesconhecidos e\vconheça pessoas…\fEstes são\nmotivos para\vviajar.",
  ["4b:e755"] = "ia.\fQuando jovem, fui\na JOHTO para\vtreinar.\fVocê se parece\nmuito comigo,\vquando eu era\vapenas um jovem.\fEi. Quero que\nfique com este\vitem.\fAchei em JOHTO.",
  ["4c:40bc"] = "ANN & ANNE: Você\né mau!",
  ["4c:40d5"] = "ANN: Eu sei o que\nminha irmã e meus\fPOKéMON estão\npensando.",
  ["4c:410f"] = "ANNE: Eu e a ANN\nestamos nisso\vjuntas!",
  ["4c:4138"] = "ANN & ANNE: Você\né mau!",
  ["4c:4151"] = "ANNE: Sentimos o\nmesmo que os\vnossos POKéMON.",
  ["4c:4180"] = "POKéMON não fazem\nnada se estiverem\vdormindo.\fVou mostrar como\nisso é assustador",
  ["4c:41ca"] = "Perdi. Que\ntristeza…",
  ["4c:41e5"] = "Fazer o POKéMON\ndormir ou deixar\vele paralisado são\vboas técnicas.",
  ["4c:422d"] = "SUNNY: Oi!\fEu sou o SUNNY de\nsábado, ou seja,\vhoje é sábado!",
  ["4c:4269"] = "Me disseram para\nte dar isso se eu\vte visse!",
  ["4c:4294"] = "SUNNY: Aquilo…\fHum…\f…O que era mesmo…\f…\fAh! Lembrei!\nUm POKéMON que\ftem golpes\nelétricos devia\fsegurar.\nMinha irmã MONICA\fdisse que aumenta\nos golpes\velétricos!",
  ["4c:4300"] = "e que isso\vmelhora golpes do\vtipo elétrico!",
  ["4c:4336"] = "SUNNY: Minhas\nirmãs e meus ir-\vmãos são MONICA,\vTUSCANY, WESLEY,\vARTHUR, FRIEDA e\fSANTOS. Eles são\ntodos mais velhos",
  ["4c:43a8"] = "SUNNY: Hoje não\né sábado?\vHum… Esqueci!",
  ["4c:43d1"] = "ROUTE 37",
  ["4c:45d6"] = "Dá vontade de sair\nvoando agora.",
  ["4c:45f9"] = "Pretendo treinar\nem CIANWOOD CITY\fpara meu POKéMON\naprender a voar.",
  ["4c:4638"] = "Deixa eu tentar\numa coisa que\vaprendi hoje.",
  ["4c:4661"] = "Acho que não\nestudei bastante.",
  ["4c:4681"] = "Tenho tantas\nprovas para fazer\fque sobra pouco\ntempo pro POKéMON\fEntão quando dá\npara jogar, eu me\vconcentro mesmo.",
  ["4c:46f0"] = "Você é bom em\ntreinar?\fSe for, pode me\nmostrar como?",
  ["4c:472e"] = "Entendi. Então dá\npara lutar assim.",
  ["4c:4752"] = "Eu sei de uma\nboa!\fO leite da MOOMOO\nFARM é famoso pelo\vsabor.",
  ["4c:4796"] = "Oi! Que treinador\nfofo você é!\fPosso ver seus\nPOKéMON?",
  ["4c:47ca"] = "Que bom que eu vi\nseus POKéMON!",
  ["4c:47eb"] = "Quando vejo POKé-\nMON, meus nervos\vse acalmam.",
  ["4c:481d"] = "Já estive no\nexterior, então\fconheço todo tipo\nde POKéMON!",
  ["4c:4856"] = "Sua habilidade é\nde nível mundial!",
  ["4c:4872"] = "Todo tipo de\ngente pelo mundo\fvive feliz com\nos POKéMON.",
  ["4c:48b2"] = "ROUTE 38\fOLIVINE CITY -\nECRUTEAK CITY",
  ["4c:48d9"] = "TRAINER TIPS\fSe um POKéMON está\ntentando evoluir,\vdá para impedir.\fAperte o Botão B\ndurante a evolu-\vção.\fIsso assusta o\nPOKéMON e para a\vevolução dele.",
  ["4c:495a"] = "hoje.",
  ["4c:4acc"] = "Acabei de voltar\npara OLIVINE.\fQue tal uma\nbatalha POKéMON?",
  ["4c:4b10"] = "Meus POKéMON foram\npegos e criados\vno exterior.\fSão meus compa-\nnheiros nas longas\vviagens.",
  ["4c:4b68"] = "Você se importa se\neu me gabar dos\vmeus POKéMON?",
  ["4c:4b94"] = "Nem consigo me\ngabar…",
  ["4c:4bae"] = "Não vou ouvir\nvocê se gabar!\fNós POKé FANS\ntemos a regra de\fnão ouvir os\noutros se gabarem",
  ["4c:4c11"] = "Que POKéMON\nqueridos.\fVamos mostrar os\nnossos POKéMON\vao mesmo tempo.",
  ["4c:4c53"] = "Não me importo\nde perder.",
  ["4c:4c68"] = "Você conhece os\nPOKéMON bebês?\fAposto que são\nadoráveis!",
  ["4c:4ca2"] = "Deixa eu ver do\nque os seus\vPOKéMON são bons.",
  ["4c:4ccd"] = "Ooh, seus POKéMON\ntêm potencial.",
  ["4c:4ced"] = "Sabe como cada\nPOKéMON tem uma\vhabilidade?\fCom gente é igual\nCada um tem um\vpotencial dife-\vrente.",
  ["4c:4d5a"] = "ROUTE 39\fOLIVINE CITY -\nECRUTEAK CITY",
  ["4c:4d81"] = "MOOMOO FARM\fProve Nosso Leite\nFresco e Saboroso",
  ["4c:4dad"] = "TRAINER TIPS\fUse HEADBUTT nas\nárvores para der-\vrubar POKéMON.\fTipos diferentes\nde POKéMON caem\vdas árvores.\fUse HEADBUTT em\ntoda árvore!",
  ["4c:4fc3"] = "Tá! Chega! Perdi!",
  ["4c:4fd7"] = "CIANWOOD CITY fica\nbem longe\vdaqui.",
  ["4c:5009"] = "Um jovem como\nvocê devia nadar.\fNão use SURF no\nseu POKéMON.",
  ["4c:5054"] = "Nadar exercita\no corpo inteiro.\vÉ saudável.",
  ["4c:5087"] = "Você vai para\nCIANWOOD?\fQue tal uma luta\nrápida antes?",
  ["4c:50c3"] = "Perdi essa!",
  ["4c:50d5"] = "Eu diria que nado\nmelhor que você.\vÉ isso aí!",
  ["4c:5103"] = "Boia não é\ncomigo.\fEstou agarrado a\num POKéMON do mar",
  ["4c:5137"] = "Ooh, estou ficando\ntonto!",
  ["4c:514f"] = "Enquanto eu boio\nassim, as ondas\vme levam.",
  ["4c:5183"] = "Mesmo não\nvendo daqui,\fCIANWOOD fica\ndo outro lado",
  ["4c:51c4"] = "MONICA: Prazer, eu\nsou a MONICA de\fsegunda.",
  ["4c:51f4"] = "Em sinal de\namizade, um pre-\vsente pra você!",
  ["4c:522a"] = "MONICA: É um\nitem que aumenta\fo poder de golpes\nde voar.\fEquipe um POKéMON\npássaro com\vesse item.",
  ["4c:529a"] = "MONICA: Meus\nirmãos e irmãs\festão espalhados\npor aí.\fTente encontrá-\nlos todos!",
  ["4c:52f5"] = "MONICA: Acho que\nhoje não é\vsegunda. Triste…",
  ["4c:5300"] = " horrível.",
  ["4c:5325"] = "ROUTE 40\fCIANWOOD CITY -\nOLIVINE CITY",
  ["4c:54e4"] = "Eita! Minha pele\nestá enrugada!",
  ["4c:5500"] = "Não é relaxante\nsó boiar assim?\vNé?",
  ["4c:552b"] = "Estou cansado.\nSe eu ganhar, me\vempreste um.",
  ["4c:5566"] = "É tão longe até\nCIANWOOD.\fMas voltar para\nOLIVINE também\vnão é fácil.\fO que eu faço?",
  ["4c:55c0"] = "Viu aquelas ilhas\nbloqueadas por\vredemoinhos?\fTem que ter um\nsegredo ali!",
  ["4c:5612"] = "Qual é o segredo\nda sua força?",
  ["4c:5636"] = "Era uma noite\nescura e de\ftempestade… Eu vi\num POKéMON gigante\vvoando das ilhas.\fEle espalhava\npenas das asas\vprateadas dele.",
  ["4c:5648"] = "\fEu vi esse\ngigante POKéMON\vvoando nas ilhas.\fEstavam espalhadas\npenas das suas\vasas prateadas.",
  ["4c:56b8"] = "As ondas aqui\nsão bravas.\fElas cansam a\ngente na nadada.",
  ["4c:56fe"] = "As correntes não\nme deixam chegar\vnaquela ilha.",
  ["4c:5700"] = "s me\nmantém fora do\valcance daquela\vilha.",
  ["4c:572f"] = "Você busca os\nsegredos das\vWHIRL ISLANDS?",
  ["4c:575e"] = "Ooh, você tem\nmuito fôlego!",
  ["4c:577f"] = "Um segredo das\nWHIRL ISLANDS…\fLá dentro é\nescuro total!",
  ["4c:57b6"] = "Estou indo para\nas WHIRL ISLANDS.\fVou explorar com\nuns amigos.",
  ["4c:57f9"] = "É assim que se\nfaz?",
  ["4c:5811"] = "Dizem que tem um\nPOKéMON enorme lá\vno fundo das\vWHIRL ISLANDS.\fO que será que\npode ser?",
  ["4c:586c"] = "Você fica tão\nelegante montado\vno seu POKéMON.",
  ["4c:58a3"] = "Não tinha uma\nmúsica sobre um\vmenino no LAPRAS?",
  ["4c:58d8"] = "O tempo está tão\nlindo que eu fico\vabobado!",
  ["4c:590b"] = "Queimadura de sol\né ruim pra pele.\fMas eu não uso\nprotetor.\fNão vou poluir\na água.",
  ["4c:5955"] = "onheço algo\nbom!\fO leite da FAZENDA\nMOOMOO é famoso\vpelo sabor.",
  ["4c:5962"] = "Se precisar\ndescansar, é só\vboiar.\fVocê recupera o\nfôlego e pode\fseguir em frente\ncom força.",
  ["4c:59c5"] = "Oh! Você tem mais\nenergia que eu.",
  ["4c:59ea"] = "Ouvi rugidos lá\ndo fundo das\vISLANDS.",
  ["4c:5a17"] = "À noite, STARYU\nse juntam perto\vda superfície.",
  ["4c:5a54"] = "Os cardumes de\nSTARYU acendem\vao mesmo tempo.\fÉ tão bonito que\nchega a assustar.",
  ["4c:5c4a"] = "O quê? Isso não\nestá certo.",
  ["4c:5c62"] = "Quero virar o\ntreinador CAMPEÃO\fcom os POKéMON\nque eu pesquei.\fÉ a melhor parte\nde pescar!",
  ["4c:5cbf"] = "Ah, que bom estar\nao ar livre!\vMe sinto livre!",
  ["4c:5cf6"] = "Perder parece\npouca coisa se\fvocê olha para o\ncéu enorme!",
  ["4c:5d33"] = "EI!\fEste é o meu lugar\nsecreto! Some,\vseu forasteiro!",
  ["4c:5d6a"] = "Devia ter usado\na MOON STONE…",
  ["4c:5d8d"] = "Você está fazendo\numa POKéDEX?\fUau, deve conhecer\nalguns POKéMON\vbem raros!\fPosso ver?\nPor favor?",
  ["4c:5dee"] = "ROUTE 42\fECRUTEAK CITY -\nMAHOGANY TOWN",
  ["4c:5e16"] = "MOUNT MORTAR\fWATERFALL CAVE\nInterior",
  ["4c:5e3a"] = "MOUNT MORTAR\fWATERFALL CAVE\nInterior",
  ["4c:5e57"] = "       ROTA 42\fCIDADE ECRUTEAK-\nCIDADE MAHOGANY.",
  ["4c:5e5e"] = "ROUTE 42\fECRUTEAK CITY -\nMAHOGANY TOWN",
  ["4c:9200"] = "reino\nPOKéMONS?\fPorque eles estão\nlá!",
  ["4c:9300"] = "o.",
  ["4c:c34f"] = "ém o\nCOME SONHOS\f…\fZzz…",
  ["4c:ca41"] = "gar…   \fBom, o que você\nquer? Quer me\vdesafiar ou é\voutra coisa?\f…Eu odeio dizer\nisso, mas estou\vsem ânimo para\vbatalhar agora.\fDê uma olhada ao\nseu redor…\fUm vulcão entrou\nem eurupcão, e\visso fez uma\vcidade inteira\vdesaparecer.\fNós podemos vencer\ne perder com os\vPOKéMONS.\fSe não ficarmos\natentos, podemos\vperder em um\vsegundo.\f…\fAs coisas\nfuncionam desse\vmodo…\fMas, eu ainda sou\num treinador.\fSe eu vir um\noponente forte,\vfico com vontade\vde batalhar.\fSe quiser batalhar\ncomigo, venha ao\vGINÁSIO DE\vVERIDIANA.\fLá eu aceitarei\no seu desafio.",
  ["4c:cd4c"] = "ais\nleve na água.",
  ["4c:df00"] = "ound para\ntodos.\fCASA DE JOGOS DE\nCELADON.",
  ["4c:e100"] = "tes locais,\vo CAMINHO\vSUBTERRÃNEO foi\vselado por tempo\vindeterminado.\fPOLÍCIA DE\nCELADON.",
  ["4d:41d8"] = "Como você pôde\nfazer isso comigo",
  ["4d:41f6"] = "Do que mais eu\ngosto além de\vPOKéMON?\fA MARY do rádio.\nDeve ser fofa!",
  ["4d:423d"] = "Ei! Você tem algum\nPOKéMON raro?",
  ["4d:425e"] = "Ah, meus pobres\nPOKéMON queridos!",
  ["4d:427d"] = "Eu ficaria feliz\nsó de ter um\vPOKéMON raro.",
  ["4d:42aa"] = "Você acredita\nnisso?\fUm cara chamado\n{RIVAL} zoou os\vmeus POKéMON!\fDroga! Meu POKéMON\né ótimo!",
  ["4d:42fa"] = "Meu NIDOKING foi\nmuito bem!",
  ["4d:431c"] = "Não tem problema\nas pessoas gos-\ftarem de tipos\ndiferentes.\fPOKéMON não é só\nter o mais\vpoderoso.",
  ["4d:435c"] = "-me\vcontar a você!",
  ["4d:4385"] = "Estou numa fase\fDeve ser o\nequipamento.\fVamos lutar para\nmudar o clima!",
  ["4d:43d4"] = "Perdi, mas me\nsinto melhor.",
  ["4d:43f7"] = "A LURE BALL do\nKURT é a melhor\fpara pegar POKéMON\nfisgado.\fÉ bem mais\neficaz que uma\vULTRA BALL.",
  ["4d:4459"] = "Dá para fazer\ntanta coisa com\vmeu POKéMON!",
  ["4d:4489"] = "Perder não tem\ngraça nenhuma…",
  ["4d:44a2"] = "O que está\nhavendo no LAKE?\fA gente ia\nacampar lá.",
  ["4d:44e5"] = "Você também vai\nao LAKE OF RAGE?\fVamos brincar um\npouquinho!",
  ["4d:4528"] = "Brinquei demais!",
  ["4d:453c"] = "Estou num pique-\nnique com POKéMON\fNão quer vir?",
  ["4d:456f"] = "ROUTE 43\fLAKE OF RAGE -\nMAHOGANY TOWN",
  ["4d:4596"] = "ROUTE 43\fLAKE OF RAGE -\nMAHOGANY TOWN",
  ["4d:45bd"] = "TRAINER TIPS\fTodo POKéMON tem\nprós e contras\fconforme o tipo\ndele.\fSe os tipos são\ndiferentes, um de\fnível mais alto\npode até perder.\fAprenda que tipos\nsão fortes e\ffracos contra o\nseu POKéMON.",
  ["4d:48d1"] = "Deixa pra\nlá.",
  ["4d:48e8"] = "Aquele POLIWAG\nque escapou…\vEra enorme.\fJuro que tinha uns\n5 metros!",
  ["4d:4900"] = "a\vgrande.\fEu juro, ele tinha\nuns 5 metros de\valtura!",
  ["4d:4937"] = "Eu pesco até não\naguentar mais.\fE luto até\ncair também.\fÉ essa a minha\nrelação com os\vmeus POKéMON.",
  ["4d:4995"] = "Hmmmm…\nNão está certo.",
  ["4d:49af"] = "São 100 vitórias\ne 101 derrotas.\fNão vou lutar de\nnovo tão cedo.",
  ["4d:49ef"] = "Você conhece os\nPOKéMON pássaro\vlendários?",
  ["4d:4a1b"] = "Ufa! Você é bom\nmesmo.",
  ["4d:4a33"] = "ARTICUNO, ZAPDOS\ne MOLTRES são\fos três POKéMON\npássaro lendários\fMas ouvi que tem\noutros pássaros\vlendários também.",
  ["4d:4aa7"] = "Eu vou ganhar,\ncom certeza!",
  ["4d:4ac0"] = "Arrgh… Que\nderrota chocante…",
  ["4d:4adf"] = "É importante ter\nconvicção do seu\vlado.",
  ["4d:4b0f"] = "Faço qualquer\ncoisa para pôr a\vmão em raros!",
  ["4d:4b3e"] = "Oooh, seus POKéMON\nsão atraentes.",
  ["4d:4b61"] = "Se um POKéMON tem\ncores diferentes\fdo normal, ele\nvale mais.\fO quê? Isso não\né verdade?",
  ["4d:4bbf"] = "Dá para ver que\nvocê é um bom\vtreinador.\fEu sou bom em\nPOKéMON e vejo que\vvocê também é.",
  ["4d:4c00"] = "POKéMON, e eu\nposso ver que\vvocê também é.",
  ["4d:4c26"] = "Tch! Foi derrota\ntotal pra mim.",
  ["4d:4c49"] = "Uau. Você tem\nmuitas BADGES.\fNão é à toa que\né tão forte.\fSerá que o MORTY\ndo GINÁSIO de\fECRUTEAK ainda\nestá treinando?\fEle me arrebentou\nfeio.",
  ["4d:4cd0"] = "Você parece forte\fBons treinadores\nprocuram rivais\vfortes por si.",
  ["4d:4d14"] = "Não! Assim não\ndá mesmo.",
  ["4d:4d30"] = "A gente melhora\nvivendo muitas\vbatalhas.\fLutei muito para\nser o que sou\vhoje, uma elite.",
  ["4d:4d96"] = "ROTA 44\nICE PATH a frente",
  ["4d:4daf"] = "ROTA 44\fMAHOGANY TOWN -\nBLACKTHORN CITY",
  ["4d:504b"] = "Vou voltar para o\nICE PATH de\fBLACKTHORN e\ntreinar mais.",
  ["4d:5087"] = "Ei! Você tem gar-\nra! Mas sabe?\fQuando o assunto\né garra pura,\vo cara sou eu!",
  ["4d:50dc"] = "Meus POKéMON não\ntiveram garra!",
  ["4d:50fb"] = "Nossa, como eu\namo PS UP! Hmmm!\fFico bebendo o\ndos meus POKéMON!\fNão me controlo!",
  ["4d:5147"] = "Meus POKéMON são\npura força!",
  ["4d:5162"] = "Uahahah! Eu sou o\ngrande perdedor!",
  ["4d:517e"] = "Eu não sou bom de\npensar, sabe?\fEntão eu vou de\nforça mesmo!",
  ["4d:51c4"] = "Por que eu subo\nmontanhas?\fPorque elas estão\nlá.\fPor que eu treino\nPOKéMON?\fPorque eles estão\nlá!",
  ["4d:5220"] = "Derrotas…\nTambém estão lá!",
  ["4d:523b"] = "A melhor coisa\nque já me acon-\fteceu foi conhecer\nPOKéMON.",
  ["4d:5256"] = "e aconteceu\vfoi descobrir\vPOKéMONS.",
  ["4d:5276"] = "Eu estava treinan-\ndo sozinho aqui.\fVeja o fruto do\nmeu trabalho!",
  ["4d:52bc"] = "Isso pede medidas\nextremas.\fVou para as monta-\nnhas treinar na\vsolidão.",
  ["4d:530e"] = "O que você acha\nsobre criar\vPOKéMON?",
  ["4d:5339"] = "Você ganhou meu\nrespeito.",
  ["4d:5350"] = "Vejo que você cria\nos seus POKéMON\vcom carinho.\fO laço que vocês\ncriam vai salvar\vvocê nos apertos.",
  ["4d:53b2"] = "Qual é a sua\nestratégia?\fÉ tolice usar\ngolpes fortes\vsem critério.",
  ["4d:5414"] = "Não sou a favor\nde golpes fortes\vdemais.\fQuero ganhar, mas\ntambém não quero\vferir POKéMON.",
  ["4d:5473"] = "Eu também sou bom\nde POKéMON.",
  ["4d:5490"] = "ROTA 45\nMONTANHA a frente",
  ["4d:5652"] = "Piedade! Você me\nmostrou a força!",
  ["4d:5674"] = "Acabou. Tudo bem.\nNós HIKERS somos\vassim mesmo.",
  ["4d:56a5"] = "Eu também crio\nPOKéMON!\fQuer batalhar\ncomigo?",
  ["4d:56dd"] = "Dei o meu melhor\ne não bastou.\fSem desculpa, eu\nadmito que perdi.",
  ["4d:571b"] = "Eu também crio\nPOKéMON!\fVamos lutar!",
  ["4d:5749"] = "Já fui a muitos\nGINÁSIOS, mas o\fde GOLDENROD é o\nmeu favorito.\fEle é cheio de\nflores lindas!",
  ["4d:57aa"] = "ROTA 46\nMONTANHA a frente",
  ["4d:588a"] = "Já visitou o\nPEWTER GYM?\fO LÍDER usa\nPOKéMON de pedra.",
  ["4d:58c8"] = "De noite, CLEFAIRY\nvêm pra brincar no\vMT.MOON.\fMas nem toda\nnoite.",
  ["4d:590e"] = "Ah, você veio\nde tão longe, de\vJOHTO?\fIsso traz memó-\nrias. Quando eu\fera jovem, ia\na JOHTO treinar.\fVocê me lembra\nmuito do que eu\fera, jovem como\nvocê.\fQuero que fique\ncom um item que\vachei em JOHTO.",
  ["4d:59f2"] = "Ir a lugares\nnovos, conhecer\vgente nova…\fEssa é a alegria\nde viajar.",
  ["4d:5a47"] = "PEWTER CITY\nA Cidade Cinzenta",
  ["4d:5a66"] = "PEWTER CITY\nPOKéMON GYM\vLÍDER: BROCK\fO Treinador\nde pedra",
  ["4d:5aa6"] = "Há um aviso…\naqui…\fPEWTER MUSEUM OF\nSCIENCE está\vfechado…",
  ["4d:5af1"] = "Há um aviso…\nLOJA do\fMT.MOON GIFT SHOP\nagora aberta!",
  ["4d:5b24"] = "Bem-vindo a\nPEWTER CITY!",
  ["4d:5c53"] = "Vou procurar\nPOKéMON inseto\vmais fortes.",
  ["4d:5c7c"] = "Se você anda no\nmato alto de\fshorts, se corta\ntodo?",
  ["4d:5cc2"] = "Ai, ai, ai!",
  ["4d:5cd5"] = "Arde de verdade\nquando você toma\vbanho.",
  ["4d:5d00"] = "Por que as meninas\nnão gostam deles?",
  ["4d:5d29"] = "POKéMON inseto\nafundam feito\fpelúcia quando\nvocê aperta.\fEu adoro essa\nsensação!",
  ["4d:5d80"] = "ROUTE 2\fVIRIDIAN CITY -\nPEWTER CITY",
  ["4d:5da5"] = "CAVERNA DIGLETT",
  ["4d:8300"] = "veio este\nTM?\fIsto é\nfantasmagórico!\fEi, pode ficar\ncom este TM.",
  ["4d:8944"] = "scaria…",
  ["4d:9549"] = "AFARI ZONE OFFICE\nestá fechado até\vaviso posterior.",
  ["4d:c25c"] = "de\vaprender isso na\vminha aula de\vjaponês.",
  ["4d:ce00"] = "amos fazer uma\nbatalha justa!",
  ["4d:d148"] = "OWN\fA Nobre Cidade\nRoxa",
  ["4d:d443"] = "blema na USINA\vDE ENERGIA for\vresolvido.",
  ["4d:d656"] = "tipos devem dar\fuma vantagem\nna batalha.\fTenho certeza que\nas INSÍGNIAS de\vKANTO ajudarão.",
  ["4d:d700"] = "E\vSURGE\fO Trovão\nAmericano.",
  ["4d:d841"] = "roblema na USINA\vDE ENERGIA for\vresolvido.",
  ["4d:dc50"] = " primeira vez\vme deixa muito\vancioso.",
  ["4d:e200"] = "CONFUSÃO!",
  ["4e:4062"] = "Ei, garoto! Acabei\nde tomar um café\fbem forte e estou\nligado no 220!\fPreciso conversar\ncom alguém, e\vvocê vai servir!\fPode não parecer,\nmas eu era expert\fem capturar POKé-\nMON.\fAcredita em mim?",
  ["4e:412c"] = "Bom, bom. Sim, eu\nera alguém fora\fdo comum, posso\ndizer!",
  ["4e:4174"] = "O quê? Seu mole-\nque!\fSe eu fosse um\npouco mais jovem,\feu te mostraria\numa ou duas. Tsc!",
  ["4e:41ce"] = "Este GINÁSIO não\ntinha um LÍDER\vaté pouco tempo.\fUm rapaz de\nPALLET virou o\fLÍDER, mas vive\nfora.",
  ["4e:423b"] = "Vai encarar o\nLÍDER?\fBoa sorte.\nVai precisar.",
  ["4e:4281"] = "Bocejo!\fDevo ter dormido\nno sol.\f…Tive um sonho\ncom um DROWZEE\fcomendo meu sonho.\nEstranho, né?\fHã?\nO que é isto?\fDe onde veio\nessa MT?\fQue sinistro!\nTome, pode ficar\vcom esta MT.",
  ["4e:4343"] = "A MT42 contém\nDREAM EATER…\f…Zzzzz…",
  ["4e:4367"] = "Ouvi dizer que há\nmuitos itens no\fchão da\nVIRIDIAN FOREST.",
  ["4e:43ac"] = "VIRIDIAN CITY\fO Paraíso Verde\nEterno",
  ["4e:43d8"] = "VIRIDIAN CITY\nPOKéMON GYM\vLÍDER: …\fO resto do texto\nestá ilegível…",
  ["4e:441d"] = "Bem-vindo a\nVIRIDIAN CITY,\fa Porta de Entrada\nda INDIGO PLATEAU",
  ["4e:4456"] = "TRAINER HOUSE\fO Clube das Lutas\nentre Treinadores",
  ["4e:44fc"] = "LIGA POKéMON\fVICTORY ROAD\nENTRADA",
  ["4e:4592"] = "Aah… Perco mais\ndo que ganho…",
  ["4e:45b2"] = "Para treinadores,\né lei que a gente\fbatalhe sempre que\nse encontra.",
  ["4e:45f0"] = "Ei, você aí!\nQuer batalhar?",
  ["4e:461b"] = "Você é forte.\fDá para ver que\ntreinou bastante.",
  ["4e:4650"] = "ROUTE 1\fPALLET TOWN -\nVIRIDIAN CITY",
  ["4e:46c2"] = "Eu também crio\nPOKéMON.\fEles servem de\nmeus guardas",
  ["4e:46fb"] = "Tecnologia é\nincrível!\fDá pra trocar\nPOKéMON no tempo\vcomo e-mail.",
  ["4e:4746"] = "PALLET TOWN\fUm lugar sereno,\nde paz e pureza",
  ["4e:4778"] = "CASA do RED",
  ["4e:4785"] = "LABORATÓRIO de\nPESQUISA do OAK",
  ["4e:479c"] = "CASA do BLUE",
  ["4e:484e"] = "Esse cara metido\nestava no vulcão\vde CINNABAR.",
  ["4e:487b"] = "Oi!\fEu ia justamente\npassar protetor\vsolar.",
  ["4e:48ab"] = "Estou preocupada\ncom queimadura…",
  ["4e:48c6"] = "Tenho que tomar\ncuidado com as\vmanchas do sol.",
  ["4e:48fc"] = "Cansei de pescar.\nVamos batalhar!",
  ["4e:4900"] = "r!\fVamos batalhar!",
  ["4e:4921"] = "Fracasso total…",
  ["4e:4931"] = "Vou voltar a\npescar…",
  ["4e:49a7"] = "Quem é você?\fBem, é óbvio\nque você é um\vtreinador…\fMeu nome é BLUE.\fEu já fui o\nCAMPEÃO, embora\ftenha sido por\npouco tempo…\fAquele RED\nme venceu…\fEnfim, o que\nvocê quer? Quer\fme desafiar ou\no quê?\f…Detesto dizer,\nmas não estou a\ffim de lutar\nagora.\fOlhe ao seu\nredor…\fUm vulcão entra\nem erupção, e de\frepente, uma\ncidade some.\fPodemos ganhar\ne perder em lutas\fde POKéMON. Mas\nse a natureza se\fmexer, morremos\nnum segundo.\f…\fÉ assim que as\ncoisas são…\fMas, enfim, ainda\nsou treinador.\fSe vejo um\nadversário bom,\vme dá vontade de\flutar.\nSe quiser,\vvá ao GINÁSIO de\fVIRIDIAN. Vou te\nenfrentar.",
  ["4e:4c48"] = "Há um aviso…\naqui…\fO GINÁSIO de CIN-\nNABAR mudou para\vas ILHAS SEAFOAM.\fBLAINE",
  ["4e:4c97"] = "CINNABAR ISLAND\fA Cidade Fogo de\nDesejo Ardente",
  ["4e:4d68"] = "Nadar exercita\no corpo inteiro.\fFaz muito bem\npara você.",
  ["4e:4da5"] = "Que coleção de\nBADGES impressio-\fnante. Vamos\nbatalhar!",
  ["4e:4dea"] = "SURF já não é o\núnico golpe de HM\vque serve na água",
  ["4e:4e20"] = "Acho impossível\nnadar todo o\fcaminho até\nJOHTO.",
  ["4e:4e60"] = "Além do mar, eu\ntambém nado em\vlagos e rios.",
  ["4e:4e97"] = "O que este cartaz\ndiz?\fCINNABAR GYM\nLÍDER: BLAINE",
  ["4e:4fdf"] = "À noite o mar\nfica preto.\fParece que ele vai\nte engolir.",
  ["4e:5025"] = "Ofego, ofego…\nSó… mais… um…\fpouco… até…\nFUCHSIA…",
  ["4e:5066"] = "Eu… pedi para a\nminha namorada\vnadar até FUCHSIA",
  ["4e:509a"] = "Tenho nojo de\ngente banana!",
  ["4e:50b9"] = "Eu ganharia de\nvocê na natação…",
  ["4e:50d8"] = "É uma nadada bem\ncurta entre\fFUCHSIA e as\nSEAFOAM ISLANDS…\fPuxa, que homem\ngrande o meu\fnamorado! Banana!",
  ["4e:5100"] = "AS SEAFOAM…\fNossa, meu\nnamorado é um\vhomenzarrão!\fQue tolo!",
  ["4e:5144"] = "Nadar?\nEu sou péssimo.\fSó fico chapinhan-\ndo nesta água\vrasa aqui.",
  ["4e:5191"] = "Achei que eu ia\nganhar.",
  ["4e:51a9"] = "Posso ser ruim de\nnatação, mas eu\vamo o mar.",
  ["4e:51da"] = "Desculpe. Esta\nestrada está em\vobras.\fSe quiser chegar\na CINNABAR, é\fmelhor ir pro sul\nde PALLET TOWN.",
  ["4e:524f"] = "Estou todo suado.\nHora de nadar!",
  ["4e:5270"] = "Quem sabe quanto\ntempo pra mover\veste pedregulho…",
  ["4e:52a8"] = "As obras na estra-\nda terminaram.\fAgora posso\nvoltar a pescar.",
  ["4e:52e7"] = "ROUTE 19\fFUCHSIA CITY -\nSEAFOAM ISLANDS",
  ["4e:5310"] = "Atenção: cuidado\nao nadar até as\vSEAFOAM ISLANDS.\vPOLÍCIA de\fFUCHSIA",
  ["4e:53eb"] = "Um dos ELITE\nFOUR já foi o\fLÍDER do GINÁSIO\nde FUCHSIA.",
  ["4e:5429"] = "A filha do KOGA\nvirou o LÍDER do\fGINÁSIO depois\nque ele entrou no\vELITE FOUR.",
  ["4e:5479"] = "A SAFARI ZONE está\nfechada… Que\fpena, era a\nmaior atração\vde FUCHSIA.",
  ["4e:54c8"] = "FUCHSIA CITY\fVeja! É o Rosa\nda Paixão!",
  ["4e:54f0"] = "FUCHSIA CITY\nPOKéMON GYM\vLÍDER: JANINE\fA Mestra Ninja\ndos Venenos",
  ["4e:5531"] = "Há um aviso…\nO ESCRITÓRIO da\fSAFARI ZONE está\nfechado até\vnovo aviso.",
  ["4e:557b"] = "SAFARI ZONE\nCASA do GUARDIÃO",
  ["4e:5596"] = "O GUARDIÃO está\nno exterior.\fPor isso, a\nSAFARI ZONE está\vfechada.",
  ["4e:55dd"] = "Não jogue lixo.\fLeve seu lixo\ncom você.",
  ["4e:56d3"] = "Se você procura\nPOKéMON, tem que\folhar no mato\nalto.",
  ["4e:571c"] = "Como você é forte\ndeve ser divertido\vbatalhar.",
  ["4e:574e"] = "A CYCLING ROAD é\num atalho rápido\vpara CELADON.",
  ["4e:5784"] = "Se você não tem\numa BICYCLE, não\fpode usar o\natalho.",
  ["4e:57c8"] = "ROUTE 18\fCELADON CITY -\nFUCHSIA CITY",
  ["4e:58b2"] = "Não se ache,\nmoleque de JOHTO!",
  ["4e:58d3"] = "Uau. Que BICYCLE\nmaneira!",
  ["4e:58ef"] = "Mas você não é só\naparência…",
  ["4e:590d"] = "Eu pareço maneiro\nmas sou fraco, e\vaí não sou nada.\fTenho que treinar\nmais…",
  ["4e:5957"] = "Ei! Quer fazer uma\nbatalha rápida?",
  ["4e:597a"] = "Eita! Você tem um\ntorque incrível!",
  ["4e:599c"] = "Andar sem as mãos\né considerado bom\vna CYCLING ROAD.",
  ["4e:59d3"] = "Somos as estrelas\nsem medo da via!",
  ["4e:59f1"] = "Arrrgh! Bati e\ncapotei!",
  ["4e:5a0a"] = "Direção imprudente\ncausa acidente!\vVá com calma!",
  ["4e:5aa6"] = "CYCLING ROAD\fDescida livre\naté o fim!",
  ["4e:5b3a"] = "Este POLIWRATH é\nmeu parceiro.\fSerá que um dia\nele evolui para\vPOKéMON sapo.",
  ["4e:5b9b"] = "Perdi de novo no\ncaça-níquel…\fAgora as garotas\ntambém jogam.\fVocê devia dar\numa olhada.",
  ["4e:5c00"] = "Os GRIMER têm\naparecido muito.\fViu o lago na\nfrente da casa?\fOs GRIMER vivem\nlá agora.\fDe onde saíram?\nIsto é um pro-\vblema sério…",
  ["4e:5c99"] = "Nihihi! Este\nGINÁSIO é ótimo!\fSó entra garota\naqui!",
  ["4e:5cd2"] = "Quer saber um\nsegredo?\fA CELADON MANSION\ntem uma porta se-\vcreta.",
  ["4e:5d00"] = "porta\vnos fundos.",
  ["4e:5d12"] = "Está rolando um\nconcurso de comer\vno restaurante.\fSó de ver eles\ncomendo, já me\vsinto inchado…",
  ["4e:5d7a"] = "A CELADON DEPT.\nSTORE tem a maior\fe melhor seleção\nde mercadorias.\fSe não achar\nlá, não acha em\flugar nenhum.\nNossa… pareço\fum vendedor de\nloja.",
  ["4e:5e18"] = "De olhar pro\nchão enquanto an-\fdava, fiquei\ntonto.",
  ["4e:5e52"] = "CELADON CITY\fA Cidade dos\nSonhos Coloridos",
  ["4e:5e7b"] = "CELADON CITY\nPOKéMON GYM\vLÍDER: ERIKA\fA Princesa que\nama a Natureza",
  ["4e:5ebb"] = "Ache tudo o que\nvocê precisa na\vCELADON DEPT.",
  ["4e:5ee6"] = "CELADON MANSION",
  ["4e:5ef7"] = "A diversão de to-\ndos, CELADON GAME\vCORNER",
  ["4e:5f2a"] = "DICAS de TREINO\fGUARD SPEC.\nprotege POKéMON\fcontra ataques\nSPECIAL, como\vfogo e água.\fCompre seus itens\nna CELADON DEPT.\vSTORE!",
  ["4e:5f4d"] = "a.",
  ["4e:6081"] = "Que aviso é esse?\f…Os treinadores\nmal-educados têm\fbatalhado no\nUNDERGROUND PATH.\fPor causa das re-\nclamações dos\vmoradores locais,\vo UNDERGROUND\vPATH foi lacrado\vindefinidamente.\fCELADON POLÍCIA",
  ["4e:614f"] = "Está trancado…",
  ["4e:9151"] = "ão queria\nperder…",
  ["4e:a158"] = " mas\vparece divertido.",
  ["4e:d84f"] = "em CERULEANA!",
  ["4e:e54d"] = "Qsrei\num segredo.\fMas primeiro, nós\nbatalharemos!",
  ["4f:40a6"] = "Antes de virar\nprofessor, eu\fesquecia muita\ncoisa.",
  ["4f:40e4"] = "Nos dias de sol,\nacho que as cri-\fanças prefeririam\nbrincar no pátio\fa estudar na\nsala de aula.",
  ["4f:414c"] = "Eu não queria\nperder…",
  ["4f:4163"] = "Estudar é impor-\ntante, mas se\vexercitar também.",
  ["4f:419c"] = "Espera. Preciso\nligar pra mamãe",
  ["4f:41be"] = "Desculpe, mãe!\nEu apanhei!",
  ["4f:41d9"] = "Minha mãe se\npreocupa demais\feu tenho que ligar\ntoda hora.",
  ["4f:421d"] = "Vamos batalhar.\nNão vou perder!",
  ["4f:4238"] = "Esqueci de fazer\na lição!",
  ["4f:4255"] = "Sayonara! Acabei\nde aprender isso\vna aula japonesa",
  ["4f:428a"] = "Estamos em excur-\nsão na LAVENDER\fRADIO TOWER para\nestudos sociais.",
  ["4f:42cc"] = "Você é forte\ndemais!",
  ["4f:42e3"] = "Cansei de andar.\nPreciso de uma\vpausa.",
  ["4f:4300"] = "ansar um\vpouco.",
  ["4f:4313"] = "Aula favorita?\nEducação física!",
  ["4f:432e"] = "Ah, não!\nComo eu perdi?",
  ["4f:4349"] = "Se POKéMON fosse\nmatéria na escola,\veu era o melhor!",
  ["4f:437c"] = "ROUTE 15\fFUCHSIA CITY -\nLAVENDER TOWN",
  ["4f:449e"] = "SQUIRTLE, CHARMAN-\nDER e BULBASAUR…\fAcho que é uma boa\nmistura.",
  ["4f:44e8"] = "Meu sonho é voar\ncom meu amado\vPOKéMON pássaro.",
  ["4f:4517"] = "Posso sonhar, mas\nnunca vou voar…",
  ["4f:453a"] = "Você tem POKéMON\nque sabem o golpe\fFLY, não tem? Que\ninveja.",
  ["4f:457a"] = "Você batalhou com\ntodos do GINÁSIO?",
  ["4f:45a0"] = "Nossa! Forte\ndemais para mim!",
  ["4f:45bd"] = "Se você tem BADGES\nde KANTO, elas\fajudam nas lutas\npor link.",
  ["4f:46c7"] = "Como… Como ousa\nzombar da realeza",
  ["4f:46e8"] = "Todo mundo não\nsonha um dia ser\vum rei?",
  ["4f:4714"] = "Nihihi! Quer\nbatalhar com a\vminha gangue?",
  ["4f:4754"] = "Você parece ter\nmuitos POKéMON,\fmas PIKACHU ainda\né o melhor.",
  ["4f:4796"] = "Agilidade é o\nponto forte dos\vPOKéMON pássaro.",
  ["4f:47c2"] = "Você me venceu na\nvelocidade…",
  ["4f:47e0"] = "Seus POKéMON são\nmuito bem\vtreinados.",
  ["4f:4809"] = "Olhe os meus POKé-\nMON. Veja a cor\fe a plumagem\ndeles.",
  ["4f:484e"] = "Droga!\nNão foi bastante!",
  ["4f:4867"] = "Se escovar eles,\nPOKéMON ficam bem",
  ["4f:488b"] = "Eu devia ir ao\nROCK TUNNEL pegar\vum ONIX.",
  ["4f:48c7"] = "O relevo parece\nque não muda\vnunca.\fMas ele muda sim,\naos pouquinhos,\vcom o tempo.",
  ["4f:4921"] = "DICAS de TREINO\fOlhe! Bem ali,\nno lado esquerdo\vdo poste.",
  ["4f:4960"] = "ROUTE 13\fNorte: SILENCE\nBRIDGE",
  ["4f:4982"] = "Norte: LAVENDER\nTOWN\fOeste: FUCHSIA\nCITY",
  ["4f:4aa3"] = "Não tenho paciên-\ncia para pescar…",
  ["4f:4ac2"] = "Fico tão à vontade\npescando e ouvindo\vuma música no\vmeu rádio.",
  ["4f:4b0b"] = "Meu rádio idiota\nme distraiu!",
  ["4f:4b2b"] = "Você já ouviu as\nrádios de KANTO?\fA variedade aqui\né boa.",
  ["4f:4b74"] = "O que é mais\nimportante no\vnosso dia a dia?",
  ["4f:4ba5"] = "A resposta vem\nlogo depois!",
  ["4f:4bc4"] = "Eu acho que a\neletricidade é o\fmais importante\ndo nosso dia.\fSe não fosse,\nninguém teria\ffeito tanto\nalarde quando a\fPOWER PLANT\nparou de vez.",
  ["4f:4c40"] = "rou de\vfuncionar.",
  ["4f:4c6b"] = "Você lembra?",
  ["4f:4c7d"] = "Lembra mesmo?",
  ["4f:4c8f"] = "O puxão que você\nsente na ROD\fquando fisga um\nPOKéMON…\fÉ a melhor\nsensação para um\vpescador como eu.",
  ["4f:4cf7"] = "ROUTE 12\fNORTE: LAVENDER\nTOWN",
  ["4f:4d18"] = "ÁREA de PESCA",
  ["4f:4e25"] = "Hã? Como isso\naconteceu?",
  ["4f:4e40"] = "Lutei limpo e com\nhonra.\fNão me arrependo\nde nada.",
  ["4f:4e81"] = "Coça e faz cócega\num pouco quando\fando de shorts\nno mato.",
  ["4f:4ebf"] = "Aiaaai!\nFui pisoteado!",
  ["4f:4ed8"] = "Vou pegar mais\nPOKéMON ali\vno mato.",
  ["4f:4f09"] = "…\fPerdi de olhos\nfechados…",
  ["4f:4f2f"] = "Eu consigo ver…\fTudo o que há\npara ver em você…",
  ["4f:4f5b"] = "Não previ a sua\nforça…",
  ["4f:4f7a"] = "Força na convic-\nção…\fVocê é forte por-\nque acredita nos\vseus POKéMON.",
  ["4f:4fc6"] = "ROUTE 11",
  ["4f:5048"] = "Que prédio é\nesse, hein?\fÉ a TORRE de\nRÁDIO de KANTO.",
  ["4f:5080"] = "KANTO tem muito\nprograma de rádio",
  ["4f:50a2"] = "As pessoas vêm\nde longe para\fhomenagear as\nalmas dos POKé-\vMON.",
  ["4f:50f2"] = "Você precisa de\numa POKé FLUTE\vpra acordar POKé-\fMON. Todo treina-\ndor sabe disso!",
  ["4f:513d"] = "LAVENDER TOWN\fA Cidade Nobre\nRoxa",
  ["4f:5162"] = "RÁDIO KANTO\nSTATION\fSeus Programas\nFavoritos no Ar\v24 Horas!",
  ["4f:51a7"] = "LAVENDER VOLUN-\nTEER POKéMON",
  ["4f:51c6"] = "SOUL HOUSE\fQue as Almas dos\nPOKéMON",
  ["4f:5308"] = "VERMILION PORT é\na porta marítima\vde KANTO.\fNavios de luxo\ndo mundo todo\vaportam aqui.",
  ["4f:5362"] = "Meu POKéMON está\npreparando o ter-\vreno para a obra.\fMas não tenho\ndinheiro para co-\vmeçar…",
  ["4f:53d5"] = "Um MACHOP rosna\nenquanto pisa o\vchão para apla-",
  ["4f:5400"] = "ície.",
  ["4f:540d"] = "Há oito GINÁSIOS\nem KANTO.\fAquele prédio\ngrande é o GINÁ-\vSIO de VERMILION.",
  ["4f:5457"] = "SNORLAX ronca\ntranquilamente…",
  ["4f:5477"] = "Colocaram a POKé-\nGEAR perto do\vSNORLAX dormindo…\f…\fSNORLAX acordou!",
  ["4f:54bb"] = "Treinadores\nhabilidosos se\freúnem em KANTO.\nOs LÍDERES são\ffortes e não são\nfáceis de vencer.",
  ["4f:551e"] = "Você começou a\ncolecionar as\vBADGES de KANTO?\fVocê não acha\nque os treinadores\vdaqui são fortes?",
  ["4f:557b"] = "Acho que você\nvai acabar logo\fcom a conquista\ndos GINÁSIOS de\fKANTO.\nMe avise se\vpegar as oito",
  ["4f:55e6"] = "Parabéns!\fVocê pegou as\nBADGES de KANTO.\fTenho um prêmio\npra você.",
  ["4f:563d"] = "Uma variedade\nde tipos POKéMON\fte dá vantagem\nna batalha.\fTenho certeza\nque as GYM BADGES\vde KANTO ajudam.",
  ["4f:56ac"] = "VERMILION CITY\fO Porto dos\nBelos Pôr do Sol",
  ["4f:56da"] = "VERMILION CITY\nPOKéMON GYM\vLÍDER: LT.SURGE\fO Americano\nRelâmpago",
  ["4f:5700"] = "E\vSURGE\fO Trovão\nAmericano.",
  ["4f:571b"] = "POKéMON FAN CLUB\fTodos os Fãs de\nPOKéMON",
  ["4f:5741"] = "DIGLETT'S CAVE",
  ["4f:5751"] = "VERMILION PORT\nENTRADA",
  ["4f:5820"] = "A estrada está\nfechada até que\fo problema na\nUSINA se resolva.",
  ["4f:5864"] = "UNDERGROUND PATH\fCERULEAN CITY -\nVERMILION CITY",
  ["4f:5923"] = "Uma menininha\nexpert em imitar\fas pessoas mora\naqui.\fEla imita até\nquem está con-\fversando com ela.\nÉ confuso.",
  ["4f:59a3"] = "A menina COPYCAT\nparecia triste.\fEla disse que\nperdeu sua POKé\vDOLL, CLEFAIRY.",
  ["4f:59f6"] = "Você veio de\nJOHTO?\fVocê pode voltar\npra casa de MAGNET\vTRAIN.",
  ["4f:5a44"] = "Você veio de\nJOHTO?\fDá pra voltar\npra casa pulando\vno MAGNET TRAIN.",
  ["4f:5a94"] = "Fui ao GINÁSIO,\na fim de batalhar\vcom treinadores…\fNo fim, acabei\nentrando no GINÁ-\fSIO vago ao\nlado.\fNossa, que sem-\ngraça!",
  ["4f:5b24"] = "Esta é a SILPH\nCO., famosa por\vprodutos POKéMON.\fNo passado, a\nTEAM ROCKET\fqueria a empresa\npor causa disso.",
  ["4f:5b4f"] = "No passado, a\nEQUIPE ROCKET\vqueria a empresa\vpor esse motivo.",
  ["4f:5b92"] = "Nhoc… Nhoc…\fOuvi dizer que\nhá um grande pro-\vblema na USINA.\fNhoc… Nhoc…",
  ["4f:5be1"] = "Nhoc… Nhoc…\fOuvi dizer que\nhouve um grande\vrolo na USINA.\fNhoc… Nhoc…\nHaaah, que cheio!",
  ["4f:5c3b"] = "Entrar num beco\npela primeira\fvez me deixa\nmeio ansioso.",
  ["4f:5c7b"] = "Existe um lugar\nchamado TRAINER\fHOUSE em VIRIDIAN\nonde treinadores\fde todo canto\nse reúnem.",
  ["4f:5cdb"] = "Nossa cidade foi\ncitada num\vprograma de rádio\fÉ bom ouvir\nelogios pra sua\fcidade, mas é\num pouco sem-\vgraça também.",
  ["4f:5d4d"] = "SAFFRON CITY\fA Cidade Dourada\ndo Comércio",
  ["4f:5d7c"] = "SAFFRON CITY\nPOKéMON GYM\vLÍDER: SABRINA\fMestra dos POKéMON\nPsíquicos!",
  ["4f:5dbf"] = "Bem-vindos todos!\nFIGHTING DOJO",
  ["4f:5de0"] = "SILPH CO.\nPRÉDIO DA SEDE",
  ["4f:5dfb"] = "CASA do SR.PSI-\nQUICO",
  ["4f:5e0f"] = "SAFFRON CITY\nMAGNET TRAIN\vSTATION",
  ["4f:5f1e"] = "A estrada está\nfechada até que\fo problema na\nUSINA se resolva.",
  ["4f:5f62"] = "UNDERGROUND PATH\fCERULEAN CITY -\nVERMILION CITY",
  ["4f:5f93"] = "O que é isto?\fCasa à venda…\nNinguém mora aí.",
  ["4f:60b0"] = "A USINA de KANTO\nfica perto do fim\fda ROUTE 9.\nHouve um acidente\fde algum tipo\npor lá.",
  ["4f:610c"] = "Você quer captu-\nrar um de cada\vtipo de POKéMON?\fDeve ser um\ndesafio e tanto,\vmas parece legal.",
  ["4f:6170"] = "O CABO ao norte\né um bom lugar\fpra encontros.\nGarotas gostam!",
  ["4f:61c2"] = "Eu e meu SLOWBRO\nformamos uma\vdupla incrível!",
  ["4f:61f1"] = "SLOWBRO, mostre\nseu CONFUSION!",
  ["4f:6216"] = "Sou fã da\nMISTY do GINÁSIO\vde CERULEAN.",
  ["4f:623d"] = "Vi o cara sus-\npeito ir pro CABO\vde CERULEAN.",
  ["4f:6271"] = "Aqui havia uma\ncaverna com POKé-\fMON horríveis e\nfortes.",
  ["4f:62b6"] = "Hein?\fMeu ITEMFINDER\nestá reagindo…",
  ["4f:62da"] = "CERULEAN CITY\fUma Estranha Aura\nAzul a rodeia.",
  ["4f:630d"] = "CERULEAN CITY\nPOKéMON GYM\vLÍDER: MISTY\fA Sereia\nLevada",
  ["4f:6349"] = "Há um aviso…\naqui…\fA BIKE SHOP mudou\npara a GOLDENROD\vCITY em JOHTO…",
  ["4f:6394"] = "Há um aviso…\naqui…\fAcabe com os la-\ndrões e faça da\fcidade um lugar\nmais alegre!\fPOLÍCIA CERULEAN",
  ["4f:6403"] = "CERULEAN CAPE\nadiante",
  ["4f:6418"] = "Está trancado…",
  ["4f:9300"] = "narei mais…",
  ["4f:9a4a"] = "igo,\ncara!",
  ["4f:a045"] = " mas\vvocê ganhou mesmo\vassim.\fComo prometi, você\nganhou um prêmio.",
  ["4f:c400"] = "MON do tipo\vAÇO.\fEu não sei muita\ncoisa desse\vPOKéMON.",
  ["4f:c746"] = "escar!?\vIncompreensível!",
  ["4f:d800"] = "ve existir um\ngolpe que o\vPOKéMON use quando\vcongelado.",
  ["50:40a0"] = "Opa! Perigo, cara",
  ["50:40b4"] = "Meus POKéMON se\nmachucaram antes\fde entrar no ROCK\nTUNNEL.\fÉ melhor levar\neles ao CENTRO\vPOKéMON já.",
  ["50:411a"] = "Você já foi a um\npiquenique?\fÉ muito\ndivertido!",
  ["50:4157"] = "A gente assa um\nmonte de doces\fe divide com todo\nmundo. É delícia!",
  ["50:419d"] = "Ei, você!\nNão jogue lixo!",
  ["50:41b5"] = "Eu só estava\navisando…",
  ["50:41d1"] = "Desculpe. Você não\njogou lixo. Foi\vengano meu.",
  ["50:4202"] = "As pessoas não\ndeviam deixar\vlixo por aí.",
  ["50:423a"] = "Economizar energia\né importante, mas\fo meio ambiente é\nainda mais.",
  ["50:4283"] = "Ela vem descendo a\nMT.SILVER quando\vela vier…\fA MT.SILVER fica\nem JOHTO, né?",
  ["50:42d2"] = "Eu estava ocupada\ncantando…",
  ["50:42eb"] = "Batalha é uma\nquestão de foco.",
  ["50:430d"] = "Vou te contar um\nsegredo.\fMas primeiro a\ngente luta!",
  ["50:433b"] = "Ah, droga!\nPerdi essa…",
  ["50:4353"] = "A POWER PLANT fica\ndo outro lado de\vum riacho.",
  ["50:437d"] = "ROUTE 9\fCERULEAN CITY -\nROCK TUNNEL",
  ["50:443b"] = "Ei, menino! Eu\nda TEAM ROCKET\vsou tipo cara!\fDe outro país\nvim, treinador\vnúmero um, eu!\fPensei eu, se\na energia parar,\fpânico grande\npara daqui gente!\fSegredo meu\nmissão é, então\vnão falo!\fMas! Se batalha\nganhar de mim,\fsou homem e meu\nsegredo conto.\fEi, garoto!\nBatalha começar!",
  ["50:4574"] = "Aiii! Não, não,\nnão, não acredito\vem mim!\fMuito forte\nvocê é! Eu não\vte aguento!",
  ["50:45cd"] = "OK. Contar meu\nsegredo vou.\fMACHINE PART\neu roubei,\fno GYM de\nCERULEAN escondi.\fNa água pus.\nProcure no\fmeio da água\ndo GYM.\fGaroto, mas\nnão me esqueça!\fGanhar de você\na TEAM ROCKET\fvai. De JOHTO\nvirão meus\famigos. E a\nvingança virá!",
  ["50:4600"] = "NA\nque roubei, está\vescondida no\vGINÁSIO DE\vCERULEANA.\fEu coloquei dentro\nda água.\fOlhe na água\ncentral do\vGINÁSIO.\fGaroto, não me\nesqueça!\fA EQUIPE ROCKET\num dia derrotará\vti. \fMeus amigos virão\nde JOHTO sim\vsenhor.\fEles farão uma\nvingança.",
  ["50:46f3"] = "…\fO quê? A TEAM\nROCKET tchau\ftchau? Acabou,\ndisse você?\fOh, não! O que\nfaço agora\vcomigo?",
  ["50:48e7"] = "MISTY: Aii!\nPor que você\ftinha de vir\nagora?\fSabe como\nchamam gente\vcomo você?\fPraga! Ouviu\ndireito? Praga!\f…\f…Oh? Essas BADGES\nvocê tem… São\vBADGES de JOHTO?\fSe tem oito,\ndeve ser bom.\fCerto, então.\nVem ao GYM.\fVou adorar\nbatalhar contigo!\fSou a MISTY, a\nLÍDER do GYM\vde CERULEAN.",
  ["50:4900"] = " tem que\vaparecer e nos\vatrapalhar agora!\fVocê sabe como\nchamamos pessoas\vcomo você?\fPestinhas!\fMe ouviu bem!\f…\f… Oh? Essas\nINSÍGNIAS que\vvocê tem… São as\vINSÍGNIAS DOS\vGINÁSIOS DE JOHTO?\vVocê tem oito,\ventão deve ser um\vbom treinador.\fCerto, venha\nao GINÁSIO DE\vCERULEANA.\fFicarei feliz em\ndesafiá-lo.\fEu sou MISTY, a\nLÍDER DE GINÁSIO\vem CERULEANA!",
  ["50:4a00"] = "IO DE\vCERULEANA.\fFicarei feliz em\ndesafiá-lo.\fEu sou MISTY, a\nLÍDER DE GINÁSIO\vem CERULEANA!",
  ["50:4a2e"] = "Vença nós seis\ntreinadores e leve\vum belo prêmio!\fAcha que dá\nconta do recado?",
  ["50:4a83"] = "Uhu! Muito bom.",
  ["50:4a96"] = "Dei o meu melhor.\nNada a lamentar.",
  ["50:4ab9"] = "Sou o segundo.\nAgora é sério!",
  ["50:4ad6"] = "Como eu perdi?",
  ["50:4ae9"] = "Dei o meu melhor.\nNada a lamentar.",
  ["50:4b0c"] = "Chegou o Nº 3!\nNão vou facilitar",
  ["50:4b2a"] = "Ai! Fui esmagado!",
  ["50:4b3d"] = "Dei o meu melhor.\nNada a lamentar.",
  ["50:4b60"] = "Eu sou o Nº 4!\nJá está cansado?",
  ["50:4b87"] = "Dei o meu melhor.\nNada a lamentar.",
  ["50:4baa"] = "Certo! Sou o Nº 5.\nVou te esmagar!",
  ["50:4bd9"] = "Dei o meu melhor.\nNada a lamentar.",
  ["50:4bfc"] = "Sou o último da\nfila, mas eu digo:\vsou durão!",
  ["50:4c2c"] = "Só pode ser piada",
  ["50:4c3c"] = "Dei o meu melhor.\nNada a lamentar.",
  ["50:4c5f"] = "Mufufufu…\fEu não tenho nada\na ver com os seis\vtreinadores.\fEsperei aqui para\nte vencer quando\festivesse cansado\nde tanta batalha.",
  ["50:4ce2"] = "Você não está\ncansado nada?",
  ["50:4cfb"] = "Desculpe… Não vou\ntrapacear mais…",
  ["50:4d1c"] = "Você enfrentou\nmais uma batalha\fdo que esperava,\nmas venceu.\fComo prometido,\nganhou um prêmio.",
  ["50:4d7e"] = "Mas depois de ver\ncomo você luta,\fquero ver como\nvou me sair.\fQue tal? Deixa eu\nlutar com você!",
  ["50:4dde"] = "Nunca tive uma\nbatalha tão boa!",
  ["50:4e01"] = "Foi uma ótima\nbatalha!\fVocê e seu POKé-\nMON são mesmo\vfantásticos!",
  ["50:4e48"] = "SEA COTTAGE\nBILL'S HOUSE",
  ["50:4f9c"] = "Está sol, mas eu\nestou encharcado…",
  ["50:4fb8"] = "Quando chove, é\ndifícil dar a\vpartida…",
  ["50:4fe2"] = "Hmmm… Não sei o\nque fazer…",
  ["50:5012"] = "Você parecia bom.\fFiquei com medo de\nte encarar…",
  ["50:5043"] = "Eu corro como o\nvento!",
  ["50:506a"] = "Eu uso shorts o\nano inteiro.\fÉ a minha regra\nde moda.",
  ["50:50a8"] = "Chegue mais perto\ne dê uma olhada!",
  ["50:50d9"] = "O maior cuspidor\nde fogo de KANTO\vsou eu.\fMas não o melhor\ntreinador…",
  ["50:5124"] = "MT.MOON SQUARE\fÉ só subir as\nescadas.",
  ["50:520a"] = "Perdi? Isso é\nnovidade também…",
  ["50:5223"] = "Eu talvez vá à\nPOWER PLANT. É\vperto do TUNNEL?",
  ["50:525b"] = "Tenho a impressão\nde que vou ganhar\fVamos ver se eu\nestou certo!",
  ["50:5293"] = "Aah, você é forte\ndemais.",
  ["50:52ad"] = "Ouvi que CLEFAIRY\nvêm na MT.MOON.\fMas onde será\nque eles estão?",
  ["50:52f6"] = "……Vou treinar\nmais um pouco…",
  ["50:5311"] = "MT.MOON SQUARE\fÉ só subir as\nescadas.",
  ["50:5449"] = "A KANTO POKéMON\nFEDERATION nunca\vvai cair!",
  ["50:5475"] = "A polícia fechou o\nnosso UNDERGROUND\fPATH! Isso me dá\nmuita raiva!",
  ["50:54c4"] = "Arrasado por um\nmoleque de JOHTO…",
  ["50:54e8"] = "Somos a KANTO\nPOKéMON FEDERA-\vTION!\vÉ isso aí, cara!",
  ["50:552a"] = "Vamos tentar não\nincomodar ninguém\vdaqui pra frente",
  ["50:5557"] = "Como o MAGNET\nTRAIN funciona?",
  ["50:557a"] = "Eu só quero ver o\nMAGNET TRAIN…",
  ["50:55a0"] = "A força dos ímãs\né impressionante!",
  ["50:55c4"] = "Não vivemos sem\neletricidade.\fA POWER PLANT\nfornece energia\vpara a gente.",
  ["50:5615"] = "Não desperdice\nenergia!",
  ["50:562e"] = "A POWER PLANT ao\nnorte de LAVENDER\ffornece energia\nao MAGNET TRAIN.",
  ["50:5675"] = "Está trancado…",
  ["50:5682"] = "O cartaz rasgado…\fImpossível\nler…",
  ["50:5719"] = "POWER PLANT KANTO",
  ["50:571c"] = "KANTO POWER PLANT",
  ["50:5790"] = "A alergia está me\nfazendo espirrar!\vAtchiiim!",
  ["50:57bd"] = "Você gosta de\nPOKéMON, né?\fEu também!",
  ["50:57df"] = "Eu diria que essa\nfoi derrota minha",
  ["50:57fe"] = "Olha o que você\nfez com o POKéMON\fEu não vou\nesquecer disso…",
  ["50:5831"] = "ROUTE 10\fCERULEAN CITY -\nLAVENDER TOWN",
  ["50:588f"] = "INDIGO PLATEAU\fO Objetivo Final\ndos Treinadores!\fLIGA POKéMON HQ",
  ["50:5a00"] = "L\nDA LIGA POKéMON.",
  ["50:8057"] = "e\nrochas gigantes.",
  ["50:8500"] = "ssivo.",
  ["50:9c4f"] = "veio\vde volta?\fEu vi uns caras de\npreto no LAKE OF\vRAGE…",
  ["50:9d00"] = " quando eles\fevoluem, mas\naprendem golpes\vmais devagar.",
  ["50:c500"] = "es.\fAmanhã, as TIME\nCAPSULES vão\ffuncionar nos\nPOKéMON CENTERS.\fPreciso voltar\npra GOLDENROD já,\vver meus pais.\fTchau!",
  ["50:cb00"] = "sou bom\vem POKéMON também",
  ["51:400e"] = "Os marinheiros\nsão generosos.\fUm me ensinou\no STRENGTH.\fAgora meu POKéMON\nmove pedregulhos.",
  ["51:4067"] = "Tem uma pessoa\nem CIANWOOD CITY\vatravés do mar.\fEu ouvi ele se\ngabar dos seus\vPOKéMON raros.",
  ["51:419a"] = "…Obrigada pela\nsua ajuda no\vLIGHTHOUSE…\fMas isto é dife-\nrente. Por favor,\fpermita que eu me\napresente.\fSou JASMINE, LÍDER\nde GINÁSIO. Eu uso\vo tipo aço.\f…Você conhece o\ntipo aço?\fÉ um tipo que foi\ndescoberto há\vbem pouco tempo.\f…Hum… Começamos?",
  ["51:429c"] = "…Você é melhor\ntreinador que eu,\ftanto em técnica\nquanto em bondade\fDe acordo com as\nregras da LEAGUE,\feu lhe concedo\nesta BADGE.",
  ["51:431b"] = "{PLAYER} recebeu\na MINERALBADGE.",
  ["51:4335"] = "A MINERALBADGE\naumenta a DEFENSE\vdo POKéMON.\f…Hum… Pegue isto\ntambém…",
  ["51:4374"] = "{PLAYER} recebeu\nTM09.",
  ["51:4386"] = "…Você pode usar\nessa TM para\vensinar IRON TAIL",
  ["51:43b2"] = "Hum… Não sei bem\ncomo dizer isto,\vmas boa sorte…",
  ["51:43e3"] = "A JASMINE usa o\ntipo aço, que é\vbem recente.\fEu não sei quase\nnada sobre ele.",
  ["51:4432"] = "Aquilo foi demais\fEntão o tipo aço,\nhein?\fFoi um encontro\nimediato de tipo\vdesconhecido!",
  ["51:445a"] = "Foi um encontro\nimediato de tipo\vdesconhecido!",
  ["51:4489"] = "A JASMINE, LÍDER\ndo GINÁSIO, está\vno LIGHTHOUSE.\fEla cuida de um\nPOKéMON doente.\fUm treinador forte\nprecisa ter com-\vpaixão.",
  ["51:4583"] = "Quando meu POKéMON\nficou doente, o\fFARMACÊUTICO de\nECRUTEAK fez um\vremédio pra mim.",
  ["51:45d1"] = "RHYDON: Grrugooh!",
  ["51:4624"] = "No caminho para\nCIANWOOD, existem\fHá quatro ilhas\ndesertas.\fCrianças ruins são\nlevadas pras ilhas\vcomo castigo!",
  ["51:4692"] = "Quando me meto em\nenrascada, papai\vsempre me assusta",
  ["51:472a"] = "OLIVINE fica no\nmar!\fE se fica no mar,\ncom certeza há\vpeixes!\fPesco aqui há\n30 anos.\fQuer encarar o\nmar e pescar\vtambém?",
  ["51:47bc"] = "Ah, hahaha!\nTemos para nós\vum novo pescador!",
  ["51:47e8"] = "Peixe não existe\nsó no mar.\fEles vão pra onde\nhá água.",
  ["51:482d"] = "O quêê? Você não\ngosta de pescar!?\vInacreditável!",
  ["51:4860"] = "E aí, como vai?\nPegou uma grande?",
  ["51:48bd"] = "Hah! Seus POKéMON\nparecem mesmo ser\vpesos-leves!\fEles não têm força\npra mover de lado\vos pedregulhos.\fTome, use isto\ne ensine o golpe\vSTRENGTH a eles!\fVai precisar da\nBADGE do GINÁSIO\fde GOLDENROD pra\nusar fora de luta",
  ["51:4980"] = "No mar, a única\ncoisa que conta\fSó dá pra contar\ncom você mesmo.\fTenho orgulho do\nmeu corpo sarado!",
  ["51:49e0"] = "Cruzando o mar?\nEntão escute!\fHá redemoinhos\nno caminho para\vCIANWOOD.\fSeu POKéMON tem\nque saber de um\fgolpe pra passar\ndos redemoinhos.",
  ["51:4aaa"] = "Seus POKéMON já\nsabem o golpe pra\fcarregar pessoas\nsobre a água?",
  ["51:4aec"] = "Meu BUTTERFREE\nveio do namorado\vlá do exterior.\fEle trouxe um MAIL\nque ele mandou.\fQuer saber o que\ndiz?\fVamos ver… Não!\nÉ um segredo!",
  ["51:4bb0"] = "De onde mesmo você\né?\fDe NEW BARK TOWN?\fO PROF.ELM mora\nperto daí, certo?\fVocê veio de bem\nlonge pra chegar.",
  ["51:4d04"] = "MOOMOO doente…\fEla precisa de\nmuitas BERRIES.",
  ["51:4d30"] = "Dando comida pra\nMOOMOO!",
  ["51:4d56"] = "O choro é fraco…",
  ["51:4d77"] = "Dar uma BERRY pra\nMILTANK?",
  ["51:4d91"] = "{PLAYER} deu uma\nBERRY à MILTANK.",
  ["51:4dad"] = "A MILTANK ficou\nmais saudável!",
  ["51:4dd1"] = "MILTANK ficou\nbem saudável!",
  ["51:4df0"] = "MILTANK ficou\nmuito saudável!",
  ["51:4e11"] = "{PLAYER} não tem\nBERRIES…",
  ["51:4e24"] = "{PLAYER} não quer\ndar uma BERRY.\fMILTANK triste.",
  ["51:4f0d"] = "A MILTANK não me\ndá leite mais não.\vagora.\fEsta FAZENDA aqui\ntem leite famoso.\fQuase todo mundo\nquer beber.\fEla me dá bastante\nleite se eu der\fmuitas BERRIES,\neu acho.",
  ["51:4fb7"] = "Gostou do meu\nMOOMOO MILK?\fÉ meu orgulho e\nalegria, filho.\fDê aos POKéMON\npra recuperar PS!\fTe vendo por só\n¥500.",
  ["51:5031"] = "Toma!\nBebe e aproveita!",
  ["51:5050"] = "Desculpa, filho.\nSem grana, nada!",
  ["51:506f"] = "Acho que sua\nMOCHILA tá cheia.",
  ["51:508e"] = "Não quer mais?\nVolte depois, tá?",
  ["51:50b3"] = "Melhor eu ir\nordenhar.",
  ["51:50cd"] = "Nosso leite vai\naté para KANTO.\fEntão se nossa\nMILTANK não der\fleite, ficamos\nem apuros.",
  ["51:512d"] = "Você curou nossa\nMILTANK, meu bem.\fAgora dá MOOMOO\nMILK de novo.\fToma uma lembrança\npor seu trabalho.",
  ["51:518c"] = "{PLAYER} recebeu\nTM13.",
  ["51:519e"] = "Isso aí é o\nSNORE.\fÉ um golpe raro\nque só funciona\fquando o POKéMON\nestá dormindo.\fMelhor pensar bem\nem como usar,\vmeu bem.",
  ["51:526c"] = "Ouvi que apareceu\num GYARADOS ver-\vmelho no LAKE.\fÉ estranho, pois\naté GYARADOS\fcomuns são raros\nnaquele lago…",
  ["51:52de"] = "Meu programa de\nrádio favorito? O\vPOKéMON MUSIC.",
  ["51:530d"] = "Ando ouvindo\nrisadas no\frádio…\nÉ arrepiante.",
  ["51:545d"] = "POKéMON vivem\nmuitas coisas na\fvida deles, assim\ncomo nós.\fEu também já vi\ne sofri muito\vna minha vida.\fComo sou mais\nvelho, deixe eu\vmostrar o que é.\fEstou com POKéMON\ndesde antes\fde você\nnascer.\fEu não perco\nfácil.\fEu, PRYCE, o\ntreinador do\finverno, vou\nmostrar meu poder",
  ["51:5583"] = "Ah, estou impres-\nsionado com você.\fCom essa vontade\nforte, você vai\fsuperar todos os\nobstáculos.\fVocê é digno\ndesta BADGE!",
  ["51:560b"] = "{PLAYER} recebeu\na GLACIERBADGE.",
  ["51:5625"] = "Essa BADGE aumenta\nos status SPECIAL\vdos POKéMON.\fEla também deixa\nseu POKéMON usar\vWHIRLPOOL para\vcruzar redemoinho\fE isto… Isto é um\npresente meu!",
  ["51:56bf"] = "Essa TM contém o\nICY WIND.\fEle causa dano e\nreduz VELOCIDADE.\fEle demonstra\na dureza do\vinverno.",
  ["51:5729"] = "Quando o gelo e a\nneve derretem, a\vprimavera chega.\fVocê e seus POKé-\nMON vão ficar\fjuntos por muitos\nanos ainda.\fValorize o tempo\nde vocês!",
  ["51:57b1"] = "Vou congelar\nseus POKéMON, você\vnão fará nada!",
  ["51:57e0"] = "Droga. Não pude\nfazer nada.",
  ["51:57fd"] = "Acho que existe um\nmovimento que um\fPOKéMON pode usar\nmesmo congelado.",
  ["51:5835"] = "Este GINÁSIO\ntem piso liso.\fÉ divertido, não\né?\fMas ei, aqui nós\nnão estamos\vbrincando!",
  ["51:588d"] = "Você vê como\nsomos sérios?",
  ["51:58ad"] = "Adoro patinar\ncom meus POKéMON\vneste GINÁSIO!",
  ["51:58df"] = "Conheço o segredo\ndo PRYCE.",
  ["51:58f6"] = "Vou te contar o\nsegredo do PRYCE.",
  ["51:5917"] = "O segredo do\npoder de PRYCE…\fEle medita sob\numa cachoeira\fpara fortalecer\nmente e corpo.",
  ["51:597e"] = "Para chegar ao\nPRYCE, você\fprecisa pensar\nantes de patinar.",
  ["51:59c4"] = "Não perderia para\nvocê no esqui!",
  ["51:59e6"] = "Sem patinar com\nprecisão, você\fnão vai longe\nneste GINÁSIO.",
  ["51:5a27"] = "Veja minha\nvirada paralela!",
  ["51:5a44"] = "Não! Você me fez\ncair!",
  ["51:5a5f"] = "Não devia ter\nme gabado do meu\vesqui…",
  ["51:5a8f"] = "O PRYCE é veterano\ne treina POKéMON\fhá uns\n50 anos.\fDizem que ele é\nbom em congelar\fadversários com\ngolpes de gelo.\fOu seja, você tem\nque derreter ele\fcom sua ambição\nem chamas!",
  ["51:5b45"] = "O PRYCE é bom,\nmas você é de\voutro nível!\fFoi uma batalha\nquente que\funiu duas\ngerações!",
  ["51:5c32"] = "O quê? A TEAM\nROCKET voltou\vde novo?\fVi uns homens de\npreto no LAKE OF\vRAGE…",
  ["51:5c83"] = "Seguro meu POKéMON\nde evoluir cedo\vdemais.\fFaço aprenderem\ncertos golpes an-\vtes de deixar eles\vevoluírem.",
  ["51:5ce8"] = "POKéMON ficam mais\nfortes ao evoluir\fmas aprendem os\ngolpes bem mais\vdevagar.",
  ["51:5d88"] = "O MOUNT MORTAR é\num labirinto.\fCuidado pra não\nse perder lá.",
  ["52:406c"] = "A TIN TOWER é\nproibida a quem\fnão tem a INSÍGNIA\nde ECRUTEAK.\fDesculpe, mas você\ntem que sair.",
  ["52:40cc"] = "A TIN TOWER é\nproibida a quem\fsem a BADGE do\nGINÁSIO daqui.\fAh!\fA BADGE do GINÁSIO\nde ECRUTEAK! Pode\vpassar adiante.",
  ["52:413f"] = "A TIN TOWER à\nfrente foi feita\fcomo abrigo dos\nPOKéMON que voam.",
  ["52:417d"] = "A TIN TOWER\ntremeu! POKéMON\fdeve ter voltado\nao topo!",
  ["52:41b9"] = "Duas torres…\nDois POKéMON…\fMas quando uma\nqueimou, os dois\fPOKéMON voaram\ne nunca voltaram.",
  ["52:4304"] = "Oi, eu sou o BILL.\nE você é quem?\f{PLAYER}, hein?\nVocê chegou numa\vboa hora.",
  ["52:434e"] = "Acabei de ajustar\na minha TIME\vCAPSULE.\fVocê sabe que dá\npra trocar POKéMON\vcerto?\fMinha TIME CAPSULE\nfoi feita pra\ftrocar com o\npassado.\fNão pode mandar\nnada que\fnão existia no\npassado.\fSe mandasse, o PC\ndo passado ia\vquebrar.\fEntão é preciso\ntirar tudo que\fnão tinha no\npassado.\fEm resumo, nada\nde golpe novo ou\fPOKéMON novo na\nTIME CAPSULE.\fNão se preocupe.\nJá terminei os\vajustes.\fAmanhã, as TIME\nCAPSULES vão\ffuncionam nos\nCENTROS POKéMON.\fPreciso voltar pra\nGOLDENROD pra ver\va família.\fTchau!",
  ["52:4581"] = "O jeito das KIMONO\nGIRLS dançarem é\fmaravilhoso. Assim\ncomo elas usam\vseus POKéMON.",
  ["52:45d6"] = "MORTY, o LÍDER\ndo GINÁSIO, é tão\vlegal.\fOs POKéMON dele\nsão fortes também",
  ["52:461c"] = "LAKE OF RAGE…\fO aparecimento do\nbando de GYARADOS\fSinto cheiro de\nconspiração. Sei!",
  ["52:46d3"] = "Isso aconteceu\nquando jovem.\fO céu de repente\nficou preto. Um\fPOKéMON gigante\nvoador cobriu\vo sol.\fQue POKéMON\nserá que era?\fParecia um pássaro\ne um dragão.",
  ["52:4782"] = "Será que existe um\nPOKéMON gigante?\fSe ele existe,\ndeve ser forte.",
  ["52:48e9"] = "Oh, você é muito\nforte.",
  ["52:4903"] = "Eu gostei do\nduelo. Queria\vte ver de novo.",
  ["52:4938"] = "Eu sempre danço\ncom meus POKéMON.\fClaro, eu também\nos treino.",
  ["52:4974"] = "Oh, tão perto!\nQuase te peguei!",
  ["52:4995"] = "O ritmo é\nimportante para\fdançar e para\nPOKéMON.",
  ["52:49c9"] = "Minha presilha é\nbonita, não?\fOh. Uma batalha\nde POKéMON?",
  ["52:49f6"] = "Não tenho mais\nPOKéMON…",
  ["52:4a12"] = "Coloco uma flor\ndiferente no\vgrampo todo mês.",
  ["52:4a4a"] = "Oh, você é um\ntreinador fofo.\vQuer batalhar?",
  ["52:4a7f"] = "Você é mais forte\ndo que aparenta.",
  ["52:4a9e"] = "Treinei muito e\nme achava capaz\fde batalhar. Mas\nacho que não.",
  ["52:4ae6"] = "Gosta da minha\ndança? Também sou\vboa com POKéMON.",
  ["52:4b14"] = "Ooh, você também\né bom em POKéMON.",
  ["52:4b32"] = "Continuo dançando\nporque há gente\fque gosta do\nque eu faço.\fMeus POKéMON\nme animam.",
  ["52:4b94"] = "Não só as KIMONO\nGIRLS são ótimas\fdançarinas, também\nsão boas em\vPOKéMON.\fSempre as desafio,\nmas nunca deixei\fnem um arranhão.\nnelas…",
  ["52:4c1b"] = "Jovem! Se você\nderrotar todas as\fKIMONO GIRLS, eu\nte dou um prêmio.",
  ["52:4c5e"] = "O jeito que você\nlutou parecia\vver uma dança.\fFoi uma raridade\nver isso!\fQuero que você\nfique com isto.\vSem medo, aceite!",
  ["52:4cdf"] = "Isto é o SURF.\fÉ um golpe que\ndeixa POKéMON\vnadar na água.",
  ["52:4d19"] = "Queria que meu\nPOKéMON fosse\vtão elegante…",
  ["52:4d4e"] = "RHYDON: Grogoh\ngrugrooh!",
  ["52:4d68"] = "Aquele homem vive\ncom seu RHYDON.\fDiz que quer um\nPOKéMON que saiba\vSURF e dançar.\fSerá que ele quer\nfazer um POKéMON\vde nado sincroni-\vzado?",
  ["52:4dee"] = "As KIMONO GIRLS\nsão tão lindas…\fMas elas passam\npor um treino\vrigoroso.\fE também têm que\naprender costumes\fantes de aparecer\nem público.\fMas se você ama\nalgo, tudo é\vpossível.",
  ["52:4ebd"] = "É um painel chique\nque é decorado\vcom flores.",
  ["52:4f8c"] = "Meu EEVEE virou\num ESPEON.\fMas o do meu amigo\nEEVEE virou um\vUMBREON.\fPor que será? Nós\ndois criávamos\fnosso EEVEE do\nmesmo jeito…",
  ["52:5019"] = "Se usar REVIVE,\num POKéMON que\fdesmaiou vai\nacordar.",
  ["52:516b"] = "Que bom que você\nveio.\fAqui em ECRUTEAK,\nos POKéMON sempre\vforam venerados.\fDizem que POKéMON\nlendários surgem\fpara os treinado-\nres realmente\vpoderosos.\fEu acreditei\nnisso, e por isso\ftreinei aqui em\nsegredo sempre.\fCom isso, hoje eu\nvejo o que outros\vnão veem.\fSó mais um pouco…\fCom um pouco mais,\neu poderia ver\fum futuro em que\neu encontro o\vPOKéMON lendário.\fVocê vai me ajudar\na chegar nesse\vnível!",
  ["52:52f4"] = "Ainda não sou bom\no bastante…\fTudo bem. Esta\nBADGE é sua.",
  ["52:532d"] = "{PLAYER} recebeu\na FOGBADGE.",
  ["52:5343"] = "Com a FOGBADGE,\nPOKéMON até o L50\fvão obedecer\nvocê.\fPOKéMON que sabem\nSURF também podem\fusar o golpe a\nqualquer hora.\fQuero que fique\ncom isto também.",
  ["52:53d6"] = "É o SHADOW BALL.\nCausa dano e pode\freduzir a\nSPCL.DEF.\fUse se ele te\nagradar.",
  ["52:5400"] = "reduz a DEFESA\vESPECIAL.\fUse-a se lhe\nagradar.",
  ["52:542f"] = "Entendo…\fSua jornada levou\nvocê a lugares\vbem distantes.\fE você testemunhou\nmuito mais coisas\vdo que eu.\fEu invejo você\npor isso…",
  ["52:54a7"] = "Passei a primavera\ncom meus POKéMON.\fDepois o verão, o\noutono, o inverno\fEntão a primavera\nvoltou. A gente\fconvive junta há\nmuito tempo.",
  ["52:5527"] = "Já vivi a vitória\ne a derrota.",
  ["52:554d"] = "De onde vieram\nos POKéMON?",
  ["52:5568"] = "Consegue causar\ndano aos nossos\vPOKéMON?",
  ["52:55a1"] = "Só usamos os\nPOKéMON fantasma\fNenhum ataque\nnormal consegue\vferi-los!",
  ["52:5602"] = "Quem quiser vencer\nmais, vencerá!",
  ["52:5628"] = "Confuso com nosso\npiso invisível?\fVença-me se quiser\numa dica!",
  ["52:5674"] = "Tudo bem. Eu vou\ncontar o segredo\fdo piso\ninvisível.\fO caminho está\nna nossa frente!",
  ["52:56d2"] = "Os treinadores\ndaqui têm motivos\vsecretos.\fSe você vencer,\neles podem contar\fsegredos profundos\nde ECRUTEAK.",
  ["52:573c"] = "Ufa, {PLAYER}.\nVocê foi ótimo!\fEu estava encolhi-\ndo no canto de\vpuro terror!",
  ["52:58cc"] = "Ah. Está numa\naventura com\vseus POKéMON?\fE o que seria\numa aventura sem\vcaça ao tesouro?\fTô certo ou não\nestou certo?",
  ["52:5945"] = "Ótimo! Você\nentende o real\fespírito de\naventura.\fGostei! Leve\nisto com você.",
  ["52:599e"] = "Há muitos itens\nespalhados por aí\fE que não são\nóbvios.\fUse o ITEMFINDER\npra checar se há\fum item no chão\nperto de você.\fEle não mostra o\nlugar exato,\fentão vai ter que\nprocurar.\fAh! Ouvi dizer que\nhá itens\fna BURNED TOWER\nde ECRUTEAK.",
  ["52:5a95"] = "Ah… Cada um com\nseu gosto, né…",
  ["52:5ab6"] = "HISTÓRIA DE\nECRUTEAK\fQuer ler?",
  ["52:5adc"] = "Em ECRUTEAK havia\nduas torres.\fCada torre era\no abrigo de\vPOKéMON voadores.\fMas uma delas\nqueimou até o\vchão.\fOs dois POKéMON\nnão são vistos\vdesde então…\fContinuar lendo?",
  ["52:5b92"] = "ECRUTEAK também\nera o lar de três\fPOKéMON corriam\npela cidade.\fDizem que nasceram\nda água e do\frelâmpago e do\nfogo.\fMas não conseguiam\nconter seu poder\vexcessivo.\fPor isso os três\ncorreram como o\fvento até o\ncampo.",
  ["53:40f3"] = "Sou CLAIR. Eu sou\na melhor mestra\vdo dragão do\fmundo.\nPosso rivalizar\faté com os QUATRO\nGRANDES da LIGA\fPOKéMON.\nAinda quer\fme desafiar?\n…Tudo bem.\fVamos lá!\nComo treinadora,\fvou usar o maximo\ncontra oponente!",
  ["53:41cf"] = "Eu perdi?\fNão acredito.\nDeve haver algum\vengano…",
  ["53:4207"] = "Não vou admitir\nisso.\fPode ter sido\nderrotada, mas\fvocê ainda não\nesta pronta para\fa LIGA POKéMON.\nSei. Você deveria\vfazer o desafio\fdo usuário\ndragão.\vAtrás deste GYM\fha um lugar\nchamado\fDRAGON'S DEN.\nVa e me traga o\fDRAGON FANG\ndo fundo da DEN.\fEsse e o teste\npara ser aceito\fcomo um\nverdadeiro\vusuário dragão.\vSe conseguir,\fvou aceita-lo\ncomo treinador.\vAté lá, INSÍGNIA!",
  ["53:4391"] = "CLAIR: O que\nacontece?\fEssa tarefa não\ne difícil para\fvocê, a menos que\ntenha sido sorte.",
  ["53:43f0"] = "CLAIR: Você não\npegou isso no\vDRAGON'S DEN.\fTentar trapacear\nassim…\fEstou desapontada\ncom você.",
  ["53:4451"] = "CLAIR: Você se\nprovou para mim.\vQuero que você\ffique com\nesta MT.",
  ["53:4495"] = "{PLAYER} recebeu\nTM24.",
  ["53:44a7"] = "Contem\nDRAGONBREATH.\fNão, não tem nada\na ver com minha\vrespiração.\fSe não quiser,\nnão precisa\vpegar.",
  ["53:4525"] = "Você já colecionou\ntodas as\vINSÍGNIAS.\fSeu destino é a\nLIGA POKéMON no\fINDIGO PLATEAU.\nSabe como chegar\flá?\nDaqui, vá para\fNEW BARK TOWN.\nDepois SURF\fpara o leste.\nA rota lá é\vmuito difícil.\fNão ouse\nperder na\vLIGA POKéMON!\fSe perder, vou\nme sentir ainda\fpior por ter\nperdido para você",
  ["53:4651"] = "Primeira batalha\ncontra dragões?\fVou mostrar como\nsão durões!",
  ["53:4696"] = "Que decepção!",
  ["53:46a8"] = "Você conhece o\nLANCE, o mestre\fdos dragões?\nNão pode ser.",
  ["53:46e5"] = "Minha chance de\nperder? Nem\vum por cento!",
  ["53:471d"] = "Agora sei minhas\nlimitações.\fObrigado por me\nmostrar!",
  ["53:4753"] = "Os dragões são\nPOKéMON sagrados.\fEles têm muita\nenergia vital.\fSe você não levar\na sério, não vai\fconseguir\nderrotá-los.",
  ["53:47cc"] = "Dragões são fracos\ncontra movimentos\vde dragão.",
  ["53:47fa"] = "Ei!\nFUTURO\fCAMPEÃO!\nJá faz tempo que\fcomecamos, mas\njá estamos quase\flá! Conta comigo!\nCLAIR usa dragões\vmiticos e sagrados\vdo tipo dragão.\fVocê não consegue\nmachuca-los\ffacilmente.\nMas saiba que\feles são fracos\ncontra gelo.",
  ["53:48e8"] = "Você foi incrível\nao vencer CLAIR!\fSó falta o desafio\nda LIGA POKéMON.\vVocê esta no\fcaminho para se\ntornar o\vCAMPEÃO POKéMON!",
  ["53:4aa9"] = "Você é especial…",
  ["53:4abb"] = "Mas espere só!\nMeus POKéMON vão\fficar ainda mais\npoderosos.\fComo treinador\ne POKéMON, seremos\vmais fortes!",
  ["53:4b20"] = "Treinamos firme\ncom a CLAIR.\vNão posso perder\vde jeito nenhum!",
  ["53:4b69"] = "Argh! Estou tão\nenojado!",
  ["53:4b83"] = "Ufa…\fVou ter que\nrepensar o treino",
  ["53:4bad"] = "O bloco caiu!\npelo buraco!",
  ["53:4c64"] = "CLAIR e LANCE\ntreinaram aqui\fpara aperfeicoar\nsuas habilidades.",
  ["53:4ca4"] = "DRATINI: Draa!",
  ["53:4d20"] = "Não pode comprar\nMAX REVIVE, mas\frestaura todo\nPOKéMON desmaiado\fCuidado ,  não\nrestaura PP, os\fPONTOS DE PODER\nnecessarios.",
  ["53:4d9f"] = "MAX REPEL mantem\nPOKéMON fracos\vlonge de você.\fE o mais duradouro\ndos sprays\vREPEL.",
  ["53:4e3b"] = "No fundo do longe\nINDIGO PLATEAU\fe a LIGA POKéMON\nOuvi os melhores\ftreinadores vão\nde todo o pais.\fQuero ir lá\num dia.",
  ["53:4eb3"] = "Havia um movimento\nque eu tinha que\fensinar ao meu\nPOKéMON.\fEntão pedi ao\nAPAGADOR DE GOLPES\vesquecer um HM.",
  ["53:4fa7"] = "BLAINE, do GINÁSIO\nde CINNABAR\fmora sozinho na\nCAVERNA das\vSEAFOAM ISLANDS…",
  ["53:4ff1"] = "Já faz um ano\ndesde que o vulcão\ventrou em erupção",
  ["53:507c"] = "O vulcão de\nCINNABAR estourou\fEle jogou pedras\nque fecharam a\vROUTE 19 de vez.\fFico pensando se\no povo de CINNABAR\vestá a salvo…",
  ["53:50fc"] = "Nenhum morador de\nCINNABAR se feriu\fcom a erupção.\nQue ótimo!",
  ["53:51ba"] = "BLAINE: Uaaah!\fMeu GINÁSIO em\nCINNABAR queimou.\fEu e meus POKéMON\nde fogo ficamos\fsem casa por\ncausa do vulcão.\fBuaaah!\fMas voltei à ativa\ncomo LÍDER de\fGINÁSIO aqui na\ncaverna.\fSe você me vencer\neu te dou\vuma BADGE.\fHa! Melhor levar\nBURN HEAL!",
  ["53:52b8"] = "BLAINE: Demais.\nEstou esgotado…\fVocê ganhou a\nVOLCANOBADGE!",
  ["53:52f5"] = "{PLAYER} recebeu\na VOLCANOBADGE.",
  ["53:530f"] = "BLAINE: Perdi\ndesta vez, mas\fvou vencer na\npróxima.\fQuando eu refizer\no meu GINÁSIO,\fde CINNABAR,\nteremos revanche.",
  ["53:538e"] = "BLAINE: Meus\nPOKéMON de fogo\fficarão ainda mais\nfortes. Veja!",
  ["53:53cb"] = "E aí!\f…Hein? Já acabou?\ntão rápido?\fDesculpa, cara!\fO GINÁSIO de\nCINNABAR sumiu,\fentão não sabia\nonde te achar.\fMas você está\nbem forte, mesmo\fsem meu conselho.\nEu já sabia!",
  ["53:5477"] = "Um GINÁSIO pode\nser em qualquer\flugar, desde que\no LÍDER esteja\flá. Não precisa de\nprédio.",
  ["53:5521"] = "…Você vagou muito\nlonge…\fAqui eu meditei.\nDentro de mim,\fum novo poder\ndespertou.\fDeixe-me dividir\nmeu poder com\fseu POKéMON.\nTome, criança.",
  ["53:55b4"] = "Vê isto? É o\nHIDDEN POWER!\fEle extrai o\npoder do POKéMON\vpra atacar.\fLembre-se: o tipo\ne o poder dependem\vdo POKéMON\vque o usa.",
  ["53:5649"] = "Estou meditando…",
  ["53:5704"] = "O LAKE OF RAGE é\nna verdade uma\fcratera feita por\nGYARADOS em fúria\fA cratera encheu\nde água de chuva\fe assim nasceu\no LAKE.\fÉ a história que\nveio do tataravô\fdo tataravô do\nmeu vovô.\fAntigamente dava\npara pescar\fMAGIKARP animados\nali, mas…\fEu não entendo o\nque está havendo.",
  ["53:5823"] = "O LAKE não está\nnormal desde que\faqueles homens de\npreto chegaram.",
  ["53:5866"] = "O LAKE OF RAGE\nvoltou ao normal.\fOs MAGIKARP\nvoltaram.\fAinda posso ver\nmeu sonho de achar\vo maior MAGIKARP\vdo mundo.\fVocê tem uma ROD?\nSe tiver, por\vfavor me ajude.",
  ["53:5914"] = "Ah, você tem um\nMAGIKARP! Vamos\fver o tamanho\ndesse bichinho.",
  ["53:594d"] = "Uau! Este aqui é\nexcepcional!\fTiro o chapéu\npara você!\fLeve isto de\nlembrança!",
  ["53:5999"] = "O recorde é o que\nimporta.\fConsidere isso\num bônus!",
  ["53:59d7"] = "Uau! Este aqui é\nexcepcional!\f…Eu queria poder\ndizer isso, mas\fjá vi um maior\nantes.",
  ["53:5a32"] = "O quê? Isso não é\num MAGIKARP!",
  ["53:5a4f"] = "Ah… Então você não\npegou um bom\fo bastante?\nFica pra próxima.",
  ["53:5a92"] = "RECORDE ATUAL\f{STRBUF} pego\npor {STRBUF}",
  ["53:5af5"] = "Só quem vai ao\nLAKE OF RAGE\fpassou por aqui\nultimamente.",
  ["53:5b3b"] = "Ninguém mais vai\nao LAKE OF RAGE\vnesses dias.",
  ["53:5ca8"] = "Pare aí, moço!\nmoço!\fO pedágio é ¥1000\npara passar.",
  ["53:5ce1"] = "Obrigado, senhor!",
  ["53:5cf2"] = "Então pague o que\ntiver, por favor.",
  ["53:5d13"] = "Hihihi. Estamos\nenchendo o bolso.\fTodo mundo quer\nver o que rola\fno LAKE OF\nRAGE.",
  ["53:5d6d"] = "Fui expulso do\nmeu posto por\vaqueles de preto.\fEles deixaram\nisto para trás.\fIsso me deixa\ndesconfortável.\vPode levar?",
  ["53:5ded"] = "{PLAYER} recebeu\nTM30.",
  ["53:5dff"] = "Use este portão\npra não andar\vna grama.",
  ["53:c047"] = "mesmo que seu\fPOKéMON tenha\ndesmaiado.",
  ["54:4005"] = "Você está juntando\nBADGES de KANTO?",
  ["54:405a"] = "Ouvi dizer que um\nsujeito esquisito\vestá rondando.\fNão vou tolerar\nse ele acabar\vsendo ladrão.",
  ["54:40c3"] = "Já fomos vítimas\nde assaltantes.",
  ["54:414d"] = "Meu marido vive\nfeliz com o POKé-\vMON que ele ganhou\vem trocas.",
  ["54:418a"] = "Ah… Que alegria…",
  ["54:4218"] = "A ROUTE 9 vai\npara o leste. A\fPOWER PLANT fica\nno fim.",
  ["54:4257"] = "O MAGNET TRAIN\nanda a mais de\f540 km/h. Ele vai\nde KANTO a JOHTO\fem quase nenhum\ntempo.\fIsso aproxima\nJOHTO de você.",
  ["54:4453"] = "Upa! Eu desculpa!\nVocê não machucou,\vtá?\fEu muito ocupado.\nSem tempo pra\vpapear com você.\vRuim pra mim se\valguém me vê.",
  ["54:44cc"] = "Ah não! Já viu\nme! Eu fiz um\vgrande erro!",
  ["54:44fd"] = "Ei, você! Esquece\nque me viu, tá?\fVocê não viu,\nnem ouviu nada,\ftá?\nBye-bye, garoto!\fTchau, tchau!",
  ["54:4568"] = "Desculpe, saí\npor um tempo.\vMISTY, GYM LEADER",
  ["54:459a"] = "Como a MISTY saiu,\nnós também.\vGYM TRAINERS",
  ["54:45cc"] = "MISTY: Eu já te\nesperava, praga!\vPode ter muitas\fGYM BADGES de\nJOHTO, mas não\fvai me levar de\nbobeira!\vMeus POKéMON de\fágua são\ndurões!",
  ["54:4664"] = "MISTY: Você é\nmuito bom…\fAdmito que você\né habilidoso…\fToma. É a\nCASCADEBADGE.",
  ["54:46c0"] = "{PLAYER} recebeu\na CASCADEBADGE.",
  ["54:46da"] = "MISTY: Existem\nmuitos treinadores\vfortes em JOHTO?\vComo você, aliás?\fVou viajar\num dia e quero\fbatalhar com\ntreinadores bons.",
  ["54:4762"] = "Desculpe por me\nausentar… Vamos\vcontinuar!",
  ["54:4790"] = "Eu desisto! Você é\no vencedor!",
  ["54:47ae"] = "Vou nadar em\nsilêncio.",
  ["54:47c8"] = "Não deixe minha\nelegante natação\vte intimidar.",
  ["54:47f7"] = "Ooh, você me\nvenceu com calma…",
  ["54:4818"] = "Não fique tão con-\nfiante ao ganhar.\fMISTY vai te pegar\nse você se des-\vcuidar.",
  ["54:486a"] = "Glub…\fEu sou o primeiro!\nVenha me pegar!",
  ["54:489b"] = "MISTY melhorou\nmuito nos últimos\vanos.\fNão baixe a guar-\nda, ou você será\vesmagado!",
  ["54:48ff"] = "E aí, futuro\ncampeão!\fComo a MISTY\nsaiu, fui me\fdivertir também!\nHe-he-he.",
  ["54:4952"] = "Uau, você mostrou\ncomo é durão.\fComo sempre, foi\numa baita\vbatalha!",
  ["54:4a25"] = "Você vai ver\nmuitos por aí no\fcaminho pro CAPE\nde CERULEAN.\fEles querem ver\ncomo se saem\fcontra outros\ntreinadores.",
  ["54:4a9e"] = "A MISTY é a única\nna cidade que\fvence os caras\ndo CAPE de\vCERULEAN.",
  ["54:4b49"] = "Um CENTRO POKéMON\nperto de caverna?\fIsso é muito\nconveniente!",
  ["54:4b7e"] = "O MANAGER da\nPOWER PLANT quer\fachar um homem\ncom POKéMON bom.\fEle precisa de\najuda pra pegar\fde volta algo que\nfoi roubado.",
  ["54:4bf6"] = "Ouvi que a TEAM\nROCKET se reuniu\fde novo em JOHTO,\nmas se desfez.\fEu não sabia\nde nada disso.",
  ["54:4c64"] = "Quando você sai,\ndá pra ver o\ftelhado de um\nprédio grande.\fEssa é a POWER\nPLANT.",
  ["54:4e31"] = "Um ladrão invadiu\na POWER PLANT…\fO que o mundo\nestá virando?",
  ["54:4e73"] = "Acabei de saber\nde CERULEAN.\fAo que parece,\num sujeito\festranho anda\nrondando por aí.",
  ["54:4ed0"] = "Posso pedir sua\ncooperação?",
  ["54:4ef3"] = "Vamos ter que\nreforçar nossa\vsegurança.",
  ["54:4f20"] = "Alguém levou\numa peça que é\fessencial para\no gerador.\fSem ela, o\ngerador novo\vnão serve!",
  ["54:4f89"] = "O gerador está\nligado e no ar.\fEstá gerando\neletricidade!",
  ["54:4fca"] = "Esta POWER PLANT\ntinha sido\vabandonada.\fNós reativamos\nela pra dar\fenergia pro\nMAGNET TRAIN.",
  ["54:5040"] = "O gerador está\nrodando de novo!",
  ["54:505f"] = "O MANAGER da\nPOWER PLANT está\vlogo à frente.\fMas como alguém\nquebrou o gerador,\vele ficou\vtriste e\vfurioso…",
  ["54:50d0"] = "Como o gerador\nfoi consertado,\fo MANAGER está\nbem animado.",
  ["54:5113"] = "O MAGNET TRAIN\ngasta muita\veletricidade.\fNão anda se o\nnovo gerador\vnão funciona.",
  ["54:5176"] = "Legal! Podemos\nfinalmente pôr o\fMAGNET TRAIN\nde novo no ar!",
  ["54:51b5"] = "MANAGER: Eu vou\nexplodir alguém!\vQuem se atreve\fa estragar meu\ngerador?\fGastei tanto\ntempo nele!\fSe eu pegar,\nele vai ver o que\fé um ZAP\nCANNON!",
  ["54:5259"] = "MANAGER: Não vou\nperdoar não!\fO culpado pode\nchorar, pedindo\fperdão, mas ainda\nvou moer ele!\fHahahahaha!",
  ["54:52bf"] = "MANAGER: Ah! Sim!\fÉ a PART que\nfaltava do meu\vquerido gerador!\vVocê achou?",
  ["54:5315"] = "Uau! Valeu!\fTome este TM\ncomo recompensa!",
  ["54:5345"] = "MANAGER: TM07 é\nmeu ZAP CANNON.\fÉ uma técnica\npoderosa!\fNão é bem\nprecisa, mas\facerta em cheio!\nBate forte!",
  ["54:53c6"] = "MANAGER: Meu\namado gerador!\fContinua soltando\neletricidade!",
  ["54:5612"] = "Hum? Conhece o\nBILL? É meu neto.\fEle está em JOHTO\nFaz uma coisa\fcom PCs, então eu\ncuido da casa.",
  ["54:5676"] = "Se você tem esse\nPOKéMON, me mostra\vele, por favor?",
  ["54:56a4"] = "Você vai mostrar?\nQue gentil!",
  ["54:56c8"] = "Não tem ele?\nQue pena…",
  ["54:56ea"] = "Ah, então é\no {STRBUF}?\fQue fofo!\nMuito gentil da\vsua parte!",
  ["54:5725"] = "Obrigado!\fIsto é uma marca\nde gratidão!",
  ["54:5752"] = "Venha me visitar\noutra hora!",
  ["54:576e"] = "Obrigada por me\nmostrar tantos\vPOKéMON fofos.\fGostei muito\nmesmo. Fico feliz\fde ter vivido uma\nvida tão longa.",
  ["54:57d5"] = "Hm?\fNão é o POKéMON\nde que me\vfalaram.",
  ["54:5804"] = "Meu neto BILL me\ncontou de um\fPOKéMON que tem\nlíngua longa.",
  ["54:5843"] = "Ah, meu neto\nfalou de um\fPOKéMON verde e\nredondo, com\vfolhas na cabeça.",
  ["54:5897"] = "Conhece o\nPOKéMON que tem\fesfera vermelha\nno corpo?\fSabe, aquele\nque parece uma\vestrela?\fEu ouvi que\nsurge à noite.\fEu adoraria\nver ele.",
  ["54:5942"] = "BILL me contou\nde um POKéMON\fmuito fiel ao\nseu treinador.\fDizem que sabe\nrugir muito bem!",
  ["54:599b"] = "Ouvi falar de um\nPOKéMON fofo que\vtem seis rabos.\fEu adoraria\nabraçar esse\vPOKéMON fofinho!",
  ["54:59f5"] = "Conhece aquele\nPOKéMON muito\vfamoso?\fO POKéMON de\ncorpo amarelo e\vbochechas rubras?\fEu adoraria ver\ncomo ele fica\fantes de\nevoluir!",
  ["54:8c48"] = "\nPapai me deu o\fque voltou! A TAIL\ndele cresce!",
  ["54:ca00"] = "!\fSe POKéMON entrar\nem batalha, mesmo\fpor pouco tempo,\nganha EXP.\fNo topo da lista\npõe o fraco.\fTroque na batalha\nrápido!\fAssim, o fraco\nPOKéMON fica\vforte!",
  ["54:f200"] = "Mas acho que eles\ntambém pensam em\voutros pontos.",
  ["55:4013"] = "Seus POKéMON sabem\ngolpes de HM?\fEsses golpes podem\nser usados mesmo\fse o seu POKéMON\ndesmaiou.",
  ["55:4067"] = "O PC do BILL\nguarda até 20\vPOKéMON por BOX.",
  ["55:4092"] = "Você conhece os\nAPRICORNS?\fAbra um, esvazie\npor dentro e põe\fum aparelho\nespecial.\fAí dá para pegar\nPOKéMON com ele.\fAntes das POKé\nBALLS existirem,\ftodo mundo usava\nAPRICORNS.",
  ["55:41ed"] = "Todos os SLOWPOKE\nsumiram\vda cidade.\fO protetor da\nfloresta pode\vestar bravo…\fPode ser mau\nagouro. É melhor\vficar em casa.",
  ["55:4276"] = "Os SLOWPOKE\nvoltaram…\fMas meu APRENDIZ\nnão voltou\vda ILEX FOREST.\fOnde será que\nestá o folgado?",
  ["55:42ec"] = "Você espantou a\nTEAM ROCKET e foi\fsozinho pra ILEX\nFOREST?\fQue coragem!\nGostei. Vem\vtreinar conosco!",
  ["55:4359"] = "Para onde foram\nos SLOWPOKE?\fEstão brincando\nem algum lugar?",
  ["55:439e"] = "Desculpe, esqueci\nde agradecer.\fIsto é CHARCOAL\nque eu fiz.\fPOKéMON de fogo\nvai adorar\vsegurar isso.",
  ["55:440c"] = "Os SLOWPOKE\nvoltaram, e você\vachou FARFETCH'D.\fVocê é o cara!\nBacana, hein!",
  ["55:44c6"] = "Não tem GREAT BALL\naqui. As POKé\fBALLS vão ter\nque servir.\fQueria que o KURT\nme fizesse umas\vBALLS especiais.",
  ["55:452f"] = "Uma GREAT BALL é\nmelhor para pegar\vPOKéMON que uma\vPOKé BALL.\fMas as do KURT às\nvezes são\vmelhores.",
  ["55:47ee"] = "Hm? Quem é você?\f{PLAYER}, é? Quer\nque eu faça umas\vBALLS?\fDesculpe, mas isso\nvai esperar.\fConhece a TEAM\nROCKET? Ah, não\fimporta. Eu conto\nde qualquer forma\fA TEAM ROCKET é\numa gangue má que\fusa POKéMON para\no trabalho sujo.\fEra para eles\nterem se desfeito\vhá três anos.\fEnfim, estão no\nPOÇO, cortando\fSLOWPOKETAILS para\nvender!\fEntão eu vou lá\ndar uma lição\vdolorosa neles!\fAguente firme,\nSLOWPOKE! O velho\vKURT está indo!",
  ["55:4990"] = "KURT: {PLAYER}!\fVocê se saiu\ncomo um herói\vno POÇO.\fGostei do estilo!\fSeria uma honra\nfazer BALLS\fpara um treinador\ncomo você.\fÉ tudo que tenho\nagora, mas leve.",
  ["55:4a44"] = "KURT: Eu faço\nBALLS de APRICORN\fColha eles das\nárvores e traga\vaqui.\fEu faço BALLS\ncom eles.",
  ["55:4ab1"] = "KURT: Tem um\nAPRICORN para mim\fÓtimo! Vou virar\nele numa BALL.",
  ["55:4af4"] = "KURT: Vai levar um\ndia para a BALL.\fVolte depois\npara pegar.",
  ["55:4b37"] = "KURT: Ah…\nQue decepção.",
  ["55:4b53"] = "KURT: Trabalhando!\nNão me amole!",
  ["55:4b76"] = "KURT: Ah, {PLAYER}!\nAcabei de terminar\vsua BALL. Tome!",
  ["55:4ba5"] = "KURT: Ficou muito\nboa.\fTente pegar\nPOKéMON com ela.",
  ["55:4bde"] = "Os SLOWPOKE se\nforam… Será que\fgente ruim levou\neles?",
  ["55:4c1a"] = "O vovô saiu…\nQue solidão…",
  ["55:4c38"] = "O SLOWPOKE que meu\npai deu voltou!\fA TAIL dele está\ncrescendo!",
  ["55:4c7e"] = "Meu pai trabalha\nna SILPH, onde ele\vestuda POKé BALL.\fEu fico em casa\ncom o vovô e o\vSLOWPOKE.",
  ["55:4cdb"] = "SLOWPOKE: …\nBocejo?",
  ["55:4cee"] = "…Um PROF.OAK\njovem?",
  ["55:4d03"] = "É uma estátua do\nprotetor da\vfloresta.",
  ["55:4e83"] = "Eu sou o BUGSY!\nEu nunca perco\fquando o assunto\né POKéMON inseto.\fMinha pesquisa vai\nme tornar a maior\fautoridade em\nPOKéMON inseto!\fDeixe eu mostrar o\nque aprendi nos\vmeus estudos.",
  ["55:4f26"] = "Uau, incrível!\nVocê é um perito\vem POKéMON!\fMinha pesquisa\nainda não acabou.\fCerto, você venceu\nLeve esta BADGE.",
  ["55:4f8c"] = "{PLAYER} recebeu\na HIVEBADGE.",
  ["55:4fa3"] = "Conhece as vanta-\ngens da HIVE-\vBADGE?\fCom ela, POKéMON\naté o L30 vão\vobedecer você.\fPOKéMON que sabem\nCUT poderão usar\fo golpe fora da\nbatalha também.\fTome, quero que\nfique com isto.",
  ["55:5060"] = "A TM49 contém\nFURY CUTTER.\fSe você não errar,\nele fica mais\vforte a cada vez.\fQuanto mais longa\na batalha, melhor\vele fica.\fNão é ótimo?\nEu que descobri!",
  ["55:50fe"] = "POKéMON inseto são\nprofundos. Há\fmuitos mistérios\na explorar.\fEstude bem os\nseus preferidos.",
  ["55:515e"] = "POKéMON inseto\nevoluem jovens.\fE por isso ficam\nmais fortes.",
  ["55:519d"] = "Só evoluir não\nbasta!",
  ["55:51b9"] = "POKéMON ficam\nmais fortes se\vevoluem. Sério!",
  ["55:51e7"] = "Os insetos são\nlegais e fortes!\fVou provar para\nvocê!",
  ["55:521a"] = "Você provou como é\ndurão…",
  ["55:5239"] = "São tão legais,\nmas as meninas\fnão gostam de\nPOKéMON inseto.\fNão sei por quê…",
  ["55:527e"] = "Você salvou todos\nos SLOWPOKE?\vUfa! Você é fera!\fMas meus POKéMON\nadultos são bem\vdurões também!",
  ["55:52e4"] = "Deveria ensinar\na eles melhores\vmovimentos.",
  ["55:530f"] = "AMY: Oi! Você vai\ndesafiar o LÍDER?\vNem pensar!",
  ["55:5341"] = "AMY & MAY: Oh,\nduplamente bom!",
  ["55:5362"] = "AMY: Você é\nmuito forte!",
  ["55:537d"] = "MAY: Você quer\nver o LÍDER?\vNós primeiro!",
  ["55:53ae"] = "AMY & MAY: Oh,\nduplamente bom!",
  ["55:53cf"] = "MAY: Meus insetos\nperderam! Que\vpena!",
  ["55:53fc"] = "Ei, desafiante!\fO BUGSY é jovem,\nmas sabe muito\fde POKéMON inseto\nde verdade.\fVai ser difícil\nsem o meu\vconselho.\fVejamos… POKéMON\ninseto não gostam\vde fogo.\fGolpes voadores\ntambém são super\vefetivos.",
  ["55:54bf"] = "Muito bem! Foi um\nbelo confronto\fentre jovens\ntalentosos.\fCom gente como\nvocê, o futuro dos\vPOKéMON é lindo!",
  ["55:5600"] = "mais! Você\né ótimo com os\vPOKéMONS!\fTenho muito\na pesquisar ainda.\fVocê venceu. Leve\na INSÍGNIA DA\vCOLMÉIA.",
  ["55:9d51"] = "no rádio.",
  ["55:ae53"] = "quer usar,\ne vem me ver.",
  ["55:da52"] = "PT.STORE.",
  ["56:400f"] = "Quando você pega\num POKéMON novo,\vele é fraco.\fMas com o tempo\nele vai ficar\vforte.\fÉ importante\ntratar POKéMON com\vcarinho.",
  ["56:4090"] = "POKéMON podem\nsegurar itens como\vPOTION e ANTIDOTE\fMas parece que não\nsabem usar\fitens feitos por\ngente.",
  ["56:41e0"] = "Sou FALKNER, líder\ndo GINÁSIO POKéMON\vde VIOLET!\fDizem que dá para\ncortar as asas de\fPOKéMON voadores\ncom um choque\velétrico…\fNão vou permitir\ntal insulto às\vaves POKéMON!\fVou lhe mostrar o\npoder de verdade\fdas magníficas\naves POKéMON!",
  ["56:42b7"] = "…Droga! As aves\nqueridas do meu\vpai…\fTudo bem.\nPegue isto.\fÉ a ZEPHYRBADGE\noficial da LIGA\vPOKéMON.",
  ["56:431c"] = "{PLAYER} recebeu\na ZEPHYRBADGE.",
  ["56:4335"] = "A ZEPHYRBADGE\naumenta o ataque\vdos seus POKéMON.\fEla também deixa\no POKéMON usar\fFLASH, se souber,\na qualquer hora.\fTome, leve isto\ntambém.",
  ["56:43b5"] = "Usando uma TM, o\nPOKéMON aprende\fna hora um golpe\nnovo.\fPense antes de\nagir: uma TM só\vserve uma vez.\fA TM31 tem\nMUD-SLAP.\fEla reduz a\nmira do inimigo\fenquanto causa\ndano.\fOu seja, é defesa\ne ataque ao mesmo\vtempo.",
  ["56:44a2"] = "Há GINÁSIOS\nPOKéMON em cidades\vmais à frente.\fVocê devia testar\nsua habilidade\vnesses GINÁSIOS.\fVou treinar mais\nforte para virar\fo maior mestre de\naves!",
  ["56:453a"] = "A palavra de\nordem é raça!\fO pessoal aqui\ntreina noite e\fdia para virar\nmestre de POKéMON\fvoador. Venha!",
  ["56:45a4"] = "O talento do\nFALKNER é real!\fNão se ache só\nporque venceu\va mim!",
  ["56:45ec"] = "Deixa eu ver se\nvocê é bom o\vbastante!",
  ["56:4620"] = "Isso não pode\nser verdade!",
  ["56:4634"] = "Que vergonha,\nperder para um\vnovato…",
  ["56:4666"] = "Ei! Não sou\ntreinador, mas dou\vum conselho!\fAcredite em mim!\nSe você acredita,\fo sonho de ser\ncampeão acontece.\fAcredita?\nEntão escute.\fO tipo planta é\nfraco contra o\ftipo voador. Não\nesqueça disso.",
  ["56:4735"] = "Boa batalha!\nContinue assim e\fvocê vira CAMPEÃO\nnum piscar!",
  ["56:48a8"] = "EARL sou eu!\fMaravilhosos\nsão os POKéMON,\fsim!\nEnsinar você\veu vou!\fO que quer\nsaber? Vencedor\vser você quer?",
  ["56:492a"] = "Bom! Ensinar\neu vou!\fEm batalha, o\nPOKéMON do topo\vda lista sai!\fMude a ordem\nna lista, fácil\va luta fica!\fMais de mim\nquer ouvir?",
  ["56:49be"] = "Então, quer saber\ncomo criar bem\vos POKéMON?",
  ["56:49e8"] = "Tá bom! Eu vou\nensinar!\fSe POKéMON entrar\nem batalha, mesmo\fpor pouco tempo,\nganha EXP.\fNo topo da lista\npõe o fraco.\fTroque na batalha\nrápido!\fAssim, o fraco\nPOKéMON fica\vforte!",
  ["56:4a9e"] = "Oh! Aluno esperto\nvocê é! Nada mais\veu ensino!\fBom com POKéMON\ndeve ser você!",
  ["56:4aed"] = "Estou anotando\na aula do\vprofessor.\fMelhor copiar\no que está no\vquadro também.",
  ["56:4b47"] = "Troquei meu melhor\nPOKéMON com o\vcara do meu lado.",
  ["56:4b74"] = "Hã? O POKéMON que\nacabei de pegar\vsegurando algo!",
  ["56:4ba6"] = "POKéMON com uma\nBERRY se cura\vna batalha.\fOutros itens\ntambém podem ser\vsegurados…\fÉ difícil\nanotar tudo…",
  ["56:4c1f"] = "O quadro fala\nsobre mudanças\fde status em\nbatalha.",
  ["56:4c58"] = "Qual tópico ler?",
  ["56:4c6b"] = "Envenenado, o\nPOKéMON perde\vPS aos poucos.\fO veneno\npersiste após a\fbatalha, e o PS\ncai ao andar.\fPra curar, use\num ANTIDOTE.",
  ["56:4ced"] = "A paralisia\ndiminui a velo-\vcidade e impede\fde andar.\nFica após a luta,\vuse PARLYZ HEAL.",
  ["56:4d4f"] = "Adormecido, seu\nPOKéMON não pode\vse mexer.\fPOKéMON dormindo\nnão acorda após\va batalha.\fAcorde com um\nAWAKENING.",
  ["56:4dc2"] = "Uma queimadura\nconsome PS.\fEla reduz\no ataque.\fQueimadura\nfica após a luta.\fUse um BURN HEAL\npra curar.",
  ["56:4e38"] = "Congelado, o\nPOKéMON não pode\vfazer nada.\fFica congelado\napós a batalha.\fDescongele com\num ICE HEAL.",
  ["56:4ea3"] = "É o caderno\ndeste garoto…\fPegue POKéMON\ncom POKé BALLS.\fAté seis podem\nna sua equipe.\fContinuar lendo?",
  ["56:4f04"] = "Antes da POKé\nBALL, enfraqueça\vo alvo primeiro.\fEnvenenado ou\nqueimado, o\vPOKéMON é fácil\fde pegar.",
  ["56:4f74"] = "Alguns movimentos\ncausam confusão.\fNa confusão,\no POKéMON pode\vse atacar.\fSair da batalha\ncura qualquer\vconfusão.\fContinuar lendo?",
  ["56:4ff4"] = "Quem pega e usa\nPOKéMON em\fbatalhas são os\ntreinadores.\fEles devem ir\naos GINÁSIOS e\fvencer outros\ntreinadores.\fA próxima página\nestá em branco!\fGaroto: E-he-he…\fNão escrevi\nmais nada…",
  ["56:50b1"] = "Esta máquina im-\nprime dados como\ffigurinhas!",
  ["56:5167"] = "Ela usa os nomes\ndas suas comidas\vpreferidas.\fNos apelidos\nque ela dá aos\vPOKéMON, digo.",
  ["56:51cb"] = "Chamo meu PIDGEY\nde STRAWBERRY!",
  ["56:51e9"] = "STRAWBERRY:Pijji!",
  ["56:52c2"] = "{PLAYER}, faz\ntempo, hein!\fPROF.ELM pediu\npra te achar.\fEle quer pedir\noutro favor.\fAceita levar o\nPOKéMON EGG?",
  ["56:5332"] = "Descobrimos que\num POKéMON não\fchoca até\ncrescer no EGG.\fEle também tem\nde ficar com\voutros POKéMON.\f{PLAYER}, você\né o único em\vquem confiamos.\fLigue pro PROF.\nELM quando o EGG\vchocar!",
  ["56:5400"] = "Ah, não. Você\nnão pode levar\vmais POKéMON.\fVou esperar\nenquanto você\varruma espaço.",
  ["56:545f"] = "M-mas… O PROF.ELM\npediu por você…",
  ["56:547f"] = "{PLAYER}, você\nleva o EGG?",
  ["56:549a"] = "Um cara chamado\nBILL fez o sistema\vde POKéMON do PC.",
  ["56:54cd"] = "Foi há mais ou\nmenos três anos.\fA TEAM ROCKET\nfazia maldades\vcom POKéMON.\fMas a justiça\nvenceu: um garoto\vacabou com eles.",
  ["56:5549"] = "POKéMON são\nespertos.\fNão obedecem a\num treinador que\fnão respeitam.\nSem as GYM BADGES\fcertas, eles só\nagem como querem.",
  ["56:5628"] = "POKéMON trocado\ncresce\vrápido.\fMas sem a GYM\nBADGE certa,\feles podem\ndesobedecer você.",
  ["56:56c7"] = "RUÍNAS DE ALPH\fUm Turismo de\nVer e Tocar\fTente os painéis\nde pedra!",
  ["56:5712"] = "Está estudando\nas RUÍNAS?\fVejo um cientista\nem formação.",
  ["56:574e"] = "Há desenhos\nnas pedras.\fTentei mover\neles. Será que\vsão o quê?",
  ["56:5814"] = "Este é um ótimo\nlugar pra pescar.\fVocê viu gente\npescando? Que tal\vvocê?\fQuer uma das\nminhas RODS?",
  ["56:5879"] = "Heh, que bom\nouvir isso.\fAgora você é\npescador também!",
  ["56:58ac"] = "Pescar é ótimo!\fSe há água,\nseja no mar ou\fem um riacho,\nuse sua ROD.",
  ["56:58fd"] = "Oh. Que\ndecepção…",
  ["56:591e"] = "Ei, garoto. Como\nestão mordendo?",
  ["56:5943"] = "O que devo dar\nao meu POKéMON?\fTalvez um item\nque aumente o\vATAQUE…",
  ["56:5a70"] = "Ei, moço!\nPode fazer um\vfavor?\fPode levar este\nPOKéMON com MAIL\vpro meu amigo?\fNa ROUTE 31.",
  ["56:5adb"] = "Vai? Perfeito!\nValeu, moço!\fMeu amigo é\num cara gordinho\vque só cochila.\fVocê vai\nreconhecer fácil!",
  ["56:5b4b"] = "{PLAYER} recebeu\nPOKéMON com MAIL.",
  ["56:5b69"] = "Pode ler,\nmas não perca!\vROUTE 31!\fAh, sim. Tinha\numa árvore\vesquisita na\festrada. Será\nque tiraram?",
  ["56:5be9"] = "Não pode levar\noutro POKéMON…",
  ["56:5c07"] = "Oh… Deixa pra\nlá…",
  ["56:5c1e"] = "Valeu, moço! Você\nfez a entrega\vpor mim!\fTome algo\npela ajuda!",
  ["56:5c6c"] = "Meu amigo estava\ncochilando, né?\vO que eu disse?",
  ["56:5c9d"] = "Uma árvore\nestranha bloqueia\fa estrada.\nEla se mexe\fse você falar.\nDizem que ela\fficou selvagem\ncom SQUIRTBOTTLE.",
  ["56:5d2d"] = "Gosto do POKéMON\nLullaby que toca\vno rádio.",
  ["56:5ef2"] = "Hoje é {STRBUF}.\nIsso quer dizer\fque o Concurso de\nInsetos é hoje.\fAs regras são\nsimples.\fUse um dos seus\nPOKéMON pra pegar\fum inseto que\nserá avaliado.\fQuer dar uma\nchance?",
  ["56:5fa4"] = "Aqui estão as\nPARK BALLS pro\vConcurso.",
  ["56:5fce"] = "{PLAYER} recebeu\n20 PARK BALLS.",
  ["56:5fe9"] = "Quem pegar o\ninseto mais\vforte vence\vo jogo.\fVocê tem 20\nminutos.\fSe ficar sem\nPARK BALLS, já\vera.\fPode ficar com\no último inseto\vque pegar.\fVai lá e pega\no inseto mais\fforte que\npuder!",
  ["56:60cd"] = "Opa…\fVocê tem mais\nde um POKéMON.\fVai ter que\nusar {STRBUF},\fo primeiro POKéMON\nda sua equipe.\fTudo bem\ncom você?",
  ["56:613e"] = "Certo, seguramos\nseus outros\vPOKéMON.",
  ["56:619e"] = "Escolha o\nPOKéMON que vai\fusar no Contest,\ne vem me ver.",
  ["56:61e3"] = "Certo. Esperamos\nque participe\vno futuro.",
  ["56:620f"] = "Opa…\nO primeiro POKé-\fMON da equipe\nnão pode lutar.\fTroque com o\nPOKéMON que você\fquer usar,\ne vem me ver.",
  ["56:6283"] = "Opa…\nSua equipe e a\fPC BOX estão\ncheias.\fNão tem espaço\npra pôr o inseto\vque você pegar.\fFaça um espaço\nna equipe ou na\fPC BOX e\nvem me ver.",
  ["56:6326"] = "Opa…\nVocê tem um EGG\fcomo primeiro\nPOKéMON inicial.\fTroque com o\nPOKéMON que você\fquer usar,\ne vem me ver.",
  ["56:63a1"] = "Restam {STRBUF}\nminuto(s) ainda.\fQuer terminar\nagora?",
  ["56:63e2"] = "Certo. Espere no\nPortão Norte\fpelo anúncio\ndos vencedores.",
  ["56:642a"] = "Certo. Volte\npra fora e\vtermine.",
  ["56:6456"] = "O Concurso de\nhoje acabou.\fEsperamos que\nparticipe depois.",
  ["56:649b"] = "Fazemos Concursos\nno PARK toda\fhora. Deveria\ntentar.",
  ["56:64df"] = "Quando é o\npróximo Concurso\vde Insetos?",
  ["56:6515"] = "O Concurso de\nCaptura Insetos\fé realizado na\nterça, quinta e\fsábado.\nNão só você ganha\fum prêmio por vir,\ncomo também pode\fficar com um\nPOKéMON inseto.",
  ["56:660d"] = "Não se pergunta\nquem faria algo\vassim?\vE por quê?",
  ["56:6648"] = "Você viu aquela\nárvore estranha\vna estrada?\fIsso pode explicar\npor que menos\fpessoas visitam\nas RUÍNAS.",
  ["56:69c0"] = "Hoje é {STRBUF}.\nIsso quer dizer\fo Concurso de\nCaptura Insetos\fé hoje.\nAs regras são\fsimples.\nUse um dos seus\fPOKéMON, capture\num POKéMON inseto\fpara ser julgado.\nVocê quer tentar?",
  ["56:6a70"] = "Aqui estão as\nPARK BALLS para\vo Concurso.",
  ["56:6a9a"] = "{PLAYER} recebeu\n20 PARK BALLS.",
  ["56:6ab5"] = "A pessoa que\ncapturar o\vPOKéMON inseto\vmais forte é a\fvencedora.\nVocê tem 20\fminutos.\nSe ficar sem PARK\vBALLS, acabou.\fVocê pode ficar\ncom o último\vPOKéMON que\fcapturar.\nVá e capture o\fPOKéMON inseto\nmais forte!",
  ["56:6b99"] = "Opa…\fVocê tem mais de\num POKéMON.\fVocê terá que usar\n{STRBUF}, o\fprimeiro POKéMON\nna sua equipe.\fEsta tudo bem\ncom você?",
  ["56:6c0a"] = "Tudo bem. Vamos\nguardar os outros\vdurante o teste.",
  ["56:6c3e"] = "POKéMON de\n{PLAYER} ficaram\vcom o HELPER.",
  ["56:6c6a"] = "Escolha o POKéMON\npara usar no\fConcurso, depois\nvenha me ver.",
  ["56:6caf"] = "OK. Esperamos que\nvocê participe\vno futuro.",
  ["56:6cdb"] = "Opa…\nO 1º POKéMON\fna sua equipe\nnão pode lutar.\fTroque-o pelo\nPOKéMON que quer\fusar, depois\nvenha me ver.",
  ["56:6d4f"] = "Opa…\nSua equipe e seu\fPC BOX estão\ncheios.\fVocê não tem\nonde guardar o\vPOKéMON inseto\fque capturar.\nLibere espaço na\fequipe ou na BOX,\ndepois volte.",
  ["56:6df2"] = "Opa…\nVocê tem um OVO\fcomo o primeiro\nPOKéMON do grupo.\fTroque-o pelo\nPOKéMON que quer\fusar, depois\nvenha me ver.",
  ["56:6e6d"] = "Ainda restam\n{STRBUF} min.\fQuer terminar\nagora?",
  ["56:6eac"] = "OK. Por favor\nespere aqui pelo\fanuncio dos\nvencedores.",
  ["56:6ee7"] = "OK. Volte lá fora\ne termine\vo que falta.",
  ["56:6f12"] = "O Concurso de hoje\nacabou. Esperamos\fque você participe\nno futuro.",
  ["56:6f57"] = "Alguns POKéMON só\npodem ser vistos\vno PARQUE.",
  ["56:6f80"] = "DON: Uau, você me\nvenceu. Você e\vmuito bom.",
  ["56:6fab"] = "DON: Sorte tem uma\nmuita influência.\fNunca se sabe\nque POKéMON vai\vaparecer.",
  ["56:6ff6"] = "ED: Invidio você.\nNão consegui\vdesta vez.",
  ["56:7027"] = "ED: Talvez você\nvenca com POKéMON",
  ["56:7049"] = "NICK: Muito bem!\nVou criar meus\vPOKéMON melhor.",
  ["56:707d"] = "NICK: Talvez você\nganhe mais pontos\fmaior com um\nPOKéMON incomum.",
  ["56:70c1"] = "WILLIAM: Você e\no vencedor? O que\vvocê capturou?",
  ["56:70f1"] = "WILLIAM: Estou\nsatisfeito porque\fpeguei o POKéMON\nque eu queria.",
  ["56:7135"] = "BENNY: Parabéns!\nVocê ganhou meu\vrespeito!",
  ["56:7163"] = "BENNY: Eu capturei\num SCYTHER antes,\vmas não venci.",
  ["56:7197"] = "BARRY: O POKéMON\nque você capturou\v…e incrível!",
  ["56:71c4"] = "BARRY: É mais\nvencer se você\fcapturar um\nPOKéMON inseto de\fnível alto.\nMas acho que eles\volham mais coisas",
  ["56:7232"] = "CINDY: Venceu?\nQue ótimo!\fVocê quer ir\ncaçar POKéMON\vinsetos comigo?",
  ["56:727f"] = "CINDY: Eu amo\nPOKéMON insetos!",
  ["56:729f"] = "JOSH: Eu… não\nacredito que perdi\vno concurso…",
  ["56:72d0"] = "JOSH: Ouvi que\nalguém venceu\vcom um CATERPIE!",
  ["56:7302"] = "SAMUEL: Na próxima\nvou vencer.",
  ["56:7327"] = "SAMUEL: Droga.\nAchei que teria\vmelhor pontuação…",
  ["56:7356"] = "KIPP: Você pode\nme dar dicas?\fQuero estudar\nseu estilo.",
  ["56:7396"] = "KIPP: Estudo bem,\nmas isso não é\fsuficiente para\nvencer.",
  ["56:73ce"] = "Dizem que há um\nPOKéMON parecido\vcom uma árvore.\fVocê pode revelar\nsua identidade com\vum SILPHSCOPE 2.",
  ["56:7433"] = "O CONCURSO DE\nCAPTURA ocorre\fterça, quinta\ne sábado.\fNão só você ganha\num prêmio por\fparticipar,\nmas também fica\fcom o inseto que\nvocê capturar.",
  ["56:74dd"] = "Opa… Seu PACK\nesta cheio.\fGuardaremos seu\nprêmio, mas\vsó por hoje.\fLibere espaço,\ndepois volte.",
  ["56:754c"] = "{PLAYER}?\fAqui esta o prêmio\nque estavamos\vpara você.",
  ["56:9c45"] = "de graça.\nPresente. Dê pro\vPOKéMON segurar.",
  ["56:a000"] = "DEFENSE.",
  ["57:4122"] = "Oi! Sou WHITNEY!\fTodo mundo curtia\nPOKéMON, então eu\ventrei também!\fPOKéMON são\nfofos demais!\fQuer batalhar?\nEstou avisando,\veu sou boa!",
  ["57:41a5"] = "Snif…\f…Buááááá!\nVocê é mau!\fNão devia levar\ntão a sério! Você,\vvocê, criança!",
  ["57:41f5"] = "Buááááá!\fBuááááá!\f…Funga, soluço…\n…Seu malvado!",
  ["57:4223"] = "…Snif…\fO quê? O que você\nquer? Uma BADGE?\fAh, é. Eu tinha\nesquecido. Tome a\vPLAINBADGE.",
  ["57:4278"] = "{PLAYER} recebeu\na PLAINBADGE.",
  ["57:4290"] = "A PLAINBADGE deixa\nseu POKéMON usar\fSTRENGTH fora da\nbatalha.\fEla também aumenta\na VELOCIDADE do\vseu POKéMON.\fAh, pode ficar\ncom isto também!",
  ["57:4307"] = "É o ATTRACT!\nEle usa todo o\fcharme de um\nPOKéMON.\fNão é perfeito\npara uma fofa\vcomo eu?",
  ["57:4365"] = "Ah, chorei bem!\nQue alívio!\fVolte para visitar\nde novo! Tchau!",
  ["57:43a0"] = "Não pense que sou\nfácil de vencer!",
  ["57:43bb"] = "Droga… Pensei que\nvocê fosse fraco…",
  ["57:43db"] = "No mundo dos\nPOKéMON, será que\fé mais forte:\nmacho ou fêmea?",
  ["57:441b"] = "Gosto mais de POKé\nMON fofos do que\vdos fortes.\fMas tenho POKéMON\nfortes e fofos!",
  ["57:447a"] = "Tento vencer a\nWHITNEY, mas…\vÉ deprimente.\fEstou bem! Se eu\nperder, tentarei\fde novo da pró-\nxima vez!",
  ["57:44de"] = "Ah, não. Você fez\na WHITNEY chorar.\fTudo bem. Ela para\nlogo. Ela sempre\fchora quando\nperde.",
  ["57:4537"] = "Oh, que treinador\nbonitinho! Gosto\fde você, mas não\nvou me segurar!",
  ["57:457e"] = "Vejamos… Ops,\nacabou?",
  ["57:4599"] = "Uau, você deve ser\nbom pra me vencer!\vContinue assim!",
  ["57:45c8"] = "Dê o seu melhor,\nou eu vou te der-\vrubar!",
  ["57:45f7"] = "Não! Oh, MEOWTH,\nme desculpe!",
  ["57:4615"] = "Ensinei ao MEOWTH\ngolpes para lidar\vcom todo tipo…",
  ["57:4644"] = "E aí! Futuro\nCAMPEÃO!\fEste GINÁSIO é de\ntreinadores de\vPOKéMON normais.\fRecomendo que use\nPOKéMON do tipo\vlutador.",
  ["57:46b1"] = "Ganhou? Ótimo! Eu\nestava ocupado\volhando as moças.",
  ["57:4791"] = "…Suspiro… Me\nmudei, mas não\fvendo minhas\nBICYCLE. Por quê?\fAh, sei! Você\npoderia andar e\vanunciar pra mim?",
  ["57:4802"] = "Sério? Ótimo!\fDê-me seu nome\ne telefone e\flhe empresto\numa BICYCLE.",
  ["57:4852"] = "{PLAYER} pegou\numa BICYCLE.",
  ["57:4869"] = "Minhas BICYCLEs\nsão de primeira!\fVocê pode andar\nem qualquer lugar",
  ["57:48a2"] = "…Suspiro… Ah,\nse as pessoas\vfossem boas…",
  ["57:48ca"] = "Acabaram de sair!\fBicicletas compac-\ntas de primeira!",
  ["57:48f7"] = "É uma BICYCLE\nnova e brilhante!",
  ["57:49ad"] = "Se tratar seu\nPOKéMON bem,\feles vão te amar\nde volta.\fAh? Deixe ver\nseu {STRBUF}…",
  ["57:4a06"] = "Ele parece muito\nfeliz! Deve te\vamar muito.",
  ["57:4a36"] = "Tenho a sensação\nde que ele\vconfia em você.",
  ["57:4a98"] = "Ele é bem fofo.",
  ["57:4aa9"] = "Trate ele melhor.\nEle ainda não\vconfia em você.",
  ["57:4adb"] = "Ele não parece\ngostar de você.\vParece bravo.",
  ["57:4b0e"] = "Vivo perdendo\nbatalhas e meus\fPOKéMON acabam\ndesmaiando…\fTalvez por isso\nmeus POKéMON não\vgostem de mim…",
  ["57:4b71"] = "Quando uso item\nno POKéMON, ele\vfica todo feliz!",
  ["57:4c7e"] = "BILL: Oi, {PLAYER}!\nFaça um favor e\vfique com este\fEEVEE.\nEle veio quando\veu ajustava\fa TIME CAPSULE.\nAlguém precisa\ftomar conta,\nmas eu não gosto\fde sair.\nPosso contar com\vvocê, {PLAYER}?",
  ["57:4d49"] = "BILL: Eu sabia!\nIsso aí, herói!\fVocê é um cara\ndos bons!\fOK, conto com\nvocê. Cuide\vbem dele.",
  ["57:4db5"] = "{PLAYER} recebeu\num EEVEE!",
  ["57:4dc8"] = "BILL: O PROF.ELM\ndiz que o EEVEE\fpode evoluir de\nmodos inéditos.",
  ["57:4e09"] = "Ei, espera. Você\nnão pode levar\vmais POKéMON.",
  ["57:4e34"] = "Oh… E agora,\no que fazer?",
  ["57:4e49"] = "BILL: Eu costumava\nfazer testes com\vum TELEPORTER.\fDeveria dar\ncontinuação.",
  ["57:4e93"] = "Ah, coleciona\nPOKéMON? Meu filho\vBILL é um expert.\fEle teve que ir\nao CENTRO POKéMON\fde ECRUTEAK\nCITY.",
  ["57:4efa"] = "Fico tão feliz\nem ver meu filho.",
  ["57:4f1d"] = "Você é treinador?\fTenho um número\nde telefone\vútil pra você.",
  ["57:4f58"] = "{PLAYER} anotou\no número do BILL.",
  ["57:4f72"] = "Meu irmão criou\no sistema de\vguarda de POKéMON\fno PC.\nIa te dar o\vnúmero do BILL…",
  ["57:4fc5"] = "Você não pode mais\nanotar números.",
  ["57:4fe8"] = "Meu irmão mais\nvelho, BILL, fez\fo sistema de\nguarda de POKéMON",
  ["57:50d7"] = "O trem não\nchegou…\fJá sei! Vou levar\nos passageiros\vnas costas!\fNão vai dar.",
  ["57:512e"] = "Vamos partir logo\npara SAFFRON.\fVocês virão\na bordo?",
  ["57:5164"] = "Posso ver seu\nRAIL PASS?\fCerto. Venha por\naqui, senhor.",
  ["57:51a0"] = "Desculpe. Você\nnão tem RAIL PASS",
  ["57:51c3"] = "Esperamos vê-lo\nnovamente!",
  ["57:51de"] = "Chegamos a\nGOLDENROD!\fEsperamos vê-lo\nde novo.",
  ["57:5217"] = "Sou o PRESIDENTE.\fMeu sonho era\nconstruir um trem\fmais rápido que\nqualquer POKéMON.\fEle realmente\naproxima JOHTO e\vKANTO.",
  ["57:5311"] = "Ah, você é melhor\nque a WHITNEY.\fConhece aquela\nárvore que anda?\fSe molhá-la com\numa SQUIRTBOTTLE,\vela ataca.\fMas, como você\ntem BADGE,\vvai ficar bem.",
  ["57:53b6"] = "Lalala lalalala.\nMuita água,\vminha linda!",
  ["57:53e9"] = "Quando molhei\naquela árvore\fque anda na ROTA\n36, ela pulou!\fSó pode ser\num POKéMON.\fMas só alguém\ncomo a WHITNEY,\vnossa LÍDER de\vGINÁSIO, a vence.",
  ["57:5485"] = "Conhece a árvore\nque anda?\fSe você a regar,\nela pula de\vsurpresa!",
  ["57:5513"] = "O COLOSSEUM\nnos andares do\fCENTRO POKéMON,\né para batalhas\fvia link.\nOs recordes de\fluta na parede,\nnão posso perder.",
  ["57:5597"] = "Quantos tipos de\nPOKéMON existem\fno mundo?\nHá três anos,\fo PROF.OAK disse\nque existiam 150\ftipos\ndiferentes.",
  ["57:5614"] = "Um POKéMON de\nnível mais alto\vnem sempre vence.\fEle pode até ter\ndesvantagem de\vtipo.\fAcho que não\nexiste um único\fPOKéMON que seja\no mais forte.",
  ["57:56fe"] = "Uma vez, numa\nbatalha, meu\fPOKéMON não\nconseguia agir.\fOs POWER POINTS,\nou PP, dos seus\fgolpes tinham\nacabado.",
  ["57:576f"] = "Às vezes, um\nPOKéMON saudável\fnão consegue usar\nseus golpes.\fSe isso ocorrer,\ncurar no CENTRO\vPOKéMON ou usar\vum item.",
  ["57:587b"] = "Queria te dar um\npouco de SWEET\fHONEY, mas você\nnão tem espaço.",
  ["57:58be"] = "Toma! Um pouco de\nSWEET HONEY!",
  ["57:58e3"] = "{PLAYER} recebeu\nSWEET HONEY.",
  ["57:58fc"] = "Meu irmão pega o\nSWEET HONEY, vai\fpra algum lugar\ncom ele.\fO que será que ele\nestá aprontando?",
  ["57:5956"] = "Você pôs SWEET\nHONEY na árvore?\fO que aconteceu\ncom ele?",
  ["57:598f"] = "Você pôs SWEET\nHONEY na árvore?\fLeva quase um\ndia para o POKéMON\vser atraído.",
  ["57:59e4"] = "BUTTERFREE: Freh!",
  ["57:5a38"] = "Bem-vindo à\nDEPT.STORE!",
  ["57:5a5c"] = "A DEPT.STORE tem\numa boa\vvariedade.\fMas alguns itens\nsó saem como\fprêmios do\nGAME CORNER.",
  ["57:5abf"] = "Estou doida para\ncomprar hoje!",
  ["57:5adf"] = "Mamãe é boa em\ncaçar promoção.\fEla sempre compra\nas coisas mais\vbaratas.",
  ["57:5b25"] = "1F BALCÃO\f2F MERCADO DO\n   TREINADOR\f3F COLEÇÃO DE\n   BATALHA\f4F REMÉDIOS\f5F CANTO DAS TM\f6F TERRAÇO",
  ["57:5c67"] = "Dar itens para os\nPOKéMON segurarem\vdurante a batalha\vpode virar o jogo\va seu favor.",
  ["57:5cb7"] = "A POKéGEAR pode\nguardar até dez\vnúmeros.\fÉ difícil\ndecidir quais\vguardar.",
  ["57:5d0d"] = "Ganhei meu ABRA\nna CASA DE JOGOS.\fAgora é meu\nmelhor parceiro.",
  ["57:5d49"] = "Esta LOJA me faz\nver que GOLDENROD\fé uma cidade\ngrande.\fA seleção daqui\nnão tem igual\vem nenhum lugar.",
  ["57:5dba"] = "SUA COMPANHEIRA\nDE VIAGEM\f2º ANDAR: MERCADO\nDO TREINADOR",
  ["57:5e5e"] = "Eu, eu, eu sou bem\nimpaciente!\fUso X SPEED na\nbatalha para\vacelerar POKéMON.",
  ["57:5ea7"] = "Ei! Em batalha,\nvocê usa X\vSPECIAL?\fÉ demais. Ele\naumenta muito\vos SPECIAL!",
  ["57:5f09"] = "Para os que Buscam\na Vitória\f3F COLECAO\nDE BATALHA",
  ["57:5f9d"] = "Ei. Amo POKéMON\nfortes.\fDou PROTEIN a\neles para elevar\vo ATTACK.",
  ["57:5fe7"] = "IRON: a DEFESA do\nPOKéMON sobe.",
  ["57:6009"] = "Alguns POKéMON\nevoluem quando\fsão trocados por\ncabo Game Link.\fConheço quatro:\nMACHOKE, KADABRA,\fHAUNTER e, hum,\nGRAVELER.\fDizem que existem\noutros também.",
  ["57:60a2"] = "Vamos Turbinar\nSeu POKéMON!\f4º ANDAR REMÉDIOS",
  ["57:61d8"] = "Olá. Oh, seu\nPOKéMON…",
  ["57:61ef"] = "Ele é muito afei-\nçoado a você.\fEste golpe deve\nser perfeito para\vvocês dois.",
  ["57:623b"] = "É adorável!\fEnsine bons\nmovimentos de TM.",
  ["57:626d"] = "Parece mau. Que\ntal esta TM para\vele?",
  ["57:6297"] = "Com certeza há\nTM perfeita para\fo seu\nPOKéMON.",
  ["57:62d6"] = "MYSTERY GIFT.\fCom um pequeno\nbip, você\vganha um presente",
  ["57:630e"] = "O MYSTERY GIFT\nexige um\vGame Boy Color.",
  ["57:6342"] = "Aos domingos, uma\nmoça vem olhar\vos POKéMON.\fEla até dá\nTM de presente!",
  ["57:6388"] = "Não dá para\nrenomear um\vPOKéMON trocado.\fO nome mostra o\ncarinho do\ftreinador antigo\npor ele.",
  ["57:63f9"] = "Personalize seu\nPOKéMON\f5º ANDAR: TM",
  ["57:6560"] = "Uma máquina de\nvendas! O menu:",
  ["57:6584"] = "Click! Uma\nlata de {STRBUF}\vcaiu!",
  ["57:65a7"] = "Opa, dinheiro\ninsuficiente…",
  ["57:65c0"] = "Não há mais espaço\npara coisas…",
  ["57:65e0"] = "Você ouve a\nLUCKY CHANNEL?\fSe quer vencer,\ntroque POKéMON\fcom o máximo de\ngente para ter\fnúmeros de ID\ndiferentes.",
  ["57:665f"] = "Se estiver cansado\ntente as bebidas\vdas máquinas.\fSeu POKéMON vai\namar também.",
  ["57:66af"] = "Descanse um pouco\ndas compras!\f6º ANDAR: TERRAÇO",
  ["57:6ab5"] = "Bem-vindo!\fTrocamos suas\nmoedas de jogo\vpor prêmios bons!",
  ["57:6af0"] = "Qual prêmio você\nquer?",
  ["57:6b0d"] = "{STRBUF}.\nÉ isso mesmo?",
  ["57:6b22"] = "Aqui está!",
  ["57:6b30"] = "Precisa de mais\nmoedas ainda!",
  ["57:6b4d"] = "Desculpe. Você\nnão pode carregar",
  ["57:6b6e"] = "OK. Guarde suas\nmoedas e\vvolte sempre!",
  ["57:6b9a"] = "Oh? Você não tem\na COIN CASE.",
  ["57:6bba"] = "Sempre jogo nesta\nmáquina.\fAcho que ela paga\nmais que outras.",
  ["57:6c03"] = "Adoro esta nova\ncaça-níqueis.\fÉ mais desafiadora\nque as de\vCELADON.",
  ["57:6c59"] = "A vida é um jogo.\nVou virar\vcartas até cair!",
  ["57:6c90"] = "Vira-cartas…\fPrefiro aos\ncaça-níqueis\fporque é mais\nfácil de calcular\fas chances.\nMas paga menos.",
  ["57:6cfc"] = "Não paro até\nconseguir vencer!",
  ["57:6d16"] = "Ensinei BLIZZARD\nao meu POKéMON.\fFoi difícil juntar\nas moedas para\fele, mas valeu\na pena.",
  ["57:6d72"] = "Perdi nas\ncaça-níqueis,\fgastei tudo\nna vira-cartas…\fFiquei tão nervoso\nque joguei fora\fminha COIN CASE\nno UNDERGROUND.",
  ["57:6f2c"] = "A ILEX FOREST\né grande. Cuidado!\vNão se perca.",
  ["57:6f5c"] = "A FLORESTA é\ncuidada pelo\vseu protetor.\fNada de\ntraquinagens!",
  ["57:6ffe"] = "Ah, querido. Faz\numa POKéDEX?\fDeve ser difícil\nse os POKéMON\fnão aparecem.\nTente usar a TM.",
  ["57:7057"] = "É SWEET SCENT.\fUse onde há\nPOKéMON por\fperto. Eles\nserão atraídos.",
  ["57:70b6"] = "Viu o santuário\nem honra ao\vprotetor?\fEle vigia a\nFLORESTA através\vdos tempos.\fAcho que deve ser\num POKéMON do tipo\vgrama.",
  ["57:71b8"] = "O vovô estava\nprocurando você.",
  ["57:c700"] = "…jeito\ncomo o CLEFAIRY\fbalança o dedo\nquando tenta usar\fMETRONOME.\nÉ tão fofo!",
  ["59:400b"] = "Eu sou o FISHING\nGURU, o mais velho\vdos FISHING BROS.\fPor acaso conhece\no FISHERMAN\fWILTON? Ele pesca\nna ROUTE 44.\fEle me ligou com\numa dica\vincrível.\fGraças a ele, eu\npeguei um monte\fde um POKéMON raro\nQue dia aquele!",
  ["59:40fa"] = "É uma foto de\ngente pescando…\fParecem estar\nse divertindo…",
  ["59:4177"] = "Um POKéMON dorme\nbem na frente da\vDIGLETT'S CAVE.\fÉ uma chance ótima\nde pegar ele,\fmas como acordar\no bicho?",
  ["59:41ef"] = "Antes tinha um\nPOKéMON dormindo\fbem na frente da\nDIGLETT'S CAVE.\fMas parece que\nele sumiu.",
  ["59:4255"] = "O FAST SHIP é um\nótimo lugar para\fachar e enfrentar\ntreinadores.",
  ["59:4292"] = "Ué? Você tem umas\nINSÍGNIAS que eu\vnunca vi.\fAh, já sei. Você\npegou em JOHTO.",
  ["59:43d8"] = "Eu sou o CHAIRMAN\ndo POKéMON FAN\vCLUB.\fJá criei mais de\n150 POKéMON.\fEu sou bem\nexigente quando o\vassunto é POKéMON\fVocê veio só para\nouvir sobre os\vmeus POKéMON?",
  ["59:4468"] = "Ótimo!\nEntão escute!\fBom… meu RAPIDASH\nfavorito…\fEle… fofo… lindo…\nesperto… demais…\ve… incrível… ah…\vvocê acha?…\vDemais… selvagem…\vbelo… gentil…\veu amo ele!\fAbraçar… quando…\ndorme… quentinho…\ve fofo… Ah, e…\vespetacular…\varrebatador…\vdivino…\vOpa! Olha a hora!\vPrendi você tempo\vdemais!",
  ["59:4594"] = "Obrigado por me\nouvir. Quero que\vfique com isto!",
  ["59:45c9"] = "É um RARE CANDY\nque deixa POKéMON\vmais forte.\fEu prefiro deixar\nos meus fortes\fbatalhando, então\nfique com ele.",
  ["59:4637"] = "Olá, {PLAYER}!\fVeio me ver de\nnovo para falar\vdos meus POKéMON?\fNão? Ah… eu tinha\nmais histórias…",
  ["59:468f"] = "Que decepção…\fVolte se quiser\nouvir.",
  ["59:46c4"] = "Nosso CHAIRMAN\nfala demais quando\vé sobre POKéMON…",
  ["59:46f7"] = "Eu amo o jeito\nque o CLEFAIRY\fbalança o dedo\nquando vai usar\fMETRONOME.\nÉ tão adorável!",
  ["59:4756"] = "Eu amo CLEFAIRY,\nmas nunca peguei\fum. Então me viro\ncom uma\fPOKé DOLL que eu\nachei.",
  ["59:47b1"] = "Ah, entendi. A\nmenina que perdeu\festa DOLL sofre…\fCerto. Você leva\nesta POKé DOLL\fde volta para a\ncoitadinha?\fEu ainda faço\namizade com um\fCLEFAIRY um dia.\nSem problema!",
  ["59:4861"] = "{PLAYER} recebeu\nPOKé DOLL.",
  ["59:4875"] = "Você vai ver. Eu\nvou conseguir\fum CLEFAIRY de\nverdade de amigo.",
  ["59:48af"] = "Sua BOLSA está\nlotada.",
  ["59:48ca"] = "Olha o meu querido\nBAYLEEF!\fA folha na cabeça\ndele é tão fofa!",
  ["59:4908"] = "É um CLEFAIRY!\nHã?\fAh, é mesmo. É uma\nPOKé DOLL de\vCLEFAIRY.",
  ["59:4953"] = "Vamos ouvir os\noutros treinadores\vcom educação.",
  ["59:4980"] = "Se alguém se gaba,\ngabe-se também!",
  ["59:4a17"] = "Você conhece o\nMAGNET TRAIN?\fÉ uma ferrovia\nque vai até\vGOLDENROD, JOHTO.",
  ["59:4a6d"] = "Quero ir a SAFFRON\npara ver o\vMAGNET TRAIN.",
  ["59:4ae2"] = "A TEAM ROCKET\nsumiu de KANTO.\fSó isso já me\ndeixa feliz.",
  ["59:4b21"] = "Estou pensando em\nfazer compras em\vSAFFRON.",
  ["59:4b8b"] = "Ao longo de anos,\nos DIGLETT cavaram\vum túnel enorme.\fEsse túnel vai\na uma vila longe.",
  ["59:4c99"] = "SURGE: Ei,\ngarotinho!\fTenho que admitir.\nPode não ser lá\fmuito esperto me\ndesafiar, mas\vtem coragem!\fQuando o assunto é\nPOKéMON elétrico,\vsou o número um!\fNunca perdi no\ncampo de batalha.\fVou fritar você\nigual fritei meus\vinimigos!",
  ["59:4d8a"] = "SURGE: Arrrgh!\nVocê é forte!\fCerto. A sua\nTHUNDERBADGE!",
  ["59:4dc9"] = "{PLAYER} recebeu\na THUNDERBADGE.",
  ["59:4de3"] = "SURGE: A THUNDER-\nBADGE aumenta a\vvelocidade.\fConsidere isso a\nprova de que você\fme venceu. Use com\norgulho, ouviu?",
  ["59:4e55"] = "SURGE: Ei, garoto!\nAinda dando duro\vpor aí?\fEu e meus POKéMON\ntambém estamos!",
  ["59:4ea8"] = "Veio derrotar o\nLT.SURGE?\fNão enquanto eu\nestiver aqui!",
  ["59:4ede"] = "Desculpe, falhei\ncom o LT.SURGE,\vsenhor!",
  ["59:4f02"] = "Quando eu estava\nno exército, o\fLT.SURGE salvou\na minha vida.",
  ["59:4f3a"] = "LT.SURGE viu meu\npotencial com\fPOKéMON elétri-\ncos.\fAcha que vai\nme vencer?",
  ["59:4f89"] = "Ooh, que choque!",
  ["59:4f9d"] = "Se as armadilhas\nfuncionassem,\fvocê já estaria\nfrito…",
  ["59:4fd9"] = "Vou te derrubar!\nPrepare-se para\vlevar um choque!",
  ["59:500c"] = "Gwaaah!\nFui superado…",
  ["59:5028"] = "Nada de se achar\npor me vencer.\fLT.SURGE é muito\ndurão.",
  ["59:5069"] = "Ei! Futuro\nCAMPEÃO!\fVocê deu sorte\ndesta vez.\fO LT.SURGE é muito\ncauteloso.\fTem armadilhas por\ntodo o GINÁSIO.\fMas, he-heh, as\narmadilhas não\vestão ligadas.\fVocê não vai ter\nproblema para\vchegar nele.",
  ["59:5131"] = "Ufa! Que combate\neletrizante!\fMe deixou mesmo\nnervoso.",
  ["59:5170"] = "Nada! Só tem lixo\naqui.",
  ["59:5250"] = "Bem-vindo à\nSAFFRON CITY, lar\vdo MAGNET TRAIN!\f…É o que eu diria\nnormalmente, mas\fo MAGNET TRAIN\nnão está rodando.\fEle não recebe\neletricidade\fporque tem algo\nde errado\fcom a POWER\nPLANT.",
  ["59:531d"] = "O MAGNET TRAIN\né a coisa mais\ffamosa de\nSAFFRON.",
  ["59:53bb"] = "Oi!\fO RED está fora\nfaz muito tempo.\fE também não\nligou, então eu\fnão faço ideia de\nonde ele está nem\vdo que faz.\fDizem que sem\nnotícia é sinal\fde que vai bem,\nmas eu me\vpreocupo com ele.",
  ["59:547c"] = "Fico com medo do\nRED se machucar\fou ficar doente,\nmas ele é rapaz.\fTenho orgulho de\nele fazer o que\fquer.",
  ["59:54e3"] = "Tem programas aqui\nque não passam\vem JOHTO…",
  ["59:554b"] = "{PLAYER} jogou o\nN64.\fMelhor ir andando,\nnão há tempo!",
  ["59:5582"] = "Parece que isto\nnão é usado\vfaz muito tempo…",
  ["59:562b"] = "DAISY: Oi! Meu\nirmão mais novo é\fLÍDER do GINÁSIO\nde VIRIDIAN CITY.\fMas ele sai da\ncidade tanto,\fque causa problema\npara o treinador.",
  ["59:56b1"] = "DAISY: Oi! Chegou\nna hora. Eu ia\vtomar um chá.\fVocê quer me\nacompanhar?\fAh, seus POKéMON\nestão meio sujos.\fVocê quer que eu\nescove um?",
  ["59:573f"] = "DAISY: Qual deles\neu devo escovar?",
  ["59:5761"] = "DAISY: Certo, vou\ndeixar ele bonito\vnum instante.",
  ["59:5791"] = "{STRBUF} parece\nsatisfeito.",
  ["59:57a5"] = "DAISY: Aí está!\nTudo pronto.\fViu? Não ficou\nbonito, né?\fÉ um POKéMON\nmuito fofo.",
  ["59:57f5"] = "DAISY: Eu sempre\ntomo chá\fa esta hora. Venha\nme acompanhar.",
  ["59:582f"] = "DAISY: Não quer\nescovar nenhum?\fCerto, vamos só\ntomar chá então.",
  ["59:5872"] = "DAISY: Foi mal.\nEu não consigo\vescovar um EGG.",
  ["59:5922"] = "OAK: Ah, {PLAYER}!\nQue bom que você\fveio de tão longe\naté KANTO.\fO que você acha\ndos treinadores\fdaqui?\nBem durões, né?",
  ["59:599d"] = "Como vai a sua\nPOKéDEX?\fVamos ver…",
  ["59:59c3"] = "Se estiver por\nperto, espero que\vvolte a visitar.",
  ["59:5b9d"] = "OAK: Hum? Você não\nestá juntando as\vINSÍGNIAS daqui?\fOs LÍDERES daqui\nsão tão fortes\fquanto os que você\nvenceu em JOHTO.\fEu recomendo que\nvocê desafie\veles.",
  ["59:5c37"] = "OAK: Ah, você está\njuntando as\vINSÍGNIAS daqui.\fImagino que seja\ndifícil, mas a\fexperiência vai\najudar você.\fVenha me ver\ncom todas elas.\fTenho um presente\npara você.\fContinue firme,\n{PLAYER}!",
  ["59:5cf6"] = "O programa POKéMON\nTALK do PROF\fnão passa aqui\nem KANTO.\fÉ uma pena, eu\nqueria ouvir.",
  ["59:5d54"] = "Graças ao seu\ntrabalho na POKé-\vDEX, a pesquisa\fdo PROF está indo\nmuito bem.",
  ["59:5da2"] = "Não conte a\nninguém, mas o\fPOKéMON TALK não é\nao vivo.",
  ["59:5de5"] = "Aperte START para\nabrir o MENU.",
  ["59:5e04"] = "A opção SAVE está\nno MENU.\fUse de tempos em\ntempos.",
  ["59:5e40"] = "Não tem nada aqui\ndentro…",
  ["59:5e59"] = "Tem uma mensagem\nde e-mail no PC.\f…\fPROF.OAK, como vai\na sua pesquisa?\vTudo indo bem?\fEu continuo\nbatalhando.\fOuvi rumores de\nque {PLAYER} está\fficando bem\nconhecido por aí.\fFico muito feliz\nde saber disso.\fELM, de NEW BARK\nTOWN 8-)",
  ["5a:400f"] = "NIDORAN, pata!",
  ["5a:40cb"] = "BROCK: É raro\nreceber desafio\fde treinador\nvindo de JOHTO.\fEu sou o BROCK,\nLÍDER de PEWTER.\fSou especialista\nem POKéMON pedra.\fMeus POKéMON são\nimunes à maioria\fdos ataques\nfísicos. Vai ser\fdifícil causar\nalgum dano.\fVenha!",
  ["5a:41b6"] = "BROCK: Os ataques\nfortes do seu\vPOKéMON venceram\vminha defesa…\fVocê é mais forte\ndo que eu pensava\fVá em frente,\nleve a INSÍGNIA.",
  ["5a:4238"] = "{PLAYER} recebeu\na BOULDERBADGE.",
  ["5a:4252"] = "BROCK: {PLAYER},\nobrigado. Gostei\fde batalhar com\nvocê, mesmo\vmeio chateado.\fEssa BOULDERBADGE\nvai deixar seus\fPOKéMON ainda\nmais fortes.",
  ["5a:42d5"] = "BROCK: O mundo é\nenorme. Ainda tem\fmuitos treinadores\nfortes como você.\fEspere para ver.\nEu também vou\vficar bem mais\vforte.",
  ["5a:435d"] = "Os treinadores\ndeste GINÁSIO\vusam POKéMON de\fpedra. O tipo\npedra tem DEFESA\falta. As batalhas\npodem demorar\fbastante. Você\nestá preparado?",
  ["5a:43ec"] = "Preciso vencer\nessas batalhas…",
  ["5a:440a"] = "Ei, você! Treina-\ndor de JOHTO!\fBROCK é durão.\nVai te punir se\fvocê não o levar\na sério.",
  ["5a:4469"] = "Ei! Futuro\nCAMPEÃO!\fVocê está indo bem\nEstá enfrentando\fos LÍDERES de\nGINÁSIO de KANTO?\fSão gente forte e\ndedicada,\figual aos LÍDERES\nde JOHTO.",
  ["5a:4502"] = "Ei! Futuro\nCAMPEÃO!\fO GINÁSIO não te\ndeu trabalho.\fO jeito que você\nassumiu o comando\ffoi inspirador.\nFalo sério.",
  ["5a:45d3"] = "Oi! Olha o meu\nGYARADOS!\fCriei ele desde\nMAGIKARP. Não dá\fpara acreditar em\ncomo ficou forte.",
  ["5a:4635"] = "Teve um velho\nestranho que\vvendia MAGIKARP.\fEle dizia que os\nMAGIKARP do\fLAKE OF RAGE eram\nexcelentes.",
  ["5a:46fc"] = "…É, e o GINÁSIO\nde CINNABAR\fsumiu. Eu fiquei\nespantado.\f…Sim? Estou no\ntelefone. Sai!",
  ["5a:4770"] = "Quase todo POKéMON\nfica com sono\fse ouve um\nJIGGLYPUFF cantar\fTem vários golpes\nque só dá para\fusar enquanto o\nPOKéMON dorme.",
  ["5a:485a"] = "Gosto de cochilar\ncom o rádio ligado\v…Zzzz…",
  ["5a:4a24"] = "Na POKéMON LEAGUE\nvocê vai ser\ftestado pelos\nELITE FOUR.\fTem que vencer\ntodos eles. Se\fperder, começa\ntudo de novo!",
  ["5a:4aa1"] = "Espere aí.\fVocê vai encarar\no desafio da\fPOKéMON LEAGUE\nagora?\fIsso não vai\nacontecer.\fMeus POKéMON super\nbem treinados\fvão acabar com\nvocê.\f{PLAYER}!\nEu te desafio!",
  ["5a:4b50"] = "…Droga… Eu ainda\nnão consigo…\fEu… eu preciso\npensar mais nos\vmeus POKéMON…\fHumpf! Tente não\nperder!",
  ["5a:4ba9"] = "…\fUfa…\nCom meus amigos,\feu vou ser o\nCAMPEÃO!",
  ["5a:4be1"] = "Ah! Você vai\ndesafiar os ELITE\fFOUR? Tem certeza\nque está pronto?\fSe precisar\ntreinar mais,\fmeu ABRA pode\najudar você.\fEle pode TELEPORT\nvocê para casa.\fVocê quer ir\npara casa agora?",
  ["5a:4c93"] = "Certo, certo.\nImagine a sua casa\vna cabeça…",
  ["5a:4cbd"] = "Certo, certo.\nBoa sorte!",
  ["5a:4ddd"] = "{PLAYER}, bem-vindo\nà POKéMON LEAGUE.\fDeixe eu me\napresentar. Eu sou\vo WILL.\fEu treinei no\nmundo inteiro,\fdeixando meus\npsíquicos fortes.\fE, enfim, eu fui\naceito nos\vELITE FOUR.\fEu só posso ficar\ncada vez melhor!\fPerder não é uma\nopção!",
  ["5a:4ed8"] = "Eu… eu não…\nacredito nisso…",
  ["5a:4ef0"] = "Mesmo derrotado,\neu não vou mudar\vo meu caminho.\fVou continuar\nbatalhando até\festar acima de\ntodo treinador!\fAgora, {PLAYER},\nsiga em frente e\fsinta a fúria\ndos ELITE FOUR.",
  ["5a:503f"] = "Fuahahahaha!\fEu sou KOGA, dos\nELITE FOUR.\fEu vivo nas\nsombras, ninja!\fMeu estilo é\nintrincado e vai\vdestruir você!\fConfusão, sono,\nveneno…\fPrepare-se para\nser vítima da\vminha técnica!\fFuahahahaha!\fPOKéMON não é só\nforça bruta,\fvocê vai ver isso\nlogo, logo!",
  ["5a:5155"] = "Ah!\nVocê provou o seu\vvalor!",
  ["5a:5176"] = "Eu joguei em você\ntudo o que eu\vconsegui reunir.\fMas meu esforço\nfalhou. Preciso\vafiar minha arte.\fVá para a próxima\nsala e ponha suas\vforças à prova!",
  ["5a:52aa"] = "Eu sou BRUNO, dos\nELITE FOUR.\fEu sempre treino\nao extremo porque\veu acredito no\vnosso potencial.\fFoi assim que a\ngente ficou forte\fVocê aguenta o\nnosso poder?\fHum? Não vejo medo\nem você. Parece\fdeterminado.\nPerfeito!\fPronto, {PLAYER}?\nVai se curvar\fao nosso poder\nesmagador!\fRuu ha!",
  ["5a:53cf"] = "Por quê? Como a\ngente perdeu?",
  ["5a:53e8"] = "Tendo perdido, eu\nnão tenho direito\vde dizer nada…\fVá encarar o seu\npróximo desafio!",
  ["5a:54d3"] = "Eu sou KAREN, dos\nELITE FOUR.\fVocê é {PLAYER}?\nQue divertido.\fEu amo POKéMON\ndo tipo sombrio.\fAcho a imagem\nselvagem e dura\fdeles atraente. E\neles são fortes.\fAcha que dá conta\ndeles? Só tente\vme entreter.\fVamos lá.",
  ["5a:55a4"] = "Bom, você é bom\nmesmo. Gosto disso\vnum treinador.",
  ["5a:55d5"] = "POKéMON forte.\fPOKéMON fraco.\fIsso é só a\npercepção egoísta\vdas pessoas.\fTreinador de\nverdade tenta\fvencer com os\nseus favoritos.\fGosto do seu\nestilo. Você\ventende.\fVá em frente, o\nCAMPEÃO espera.",
  ["5a:5816"] = "LANCE: Eu estava\nesperando você.\f{PLAYER}!\fEu sabia que você,\ncom seu talento,\fia acabar\nchegando até mim.\fNão é hora de\npalavras agora.\fVamos batalhar\npara decidir quem\fé o mais forte\nde nós dois.\fComo o treinador\nmais poderoso e\fcomo CAMPEÃO da\nPOKéMON LEAGUE…\fEu, LANCE, mestre\ndos dragões,\vaceito o desafio!",
  ["5a:5953"] = "…Acabou.\fMas é uma sensação\nestranha.\fNão estou bravo\npor ter perdido.\vEstou feliz.\fFeliz por ter\nvisto nascer\fum grande novo\nCAMPEÃO!",
  ["5a:59e1"] = "…Ufa.\fVocê ficou mesmo\npoderoso,\v{PLAYER}.\fSeus POKéMON\nresponderam ao\fjeito forte e\níntegro.\fComo treinador,\nvocê vai crescer\fjunto com os seus\nPOKéMON.",
  ["5a:5a8c"] = "MARY: Ah, não!\nAcabou tudo!\fPROF.OAK, se você\nnão demorasse…",
  ["5a:5aca"] = "PROF.OAK: Ah,\n{PLAYER}!\fFaz muito tempo\nque não te vejo.\fVocê está mesmo\nmais maduro.\fA sua conquista\nda LEAGUE é\vfantástica!\fSua dedicação,\nconfiança e amor\fpelos seus POKéMON\nfizeram isso.\fSeus POKéMON foram\nnotáveis também.\fPorque acreditaram\nem você como\ftreinador, eles\nperseveraram.\fParabéns,\n{PLAYER}!",
  ["5a:5bf6"] = "MARY: Vamos\nentrevistar o novo\vCAMPEÃO!",
  ["5a:5c26"] = "LANCE: Isto está\nficando barulhento\vdemais…\f{PLAYER}, pode\nvir comigo?",
  ["5a:5c70"] = "MARY: Ah, espere!\nA gente não fez\va entrevista!",
  ["5a:5d51"] = "LANCE: Faz muito\ntempo que eu não\vvenho aqui.\fÉ aqui que a gente\nhonra os CAMPEÕES\fda LEAGUE por toda\na eternidade.\fOs POKéMON\ncorajosos deles\vtambém entram.\fHoje, aqui, a\ngente viu surgir\fum novo CAMPEÃO\nda LEAGUE, um\ftreinador que tem\ncompaixão e\fconfiança nos\nseus POKéMON.\fUm treinador que\nvenceu por meio\fda perseverança e\nda determinação.\fO novo CAMPEÃO da\nLEAGUE, que tem\ftudo para ser\num grande!\f{PLAYER}, deixe eu\nregistrar você\fe seus parceiros\ncomo CAMPEÕES!",
  ["5b:41b3"] = "Vamos partir logo.\nPor favor, suba\va bordo.",
  ["5b:41de"] = "Desculpe. Não dá\npara embarcar.",
  ["5b:41fa"] = "Bem-vindo ao FAST\nSHIP S.S.AQUA.\fVai embarcar\nhoje?",
  ["5b:4238"] = "Posso ver o seu\nS.S.TICKET?",
  ["5b:4259"] = "Esperamos ver você\nde novo!",
  ["5b:4274"] = "{PLAYER} mostrou\no S.S.TICKET.\fÉ isso.\nObrigado!",
  ["5b:42a9"] = "{PLAYER} tentou\nmostrar o S.S.\vTICKET…\f…Mas não tem!\fDesculpe!\nSó pode embarcar\fquem tiver um\nS.S.TICKET.",
  ["5b:4336"] = "O FAST SHIP zarpa\nna sexta que vem.",
  ["5b:435c"] = "SHELLDER é fácil\nde pegar aqui.\fEm outros lugares\né meio raro.",
  ["5b:439d"] = "Quantas RODS você\ntem?\fRODS diferentes\npegam POKéMON\vdiferentes.",
  ["5b:43de"] = "O S.S.AQUA usa\njatos e desliza\vsobre as ondas!",
  ["5b:440a"] = "Tem um monte de\nPOKéMON em KANTO.\fQueria poder ir…",
  ["5b:443f"] = "Não queremos que\nvocê caia no mar,\fentão não pode\nentrar.",
  ["5b:466e"] = "Vamos partir logo.\nPor favor, suba\va bordo.",
  ["5b:4699"] = "Desculpe. Não dá\npara embarcar.",
  ["5b:46b5"] = "Bem-vindo ao FAST\nSHIP S.S.AQUA.\fVai embarcar\nhoje?",
  ["5b:46f3"] = "Posso ver o seu\nS.S.TICKET?",
  ["5b:4714"] = "Esperamos ver você\nde novo!",
  ["5b:472f"] = "{PLAYER} mostrou\no S.S.TICKET.\fÉ isso.\nObrigado!",
  ["5b:4764"] = "{PLAYER} tentou\nmostrar o S.S.\vTICKET…\f…Mas não tem!\fDesculpe!\nSó pode embarcar\fquem tiver um\nS.S.TICKET.",
  ["5b:47cb"] = "O FAST SHIP zarpa\nna quarta-feira.",
  ["5b:47f2"] = "O FAST SHIP zarpa\ndomingo que vem.",
  ["5b:4818"] = "Você veio de\nJOHTO?\fDizem que muitos\nPOKéMON raros\vvivem lá.",
  ["5b:49ad"] = "O FAST SHIP S.S.\nAQUA segue para\vVERMILION CITY.\fVamos anunciar\nassim que a gente\vchegar.",
  ["5b:4a0d"] = "O FAST SHIP S.S.\nAQUA segue para\vOLIVINE CITY.\fVamos anunciar\nassim que a gente\vchegar.",
  ["5b:4a6b"] = "É a sua cabine.\fSe seus POKéMON\nestão machucados,\vdurma na cama.\fIsso vai curar\neles.",
  ["5b:4ac1"] = "É a sua cabine.\fVocê pode curar\nseus POKéMON\vdormindo na cama.\fO navio chega\nenquanto você\vestá dormindo.",
  ["5b:4b32"] = "Todo passageiro\naqui é treinador.\fEstão todos loucos\npara batalhar nas\vcabines.",
  ["5b:4c00"] = "e!",
  ["5b:4c04"] = "O FAST SHIP S.S.\nAQUA chegou em\vOLIVINE CITY.",
  ["5b:4c35"] = "O FAST SHIP S.S.\nAQUA chegou em\vVERMILION CITY.",
  ["5b:4de0"] = "Eu queria ganhar!",
  ["5b:4df2"] = "Treinadores de\nJOHTO podem lutar\fcom os LÍDERES de\nKANTO.",
  ["5b:4e2a"] = "Estou treinando\npara ser CAMPEÃO",
  ["5b:4e4c"] = "Qual é a diferença\nentre nós dois?",
  ["5b:4e6e"] = "Um dia eu venço\nvocê!",
  ["5b:4e8d"] = "Você conhece a\nLILY? Ela é uma\vDJ de KANTO.",
  ["5b:4ec2"] = "A LILY é legal,\nmas a MARY é a\fmelhor!\nQuero conhecer as\vrádios de JOHTO!",
  ["5b:4f0e"] = "Está sozinho?\nEntão vamos lutar",
  ["5b:4f30"] = "Isso é demais\npara mim!",
  ["5b:4f4b"] = "Será que tem\nalguma montanha\fboa para escalar\nem KANTO?",
  ["5b:4f89"] = "É, eu sou\nmarinheiro sim.\fEu não estava\nvadiando!\fEsta cabine estava\nvazia, então eu só\vtirei um cochilo!\fAh, deixa para lá!\nVamos batalhar!",
  ["5b:500e"] = "Desculpe! A culpa\né toda minha!",
  ["5b:5028"] = "Ser marinheiro é\ntrabalho pesado.\vServiço braçal.\vÉ exaustivo!",
  ["5b:5068"] = "Ah, não. Perdi uma\ncoisa que é muito\vimportante.",
  ["5b:509a"] = "Eu… não consigo\nachar…",
  ["5b:50ae"] = "Desisto. Filho,\nvocê não precisa\fprocurar. Esqueça\nisso!",
  ["5b:50fc"] = "Que azar!\nEu perdi!",
  ["5b:5112"] = "Achei uma moeda\nbonita aqui.\fAlguém deve ter\nperdido…",
  ["5b:52a4"] = "Fsss… A chama\nestá fraquinha…",
  ["5b:52be"] = "Acho que o fogo é\nfraco no mar.\fNão faz diferença?\nSério?",
  ["5b:52fa"] = "Vou visitar minha\nvovó para pegar\vuns insetos!",
  ["5b:5329"] = "Ooh, uau. Você é\ndurão, cara!",
  ["5b:5347"] = "Dá para achar um\nmonte de POKéMON\vnas árvores!",
  ["5b:5379"] = "Estou tentando\nesquecer as mágoas\vVamos batalhar!",
  ["5b:53a4"] = "Meu peito chora…",
  ["5b:53b5"] = "Uma viagem é o\nmelhor remédio\vpara um coração\fpartido.\nMas a viagem de\vFAST SHIP é curta",
  ["5b:5418"] = "Vou fazer um teste\ncom as minhas\fmúsicas na RADIO\nSTATION.",
  ["5b:5456"] = "Uau!\nDistorção total!",
  ["5b:5470"] = "Falando na RADIO\nSTATION,\fqual é o número da\nsorte da semana?",
  ["5b:54af"] = "Uma cama macia!\nHora de dormir…",
  ["5b:54cc"] = "Ah, descansado e\nrenovado!",
  ["5b:54e9"] = "O FAST SHIP S.S.\nAQUA chegou em\vOLIVINE CITY.",
  ["5b:551a"] = "O FAST SHIP S.S.\nAQUA chegou em\vVERMILION CITY.",
  ["5b:570e"] = "Ufa! Obrigado por\nter vindo junto.\fEntreter aquela\nmenininha foi\vexaustivo.",
  ["5b:5760"] = "Gostou da viagem\nno S.S.AQUA?\fEle quase patina\npor cima das\vondas.",
  ["5b:57aa"] = "Olá, filho…\nNão acho a minha\vneta.\fSe ela está no\nnavio, tudo bem.\fMas e se ela caiu\nno mar?\fEla é uma criança\nelétrica, então\fpode amolar alguém\nEstou aflito…",
  ["5b:585a"] = "{PLAYER}, né? Ouvi\nque você brincou\vcom a minha\vneta.\fQuero agradecer\npor isso.",
  ["5b:58b2"] = "Já sei! Quero que\nfique com isto!",
  ["5b:58d5"] = "Estamos viajando\npelo mundo todo.",
  ["5b:58f7"] = "CAPTAIN, brinca um\npouco comigo?\fEstou entediado!\nQuero brincar!",
  ["5b:5936"] = "Oi! Você brinca\ncomigo?\f…Oh!\fO vovô está\npreocupado?\fTenho que ir!\fPreciso achar o\nvovô!",
  ["5b:599b"] = "Vovô, estou aqui!\nEu brincava\fcom o CAPTAIN e\ncom este moço!",
  ["5b:59dd"] = "Me diverti muito\nbrincando!",
  ["5b:59f9"] = "Ei, filho! Quer\nbatalhar comigo?",
  ["5b:5a2b"] = "Você viaja\nsozinho?\fSua mãe não fica\npreocupada?",
  ["5b:5a5e"] = "Você acha que eu\nsou bebê?\vIsso não é justo!",
  ["5b:5a92"] = "Bebê é um jeito\ngrosso de chamar\vnós, meninas!",
  ["5b:5ab9"] = "Eu não sou bebê!\fNão é bonito falar\nassim com a dama!",
  ["5b:5af8"] = "Às vezes crianças\nsão mais espertas\vque adultos!",
  ["5b:5b25"] = "Psiu! Meu cérebro\nestá captando\vsinais de rádio!",
  ["5b:5b51"] = "…Estou ouvindo\nalguma coisa!",
  ["5b:5b67"] = "Entendi. Dá para\nouvir a rádio de\vJOHTO no navio.",
  ["5b:5b9e"] = "O que você acha?\nMeus POKéMON são\vlindos, não são?",
  ["5b:5bce"] = "Ah, não! Meus\nlindos POKéMON!",
  ["5b:5bec"] = "Preciso ir ao\nPOKéMON SALON e\vdeixá-los lindos!",
  ["5b:5c1f"] = "Vou fazer compras\nna DEPT.STORE e\vdepois…",
  ["5b:5c4d"] = "O que eu ia\nfazer mesmo?",
  ["5b:5c66"] = "Ah, sim! Tenho que\nbuscar meu POKéMON\vno DAY-CARE!",
  ["5b:5c97"] = "Que tipos de POKé\nBALLS você tem\vcom você?",
  ["5b:5cc4"] = "Espera! Para! Não!\nPor favor!",
  ["5b:5cdf"] = "Você devia usar a\nBALL certa para\vcada situação.",
  ["5b:5d15"] = "O FAST SHIP S.S.\nAQUA chegou em\vVERMILION CITY.",
  ["5b:5f4b"] = "Ei, moço. Dá para\nvocê procurar o\vmeu colega?\fEle está vadiando\npor aí, aquele\vpreguiçoso!\fEu queria ir atrás\ndele, mas estou\vde serviço.",
  ["5b:5fd7"] = "Ai, caramba…\fO CAPTAIN vai\nficar furioso…",
  ["5b:5ffe"] = "Valeu, moço!\nDei uma bronca\fboa nele, para\nparar de vadiar!",
  ["5b:603d"] = "Uma menininha?\fAcho que vi ela\npassar por aqui.",
  ["5b:606d"] = "O refeitório é\nlogo à frente.\fA escada no fim\nleva à cabine do\vCAPTAIN.",
  ["5b:60bd"] = "Nada melhor que\numa batalha na\vminha folga.",
  ["5b:60ea"] = "Ganhando ou não,\na folga acabou!",
  ["5b:6108"] = "Acho que não dá\npara ganhar se eu\vnão levar a sério",
  ["5b:6133"] = "Estou entediado.\nQuer batalhar?",
  ["5b:6151"] = "Uau! Você é forte\ndemais!",
  ["5b:6169"] = "SAFFRON, CELADON…\nOuvi que tem\fmuitas cidades\ngrandes em KANTO.",
  ["5b:61a7"] = "Urrf…\nEstou enjoado!",
  ["5b:61ba"] = "Não consigo mais\nme mexer…",
  ["5b:61d2"] = "Chega de navio\npara mim. Da\fpróxima vez eu vou\nde MAGNET TRAIN.",
  ["5b:6210"] = "É aqui que os\nmarinheiros ralam",
  ["5b:6230"] = "Perdi no meu\npróprio campo…",
  ["5b:624a"] = "Recebemos passa-\ngeiros diferentes\fde VERMILION CITY\na OLIVINE CITY.",
  ["5b:628c"] = "Mesmo estando no\nmar, eu não posso\vpescar!\fQue tédio!\nVamos batalhar!",
  ["5b:62d8"] = "Eu… já não estou\nentediado…",
  ["5b:62f2"] = "Pretendo pescar no\npíer de VERMILION",
  ["5b:6317"] = "Estou fortalecendo\nas pernas firmes\fcontra o balanço\ndo navio!",
  ["5b:6355"] = "Balancei e\ncapotei!",
  ["5b:636e"] = "Não consegui achar\no KARATE KING em\vJOHTO.\fDizem que ele\ntreina em alguma\vcaverna por aí.",
  ["5b:63c9"] = "Sou marinheiro!\fMas estou criando\nPOKéMON para virar\vo CAMPEÃO!",
  ["5b:640c"] = "Minha falta de\ntreino é clara…",
  ["5b:642f"] = "Oito BADGES!\nElas provam que\fvocê venceu os\nLÍDERES.\fNão é à toa que\nvocê é tão bom!",
  ["5b:6486"] = "Não encoste um\ndedo nos alunos!",
  ["5b:64b1"] = "Estamos em excur-\nsão nas RUÍNAS\vperto de VIOLET.",
  ["5b:64e4"] = "Você conhece as\nRUÍNAS DE ALPH?",
  ["5b:650d"] = "Os rádios captam\nsinais estranhos\vnas RUÍNAS.",
  ["5b:653f"] = "Há painéis\nesquisitos nas\vRUÍNAS DE ALPH.",
  ["5b:6586"] = "Li que existem\nquatro painéis de\vpedra.",
  ["5b:667f"] = "O FAST SHIP S.S.\nAQUA vai a KANTO\fàs segundas e\nsextas.",
  ["5b:66ed"] = "O FAST SHIP zarpa\nàs quartas e aos\vdomingos, toda\vsemana.",
  ["5b:680b"] = "MT.MOON SQUARE\nNão jogue lixo",
  ["5b:6882"] = "Quando o sol se\npõe, os CLEFAIRY\vvêm brincar.",
  ["5b:845a"] = "estinguirá\nnossa verdadeira\vLÍDER?",
  ["5b:9100"] = "Antes de conectar\nvocê deve salvar\vo seu jogo.",
  ["5b:9600"] = "99x\v{STRBUF}esculpe-me, a\nCÁPSULA DO TEMPO\vnão está ativada.",
  ["5b:a453"] = "és dele\npara chegar à\vUSINA DE ENERGIA.",
  ["5b:c45c"] = " REPELENTE é\nnecessário se você\vfor explorar uma\vcaverna.\fEmbora eu goste de\nexplorar, eu ainda\vnão fiz isso em\vtodas cavernas.",
  ["5b:ce5b"] = "tão? Eu sei que\nestou com razão.",
  ["5b:d200"] = "ficar com ele.\fMas me prometa\nque será bom com\vele!",
  ["5b:d700"] = "um\nlaço forte com\vseu POKéMON\vtambém!",
  ["5b:e04d"] = "Eu acho que a vi\nindo por aqui.",
  ["5c:400f"] = "Eu queria comprar\nlembranças da\fSAFARI ZONE, mas\nestá fechada…",
  ["5c:4050"] = "A neta do WARDEN\nda SAFARI ZONE\vmora aqui\vna cidade.",
  ["5c:424f"] = "Fufufufu…\fSinto muito\ndesapontar você…\fÉ só brincadeira!\fEu sou a real!\fJANINE, do GINÁSIO\nde FUCHSIA!",
  ["5c:42bb"] = "JANINE: Você é\ndurão. Venceu\vcom certeza…\fAqui, a SOULBADGE.\nPegue.",
  ["5c:4305"] = "{PLAYER} recebeu\na SOULBADGE.",
  ["5c:431c"] = "JANINE: Você é\nmuito forte! Tenho\vum presente!\fÉ TOXIC, um veneno\npoderoso que\fvai comendo os PS\nda vítima.",
  ["5c:438e"] = "JANINE: Eu vou\nme dedicar mesmo\fe melhorar as\nminhas técnicas.\fQuero ficar melhor\nque o meu pai\ve que você!",
  ["5c:4400"] = "Fufufu!\fEu sou a JANINE,\na LÍDER!\fNão, não sou!\nCaiu, otário!",
  ["5c:4440"] = "Eu te enganei…",
  ["5c:4453"] = "Como você vai\ndescobrir quem é\va LÍDER real?",
  ["5c:4480"] = "Te enganei!\nHahaha!",
  ["5c:4495"] = "Ooh… Eu perdi…\nVocê não é fraco…",
  ["5c:44d5"] = "Eu sou a JANINE!\fComo você soube\nque eu era real?\fVamos batalhar!",
  ["5c:450b"] = "Droga!\nEu queria ganhar!",
  ["5c:4526"] = "Você deve estar\nficando cansado.",
  ["5c:4542"] = "Uahahaha!\fPode crer, cara.\nEu sou a JANINE!",
  ["5c:456a"] = "Meu disfarce era\nperfeito! Droga!",
  ["5c:458b"] = "Ei, cara. Meu\ndisfarce era fofo\vou não era, hein?",
  ["5c:45ba"] = "Ei, futuro\nCAMPEÃO!\fOpa! Dê uma boa\nolhada em volta.\fOs treinadores são\ntodos iguais à\vLÍDER, a JANINE.\fQual deles é a\nJANINE real?",
  ["5c:4646"] = "Foi uma batalha\ne tanto, treinador\vde JOHTO!",
  ["5c:46e4"] = "Meu avô está na\ncasa do meu irmão\vBILL, no CERULEAN",
  ["5c:471a"] = "Eu vi uns POKéMON\nestranhos e lentos\vna CYCLING ROAD.",
  ["5c:47b5"] = "Ei! Você tem uma\nPOKéDEX de um tipo\vnovo em folha.\fFoi o PROF.OAK que\nte deu?",
  ["5c:47fd"] = "Levei um susto\nno GINÁSIO.\fTinha um monte de\nmeninas que eram\vtodas iguais.",
  ["5c:484f"] = "Eu sou a JANINE!\nAbracadabra… Puf!",
  ["5c:486f"] = "Viu? Agora eu sou\nigualzinha a ela!",
  ["5c:4907"] = "Meu avô é o\nWARDEN da\vSAFARI ZONE.\fOu era…\fEle resolveu tirar\nférias e\ffoi para fora\ndo país sozinho.\fLargou a SAFARI\nZONE assim,\vdo nada.",
  ["5c:49b2"] = "Muita gente ficou\ndecepcionada\fcom a SAFARI ZONE\nfechada, mas o vô\vé teimoso demais…",
  ["5c:4a0b"] = "É a foto de um\nvelho sorridente\fcercado de\nPOKéMON.",
  ["5c:4a47"] = "É a foto de uma\nplanície enorme\fcom POKéMON raros\nbrincando nela.",
  ["5c:4ac2"] = "Você está fazendo\numa POKéDEX?\fIsso é e tanto.\nNão desista!",
  ["5c:4b31"] = "Quem busca poder\nsobe o MT.\fSILVER, apesar dos\nmuitos perigos…\fCom os POKéMON de\nconfiança, devem\fsentir que podem\nir onde quiserem…",
  ["5c:4c13"] = "Ai, meu Deus.\nVocê me achou.\fPor favor, não\nconte a ninguém.\fEu te dou isto\npara guardar o\vsegredo. Sim?",
  ["5c:4c81"] = "É duro ser uma\ncelebridade.\fOnde quer que eu\nvá, me perseguem.\fEu só queria\nficar em paz…",
  ["5c:4fa4"] = "Bem-vindo ao CABLE\nCLUB COLOSSEUM.\fAqui você batalha\ncom um amigo.\fVocê quer\nbatalhar?",
  ["5c:4ffe"] = "Bem-vindo ao CABLE\nCLUB TRADE CENTER\fAqui você troca\nos seus POKéMON\vcom um amigo.\fVocê quer\ntrocar?",
  ["5c:5068"] = "Bem-vindo ao CABLE\nCLUB TIME CAPSULE\fDá para viajar ao\npassado e trocar\vos seus POKéMON.\fVocê quer trocar\ncom o passado?",
  ["5c:50e2"] = "O seu amigo não\nestá pronto.",
  ["5c:50fd"] = "Antes de abrir a\nconexão, você tem\vque salvar.",
  ["5c:5130"] = "Aguarde um pouco.",
  ["5c:513e"] = "A conexão foi\nfechada por falta\vde atividade.\fFale com o seu\namigo e volte\voutra hora.",
  ["5c:51f2"] = "Não dá para ligar\nao passado aqui.",
  ["5c:5213"] = "Seu amigo escolheu\noutra sala.",
  ["5c:5238"] = "Pode entrar.",
  ["5c:5258"] = "{STRBUF} não\npode ser levado.",
  ["5c:5275"] = "Não dá para levar\no {STRBUF} com\vum {STRBUF}.",
  ["5c:529c"] = "Não dá para levar\no {STRBUF} que\vestá com MAIL.",
  ["5c:52cd"] = "Sinto muito, a\nTIME CAPSULE está\vem ajuste.",
  ["5c:52fc"] = "Sinto muito, a\nTRADE MACHINE está\vem ajuste.",
  ["5c:532c"] = "Sinto muito, a\nBATTLE MACHINE\vestá em ajuste.",
  ["5c:535d"] = "Olá! Você é o\n{PLAYER}, né?\fEu tenho uma\ncoisa para você.",
  ["5c:5391"] = "Aqui está!",
  ["5c:539f"] = "Esperamos atender\nvocê de novo.",
  ["5c:53bc"] = "Ah, você não tem\nespaço para isto.\fPasse em qualquer\nCENTRO POKéMON\fdo país para\npegar depois.",
  ["5c:541a"] = "Não? Isso é bem\nestranho…",
  ["5c:553d"] = "O seu amigo\nestá pronto.",
  ["5c:55be"] = "O seu amigo\nestá pronto.",
  ["5d:401f"] = "Ao norte de\nLAVENDER fica o\fROCK TUNNEL. Vá\npor ele até a\vPOWER PLANT.",
  ["5d:4072"] = "Tem um programa\nde rádio que toca\va POKé FLUTE.\fAh? Seu rádio\nprecisa do EXPN\vCARD para pegar.",
  ["5d:40db"] = "A RADIO STATION\nnão pode ir ao ar\fporque a POWER\nPLANT parou.",
  ["5d:411e"] = "O DIRECTOR da\nRADIO STATION\vficou bem feliz.\fEle disse que\nvoltaram ao ar\fporque a POWER\nPLANT está\vrodando de novo.",
  ["5d:4222"] = "O MR.FUJI mora\naqui, mas não\festá em casa.\fEle deve estar na\nSOUL HOUSE.",
  ["5d:4271"] = "Tem gente de\ncoração frio que\vlarga o POKéMON.\fO vô acolhe os\ncoitados sem lar\fe cuida deles com\ncarinho.",
  ["5d:437e"] = "LAVENDER é uma\nvila pequena e\fquieta, no pé da\nmontanha.\fFicou um pouco\nmais movimentada\fdesde que a RADIO\nTOWER foi feita.",
  ["5d:445a"] = "REPEL é coisa\nnecessária se\fvai explorar uma\ncaverna.\fMesmo gostando de\nexplorar, ainda\fnão fui a todas\nas cavernas.",
  ["5d:44dd"] = "Ouvi falar de um\nartesão que\ffaz POKé BALLS sob\nmedida na cidade\fde AZALEA, em\nJOHTO. Eu queria.",
  ["5d:4586"] = "MR.FUJI: Olá.\fHum… Parece que\nvocê cria os seus\fPOKéMON com amor\ne bondade.\fQuem ama POKéMON\nvem aqui prestar\frespeito aos que\njá se foram.\fDeixe as suas\ncondolências\fpara as almas dos\nPOKéMON que foram\fTenho certeza que\nisso os alegra.",
  ["5d:4680"] = "Tem outros túmulos\nde POKéMON aqui,\veu acho.\fTem muitas salas\nem que só o\vMR.FUJI entra.",
  ["5d:46e4"] = "Eu vim com a minha\nmãe ver túmulos\vde POKéMON…",
  ["5d:470e"] = "Os POKéMON que\nviviam comigo…\fEu amava eles como\nmeus netos…",
  ["5d:47f2"] = "Bem-vindo!\nFique à vontade\fpara olhar tudo\nneste andar.",
  ["5d:482d"] = "Desculpe, mas você\nsó pode visitar\vo térreo.\fDesde que a RADIO\nTOWER de JOHTO\ffoi tomada por uma\ngangue, a gente\fteve que reforçar\na segurança.",
  ["5d:48c3"] = "Muita gente aqui\ntrabalha duro\fna RADIO\nTOWER.\fDevem estar dando\no melhor para\vbons programas.",
  ["5d:492e"] = "Ah, não, não!\fA gente está fora\ndo ar desde que a\fPOWER PLANT\nparou.\fTodo o esforço de\nabrir esta rádio\fvira pó se eu\nnão for ao ar.\fEstou arruinado!",
  ["5d:49d4"] = "Ah! Então você é\no {PLAYER} que\fresolveu o caso\nda POWER PLANT?\fGraças a você, eu\nnão fui demitido.\fSério, você é um\nsalva-vidas!\fPor favor, aceite\nisto de presente.",
  ["5d:4a74"] = "Com essa coisa,\nvocê pega\fos programas de\nrádio de KANTO.\fGahahahaha!",
  ["5d:4ac6"] = "Olá, camarada!\fEu sou o super\nMUSIC DIRECTOR!\fHã? Seu POKéGEAR\nnão pega os meus\fprogramas.\nQue azar!\fSe pegar o EXPN\nCARD, você\fconsegue ouvir.\nVá atrás de um!",
  ["5d:4b83"] = "Olá, camarada!\fEu sou o super\nMUSIC DIRECTOR!\fSou responsável\npelas melodias\flindas que vão\npara o ar.\fNão seja quadrado.\nPegue a sua música\vno ar!",
  ["5d:4c26"] = "1F RECEPÇÃO\n2F VENDAS\v3F PESSOAL\v4F PRODUÇÃO\v5F SALA DO\v   DIRETOR",
  ["5d:4c70"] = "Anime seus POKéMON\ncom o som suave\fda POKé FLUTE\nno CANAL 20",
  ["5d:4cae"] = "Nossa! Uma estante\ncheia de CDs e ví-\vdeos de POKéMON.\fDeve ser a\nbiblioteca.",
  ["5d:4d5c"] = "Você já foi a\nLAVENDER TOWN?\fTem uma RADIO\nTOWER bem alta.",
  ["5d:4df2"] = "Eu sou o irmão\nmais novo do\vFISHING GURU.\fVejo que você\ngosta de pescar.\fNão tenho a menor\ndúvida disso!\fE aí? Sei que\nestou certo.",
  ["5d:4e72"] = "Isso, isso. Como\neu pensava!\fToma, fã de pesca!\nPegue isto, é uma\vSUPER ROD.",
  ["5d:4ebf"] = "Tente pescar em\nqualquer lugar\vque tenha água.\fLembre, dá para\npegar POKéMON\fdiferentes com\nRODS diferentes.",
  ["5d:4f2f"] = "Hã? Meus próprios\nolhos erraram?",
  ["5d:4ff8"] = "Estou em choque!\fUm cara da sua\nidade, de olhar\fduro e cabelo\ncomprido entrou.\fEle me assustou e\nlevou o meu\vPOKéMON precioso!\fAinda tenho um,\nmas e se ele\vvoltar?\fVocê parece forte.\nVocê pode cuidar\fdo meu POKéMON\npor um tempo?",
  ["5d:50e2"] = "Ah, obrigado!\fCuide bem dele,\npor favor!",
  ["5d:5110"] = "{PLAYER} recebeu\num POKéMON.",
  ["5d:5124"] = "O time de POKéMON\nestá cheio.",
  ["5d:513e"] = "Ai, não… O que eu\nfaço se ele\vvoltar?",
  ["5d:5165"] = "Oi! Como está o\nmeu POKéMON?\fAcho que estou\nseguro agora. Pode\vdevolver ele?",
  ["5d:51a6"] = "Obrigado!",
  ["5d:51b2"] = "Ei, você não está\ncom o meu\vPOKéMON.",
  ["5d:51d8"] = "O meu POKéMON\ngostou de você.\fEstá bem, pode\nficar com ele.\fMas prometa ser\nbom com ele!",
  ["5d:5234"] = "Ah, não, não…\nIsso é a mesma\vcoisa que roubo.",
  ["5d:5261"] = "Para o POKéMON,\nser feliz é estar\fcom uma pessoa que\ntrata ele bem.",
  ["5d:52a5"] = "Se eu recuperar\nmeu POKéMON,\fo que você vai\nusar na batalha?",
  ["5d:53ee"] = "UAHAHAH!\fEntão você chegou\naté aqui!\fVou te avisar:\neu sou durão!\fMeus POKéMON vão\nesmagar pedras e\vquebrar ossos!\fOlhe só isto!",
  ["5d:5464"] = "CHUCK: Urggh!\n…\fOoooarrgh!",
  ["5d:547f"] = "Pronto! Com medo\nagora, hein?\fO quê?\nNão tem nada\fa ver com POKéMON?\nÉ verdade!\fVamos lá. Nós dois\nvamos batalhar!",
  ["5d:54eb"] = "Hã? Quê?\nEu perdi?\fVeja só isso!\nVocê merece a\vSTORMBADGE!",
  ["5d:552a"] = "{PLAYER} recebeu\na STORMBADGE.",
  ["5d:5542"] = "A STORMBADGE faz\ntodo POKéMON até\fo L70 obedecer,\naté os trocados.\fEla também deixa\nseu POKéMON usar\fFLY fora da\nbatalha.\fTome, fique com\nisto também!",
  ["5d:55cf"] = "Isso é o DYNAMIC-\nPUNCH.\fEle nem sempre\nacerta, mas quan-\fdo acerta, causa\nconfusão!",
  ["5d:5625"] = "UAHAHAH! Adorei\nbatalhar com você\fMas derrota é\nderrota!\fDe agora em diante\nvou treinar 24\vhoras por dia!",
  ["5d:568c"] = "Meu POKéMON e eu\nestamos unidos\vpela amizade.\fNosso laço\nnunca se quebra!",
  ["5d:56de"] = "Isto não é real!",
  ["5d:56ef"] = "Você parece ter\num forte laço\vcom seu POKéMON!",
  ["5d:5723"] = "Nada tememos,\nnós, lutadores!",
  ["5d:5745"] = "Isso é chocante!",
  ["5d:5756"] = "POKéMON de luta\ntemem os psíqui-\vcos…",
  ["5d:577f"] = "Palavras são\ninúteis. Deixe\vos punhos falar!",
  ["5d:57b5"] = "Perdi! Estou\nsem palavras!",
  ["5d:57ce"] = "Meus punhos fú-\nrios despedaçam\vseu POKéMON!",
  ["5d:57f7"] = "Fui despedaçado!",
  ["5d:5809"] = "Meu POKéMON per-\ndeu… Meu orgulho\vestá quebrado…",
  ["5d:58dd"] = "Você conheceu o\nPOKéMANIAC?\fEle vive se\ngabando dos\vPOKéMON raros.",
  ["5d:5923"] = "Os treinadores do\nGINÁSIO daqui são\vuns brutamontes.\fSe eu ficar aqui,\neles podem vir\vpara cima de mim.\fVai uma dica: o\nLÍDER do\fGINÁSIO usa o\ntipo lutador.\fEntão confunda\nele com POKéMON\vpsíquicos.\fAcabe com eles\nantes que usem\fa força\nfísica deles.",
  ["5d:5a2a"] = "{PLAYER}! Você\nganhou! Dá para\vver na sua cara!",
  ["5d:5ac9"] = "Seus POKéMON\nparecem bem.\fTem algo\npreocupando você?\f…\fO POKéMON do\nLIGHTHOUSE está\vem apuros?\fJá sei!\fIsto deve\nresolver.",
  ["5d:5b52"] = "{PLAYER} recebeu\na SECRETPOTION.",
  ["5d:5b6c"] = "Minha SECRETPOTION\né forte demais.\fSó ofereço numa\nemergência.",
  ["5d:5bf5"] = "Você está com uns\nPOKéMON\vmagníficos.\fQue tal uma foto\nde lembrança?",
  ["5d:5c3e"] = "Certo! Sorria!",
  ["5d:5c52"] = "Ah, que pena.\nAchei que seria\fuma bela\nlembrança…",
  ["5d:5cb8"] = "Você veio de\nOLIVINE?\fLembra das quatro\nilhas que ficam\vno caminho?\fOuvi dizer que\numa criatura\vmítica do mar\vse esconde lá.",
  ["5d:5d3b"] = "Ouvi dizer que só\ndá para vê-la se\fvocê tiver uma\nSILVER WING.\fEla deve ter o\nmesmo cheiro da\vcriatura.",
  ["5d:5da5"] = "Os redemoinhos\nperto das ilhas\fdevem ser causados\npela criatura.",
  ["5d:9100"] = "r lá fora.\fVolte após o\npôr-do-sol, tá?",
  ["5d:a500"] = "ra.",
  ["5d:cd00"] = "RIDIANA.\fA política do\nLÍDER é ganhar sem\va ajuda de nenhum\vsubalterno.",
  ["5e:4011"] = "Bem-vindo à LOJA\nDE DEPARTAMENTOS\vCELADON!\fO índice está\nna parede.",
  ["5e:4057"] = "Esta LOJA é da\nmesma rede que a\fde GOLDENROD.\nAs duas foram\freformadas ao\nmesmo tempo,\vjuntas.",
  ["5e:40cb"] = "É minha primeira\nvez aqui.\fÉ tão grande…\fTenho medo de me\nperder.",
  ["5e:410c"] = "1º ANDAR: RECEPÇÃO\nE SERVIÇOS\f2º ANDAR: MERCADO\nDO TREINADOR\f3º: LOJA DE TM\f4º: PRESENTES\f5º: FARMÁCIA\f6º: MÁQ. DE\nVENDAS",
  ["5e:41ed"] = "Me tornei\ntreinador\fpor incentivo do\nmeu filho.\fFico impressionado\ncom a seleção de\vitens práticos.",
  ["5e:4262"] = "Meu pai está tendo\ntrabalho para\fdecorar os nomes\ndos itens e como\feles devem ser\nusados…",
  ["5e:42c0"] = "Produtos ótimos\npara treinadores!\f2º ANDAR: MERCADO\nDO TREINADOR",
  ["5e:4377"] = "Não consigo\ndecidir em qual\fPOKéMON usar esta\nTM…",
  ["5e:43aa"] = "Opa! Negociei meu\nPOKéMON sem tirar\fo UPGRADE que o\nPOKéMON tinha.",
  ["5e:43eb"] = "Enfim consegui um\nPORYGON!\fSou péssimo nas\nmáquinas, nunca\fjuntaria moedas\npara trocar…\f…Hã?\fO PORYGON trocado\nvirou outro\vPOKéMON!",
  ["5e:4485"] = "LOJA DE TM vende\nmovimentos raros.",
  ["5e:44a9"] = "3º ANDAR: LOJA\fDE TM! Deixe seu\nPOKéMON forte!",
  ["5e:4545"] = "Vim comprar uma\nSURF MAIL para\vminha namorada.",
  ["5e:4579"] = "Este é o único\nlugar onde você\fcompra uma LOVELY\nMAIL.",
  ["5e:45b0"] = "Dê seu recado\ncom PRESENTES!\f4º: PRESENTES",
  ["5e:4647"] = "Quero comprar\nitens que elevem\fos status do\nPOKéMON, mas não\vtenho dinheiro…",
  ["5e:4696"] = "Quero um PP UP,\npra elevar o PP\fdos golpes, mas\nnão dá comprar",
  ["5e:46da"] = "Usar itens neles\ndeixa o POKéMON\vfeliz.\fEles odeiam alguns\nitens, porém…",
  ["5e:4724"] = "5º ANDAR FARMÁCIA",
  ["5e:486c"] = "Uma máquina de\nvendas! O menu:",
  ["5e:4890"] = "Click!\f{STRBUF}\nsaiu.",
  ["5e:48aa"] = "Opa, dinheiro\ninsuficiente…",
  ["5e:48c3"] = "Não há mais espaço\npara coisas…",
  ["5e:48e3"] = "Uma máquina de\nvendas com roleta\vde prêmios…\fVocê não vê mais\ndessas hoje.",
  ["5e:492c"] = "Ahh! Não há jogos\naqui!\fEu queria jogar…",
  ["5e:495a"] = "6º ANDAR: PRAÇA DO\nTELHADO: VENDAS",
  ["5e:4a32"] = "Meus POKéMON me\nfazem companhia,\fnunca me sinto\nsozinho.\fAté o MEOWTH\ntraz dinheiro.",
  ["5e:4ac7"] = "SUÍTE DO GERENTE\nDA MANSÃO CELADON",
  ["5e:4b55"] = "{PLAYER} ligou o\nPC.\f…\fAlguém estava no\nmeio de escrever\vum e-mail.\f…Espero que\nvisite KANTO.\fVai se surpreender\ncom quanta coisa\fmuita coisa\nmudou por aqui.\fTambém verá\nvários POKéMON\fque não existem\nem JOHTO.\fAo PRODUTOR\f…",
  ["5e:4c48"] = "GAME FREAK\nSALA DE ENCONTROS",
  ["5e:4cea"] = "Isso mesmo!\fSou o DESIGNER\ndo JOGO!\fCompletar sua\nPOKéDEX é duro,\vmas não desista!",
  ["5e:4d41"] = "Uau! Excelente!\nVocê completou sua\vPOKéDEX!\fParabéns!",
  ["5e:4d7f"] = "O ARTISTA GRÁFICO\nvai imprimir um\vDIPLOMA pra você.\fDeve mostrá-lo por\naí.",
  ["5e:4dd0"] = "Sou o ARTISTA\nGRÁFICO.\fEu te desenhei!",
  ["5e:4df4"] = "Sou o ARTISTA\nGRÁFICO.\fAh, completou sua\nPOKéDEX?\fPosso imprimir\no seu DIPLOMA?",
  ["5e:4e4c"] = "Me avise se quiser\nimprimir o\vDIPLOMA.",
  ["5e:4e7f"] = "Algo está errado.\nTerei que cancelar\va impressão.",
  ["5e:4eb1"] = "Quem, eu? Sou o\nPROGRAMADOR.\fJogue nas máquinas\ncaça-níqueis!",
  ["5e:4ee6"] = "As GÊMEAS são\nadoráveis!\fJASMINE também\né bonita.\fAh, eu as adoro!",
  ["5e:4f27"] = "GAME FREAK\nSALA DE PRODUÇÃO",
  ["5e:4f44"] = "É um desenho\ndetalhado de uma\vmoça bonita.",
  ["5e:4f6e"] = "É o programa do\njogo. Mexer nele\fpode causar um bug\nno jogo!",
  ["5e:4fb2"] = "Está cheio de\nmateriais de\vreferência e até\vum POKé DOLL.",
  ["5e:5058"] = "EU SEI TUDO!",
  ["5e:50ad"] = "Deixe-me contar\nalgo terrível…",
  ["5e:50d0"] = "Claro, não é tão\nassustador\fenquanto ainda há\nluz do dia.\fVolte depois do\npôr do sol, tá?",
  ["5e:5129"] = "Era uma vez\num menino que\fganhou uma\nBICYCLE nova…\fQuis testá-la\nna mesma hora…\fSe divertia tanto\nque nem notou\fque o sol tinha\nse posto…\fVoltando pra casa\nna noite escura,\fe a BICYCLE\nparou de repente\fOs pedais ficaram\npesados!\fQuando parou\nde pedalar, a\fBICYCLE foi\npuxada pra trás!\fComo se fosse\namaldiçoada e\fquisesse levá-lo\npro abismo!\f…\f…\fSHRIEEEEK!\fO menino estava\nsubindo a\vCYCLING ROAD\f…\nTum-tum-tum!\fPor ter ouvido\ncom paciência,\vfique com a TM03!",
  ["5e:5339"] = "O TM03 é CURSE.\fÉ um golpe que\ndrena o PS da\fvítima aos\npoucos.",
  ["5e:53b4"] = "ERIKA é mestre em\nPOKéMON do tipo\fgrama. Ela vai\nfazer você pagar\vse bobear.",
  ["5e:5405"] = "O esconderijo\nda EQUIPE ROCKET\ffica no porão da\nCASA DE JOGOS.\fAh, espera. Isso\nfoi há três anos.",
  ["5e:5571"] = "Bem-vindo!\fVocê pode trocar\nsuas moedas por\fprêmios incríveis\nna casa ao lado.",
  ["5e:55b6"] = "As caça-níqueis\nsão todas de\vúltima geração.",
  ["5e:55e3"] = "É esta máquina\nque eu quero.\fEla me limpou\nontem, então\fdeveria pagar\nhoje.",
  ["5e:5636"] = "Acho que esta\nmáquina vai pagar\vagora…\fAs chances variam\nentre máquinas.",
  ["5e:567d"] = "Hahahaha!\fAs moedas não\nparam de sair!\fHã? Quer jogar,\ngaroto?\fVou dividir minha\nsorte com você!",
  ["5e:56e6"] = "Hahahaha!\fÉ bom fazer\ncoisas boas para\fas outras\npessoas!",
  ["5e:572b"] = "Ei, você não tem\numa COIN CASE.\fComo vou te dar\nmoedas, se você\vnão tem uma?",
  ["5e:577a"] = "Ei, sua COIN\nCASE está cheia.\fVocê deve estar\nnuma maré de\vsorte também.",
  ["5e:57c6"] = "Ei! Futuro\nCAMPEÃO!\fTambém joga nas\ncaça-níqueis?\fEstou tentando\njuntar moedas\vpara um POKéMON\fde prêmio. Mas\nainda não tenho…",
  ["5e:584e"] = "Hmm… As chances\nsão melhores na\ffila do PIKACHU,\n…o que fazer?",
  ["5e:5894"] = "Ei!\fAtrás deste\npôster…\fNão há nada!",
  ["5e:58c2"] = "Ei!\fAtrás deste\npôster…\fNão há nada!",
  ["5e:58f0"] = "Há um isqueiro\naqui.",
  ["5e:5908"] = "Uma latinha de\frefri. Alguém vem\nbuscar depois…\fHã? Está vazia!",
  ["5e:5c59"] = "Queria um MR.MIME\nmas me faltaram\v100 moedas…",
  ["5e:5c8a"] = "Ufa…\fPreciso ficar\ncalmo e frio…\fNão posso perder\na calma, ou\vperco o dinheiro…",
  ["5e:5cdf"] = "Bem-vindo!\fTrocamos suas\nmoedas por\vprêmios incríveis",
  ["5e:5d15"] = "Qual prêmio você\nquer?",
  ["5e:5d32"] = "Então você quer\no {STRBUF}?",
  ["5e:5d4e"] = "Aqui está!",
  ["5e:5d5c"] = "Você não tem\nmoedas pra isso…",
  ["5e:5d79"] = "Você não tem\nespaço para isto.",
  ["5e:5d93"] = "Oh. Volte com\nmais moedas!",
  ["5e:5db5"] = "Oh? Você não tem\na COIN CASE.",
  ["5e:5ec9"] = "ERIKA: Olá…\nQue tempo\fagradável, hein?\nÉ tão calmo…\fPosso até\ncochilar…\fMe chamo ERIKA.\nSou a LÍDER do\vGINÁSIO CELADON.\f…Oh? Você veio\nde JOHTO?\vQue bom…\fOh. Desculpe, não\npercebi que\fqueria me\ndesafiar.\fMuito bem, mas\nnão vou perder.",
  ["5e:5fdf"] = "ERIKA: Oh!\nAdmito a derrota…\fVocê é realmente\nforte…\fVou lhe dar a\nRAINBOWBADGE…",
  ["5e:6037"] = "{PLAYER} recebeu\na RAINBOWBADGE.",
  ["5e:6051"] = "ERIKA: Foi uma\npartida adorável.\fMe senti\ninspirada.\vFique com este\fTM.\fÉ GIGA DRAIN.\nÉ um golpe que\fdrena metade do\ndano causado,\vcurando seu\fPOKéMON. Se\nquiser, use…",
  ["5e:6100"] = "sar seu\vPOKéMON. Por\ffavor, use se\nquiser…",
  ["5e:6130"] = "ERIKA: Perder\ndeixa um gosto\vamargo…\fMas saber que\nhá treinadores\ffortes me espole\na melhorar…",
  ["5e:619d"] = "Espere! Aqui só\nentram garotas!",
  ["5e:61cd"] = "Nós não temos\nnada contra os\fmeninos. Só há\nassuntos que só\fgarotas podem\nconversar.",
  ["5e:622f"] = "Oh, uma batalha?\nQue assustador,\vmas tudo bem!",
  ["5e:626a"] = "Olha todas as\nsuas INSÍGNIAS.\fNão é à toa que\nnão venci!",
  ["5e:62a1"] = "Você estava\nolhando as flores\vou para mim?",
  ["5e:62dd"] = "Como faço para\nficar elegante\vcomo a ERIKA?",
  ["5e:630e"] = "Vamos mostrar\ngolpes que ERIKA\vnos ensinou!",
  ["5e:634c"] = "ERIKA vai se\nvingar por nós!",
  ["5e:636d"] = "Nós vamos proteger\na ERIKA!",
  ["5e:638b"] = "Não conseguimos…",
  ["5e:639c"] = "ERIKA é muito,\nmuito mais forte!",
  ["5e:64ba"] = "Oi!\fEstamos fazendo\numa competição\fde comilança. Não\npodemos atender.",
  ["5e:6505"] = "…Nhac, nhac…",
  ["5e:6516"] = "Não fale comigo!\fVocê vai quebrar\na concentração!",
  ["5e:6546"] = "…Glup… Glup…",
  ["5e:6554"] = "Quero quantidade\nantes de\fqualidade! Fico\nfeliz quando como",
  ["5e:658a"] = "Nhac, nhac…",
  ["5e:6599"] = "A comida é boa\naqui, mas a de\vGOLDENROD é a\vmelhor de todas.",
  ["5e:65dd"] = "Nhac… nhac…",
  ["5e:65ee"] = "Ninguém aqui vai\nte dar uma COIN\fCASE. Procure em\nJOHTO.",
  ["5e:6630"] = "Nhac… nhac…\fAinda posso comer",
  ["5e:6654"] = "Manda mais, CHEF!",
  ["5e:6661"] = "Competição de\ncomilança! Sem\flimite de tempo!\nbatalha sem fim!\fO maior comedor\nleva tudo grátis!",
  ["5e:66c3"] = "{PLAYER} achou\num {STRBUF}.",
  ["5e:66d5"] = "Mas {PLAYER} não\npode levar mais",
  ["5e:6757"] = "Se você descer a\nCYCLING ROAD,\fvocê vai parar\nem FUCHSIA CITY.",
  ["5e:67e6"] = "A CYCLING ROAD\ncomeça aqui. É\ftudo ladeira\nabaixo, e bem\vemocionante!\fUma sensação\nque só se sente\fem navio\nou trem.",
  ["5e:6874"] = "Ei! Pare!\fVocê não pode ir\npara a CYCLING\fROAD sem\nBICYCLE.",
  ["5e:690a"] = "Você soube do\nacidente na USINA\vDE ENERGIA?\fFica a leste,\nperto da CIDADE\vLAVANDA.",
  ["5e:6970"] = "Levo meu trabalho\nde GUARDA a sério\fEi! Você tem uma\nPOKéDEX.\fCerto. Você pode\npassar.",
  ["5e:6a0a"] = "CYCLING ROAD\na subida começa",
  ["5e:6a2b"] = "Espera! Você não\ntem BICYCLE?\fA CYCLING ROAD\nfica aqui.\fVocê precisa de\nBICYCLE pra ir",
  ["5e:8b63"] = "…",
  ["5e:ce62"] = "ado por pessoa\fmá, acaba ficando\nmau também.",
  ["5f:4057"] = "BLUE: Ei! Enfim\nchegou aqui, né?\fEu não tava a fim\nem CINNABAR,\fmas agora estou\npronto para você.\f…\fEstá me dizendo\nque venceu JOHTO\vinteira?\fHa! Então os\nGINÁSIOS de JOHTO\vdevem ser fracos.\fEi, não esquenta\ncom isso.\fEu vou saber se\nvocê é bom ou não\fbatalhando com\nvocê agora.\fPronto, garoto?",
  ["5f:4188"] = "BLUE: O quê?\fComo diabos eu\nperdi para você?\f…\fTsc, está bem…\nToma, pegue isto,\va EARTHBADGE.",
  ["5f:41e9"] = "{PLAYER} recebeu\na EARTHBADGE.",
  ["5f:4201"] = "BLUE: …\fEstá bem, eu\nerrei. Você\fé o cara mesmo.\nÉ bom treinador.\fMas eu vou vencer\nvocê um dia.\fNão vá esquecer\ndisso!",
  ["5f:4285"] = "BLUE: Escuta.\fÉ bom você não\nperder até eu te\vvencer. Entendeu?",
  ["5f:42c8"] = "Ei, futuro\nCAMPEÃO!\fComo vai isso?\nParece que você\vestá embalado.\fO LÍDER daqui é\num cara que lutou\fcom o CAMPEÃO faz\ntrês anos.\fNão é mole não.\fDê tudo o que\nvocê tem!",
  ["5f:437a"] = "Cara, você é forte\nde verdade…\fFoi uma batalha\ne tanto, das que\finspiram. Chorei\nde emoção.",
  ["5f:442e"] = "Você pensa muito\nna hora de\fdar nome aos\nseus POKéMON?\fBons apelidos\ndeixam a troca\fcom os outros\nmais divertida.",
  ["5f:44a5"] = "São o SPEARY,\num SPEAROW, e o\vRATTEY, RATTATA.",
  ["5f:4559"] = "Bem-vindo à\nTRAINER HOUSE,\fo lugar mais novo\ne badalado daqui.\fA gente só abre\npara treinador.\fDá para enfrentar\nos melhores\fdos melhores logo\naqui embaixo.",
  ["5f:45ff"] = "VIRIDIAN é a vila\nmais perto do\vINDIGO PLATEAU.\fFizeram este lugar\nporque muito\ftreinador passa\npor aqui subindo\fao INDIGO\nPLATEAU.",
  ["5f:468f"] = "Fazem batalhas de\ntreino aqui\vembaixo.\fEu adoraria ver\no quanto um\ftreinador de JOHTO\nbatalha bem.",
  ["5f:46f7"] = "Acho que não dá\npara ser CAMPEÃO\fsem rodar o mundo\ntodo e batalhar\fcom todo tipo\nde gente.\fO CAMPEÃO de\nPALLET viajou por\ftodas as cidades\ne vilas de KANTO.",
  ["5f:47a3"] = "Ufa… Estou dando\num descanso das\vbatalhas.",
  ["5f:47ce"] = "As batalhas de\ntreino acontecem\fno TRAINING HALL\naqui embaixo.\fTreinadores bons\nestão convidados\va participar.",
  ["5f:4837"] = "Não tem regra nem\nregulamento nas\fpartidas de treino\nIgual às batalhas\fde campo, vale\ntudo!",
  ["5f:489b"] = "…O que é isto?\nUm plano de luta?\fA letra parece\nrastro de ONIX…\fEstá totalmente\nilegível…",
  ["5f:49fa"] = "Oi. Bem-vindo ao\nTRAINING HALL.\fVocê pode batalhar\ncom um treinador\vuma vez por dia.",
  ["5f:4a44"] = "{STRBUF} é o seu\nadversário hoje.",
  ["5f:4a61"] = "Você quer\nbatalhar?",
  ["5f:4a7c"] = "Por favor, pode\nentrar.\fVocê já pode\ncomeçar.",
  ["5f:4ab0"] = "Desculpe. Só os\ntreinadores que\fvão batalhar podem\nentrar.",
  ["5f:4af7"] = "Sinto muito,\nsenhor.\fSeria a segunda\nvez hoje. Só é\fpermitido entrar\numa vez por dia.",
  ["5f:4b57"] = "Perdi…\nDroga…",
  ["5f:4b66"] = "Eu viajei até\naqui só para\vbatalhar contigo.",
  ["5f:4bd3"] = "O LÍDER daqui\né totalmente\vsensacional.",
  ["5f:4bf9"] = "Você já foi a\nCINNABAR?\fÉ uma ilha bem\nao sul daqui.",
  ["5f:4c8c"] = "Onde diabos está\no LÍDER do\fGINÁSIO daqui?\nQueria desafiar.",
  ["5f:4cd4"] = "Não tem TREINADOR\nde GINÁSIO no\vGINÁSIO daqui.\fO LÍDER diz que a\npolítica dele é\fvencer sem ter\nsubordinado.",
  ["5f:4d4a"] = "Ouvi dizer que o\nGINÁSIO de\vCINNABAR sumiu.\fFico pensando no\nque foi feito do\vBLAINE, o LÍDER.",
  ["5f:4da7"] = "Meu sonho é virar\nLÍDER de GINÁSIO.",
  ["5f:4e44"] = "Oi! Nossa, que bom\nver você.\fVocê é a primeira\nvisita que eu\vtenho faz tempo.\fEstou super feliz!\nDeixa eu te dar\vum presentinho.",
  ["5f:4ec4"] = "Isso é um NUGGET.\fEu não tenho\nsabedoria a dar,\fentão isso vai\nter que servir!",
  ["5f:4f34"] = "Você é {PLAYER}?\fEu trabalho como\nAIDE do PROF.OAK.\fEu não fazia ideia\nque você viria.\fO LAB do PROF.OAK\nfica perto, em\vPALLET TOWN.",
  ["5f:5008"] = "Só passa o\ntreinador que já\vprovou seu valor.",
  ["5f:503e"] = "Você não tem todas\nas INSÍGNIAS de\vJOHTO.\fSinto muito, mas\nnão posso deixar\vvocê passar.",
  ["5f:5093"] = "Oh! As oito\nINSÍGNIAS!\fPor favor, pode\nseguir, senhor!",
  ["5f:50d0"] = "Este caminho leva\nao MT.SILVER.\fVocê vai ver\nPOKéMON fortes de\vdar medo lá.",
  ["5f:5116"] = "Indo para a\nPOKéMON LEAGUE?\fOs ELITE FOUR são\ntão fortes que dá\fmedo, e estão\nprontos para você",
  ["60:43f7"] = "ELM: {PLAYER}!\nAí está você!\fPreciso lhe pedir\num favor.\fTenho um conhecido\nchamado MR.\vPOKéMON.\fEle vive achando\ncoisas estranhas\fe se gabando das\ndescobertas.\fEnfim, recebi um\ne-mail dele agora\fdizendo que desta\nvez é de verdade.\fÉ intrigante, mas\nestamos ocupados\fcom nossa pesquisa\nde POKéMON.\fVocê poderia ir\nver isso por nós?\fVou lhe dar um\nPOKéMON de\vparceiro.\fSão todos POKéMON\nraros que acabamos\vde encontrar.\fEscolha um deles!",
  ["60:4590"] = "Se um POKéMON\nselvagem aparecer,\vdeixe o seu lutar",
  ["60:45c2"] = "ELM: Espere! Aonde\nvocê vai?",
  ["60:45e3"] = "ELM: Vai levar o\nCYNDAQUIL, o\vPOKéMON de fogo?",
  ["60:460e"] = "ELM: Você quer o\nTOTODILE, o\vPOKéMON de água?",
  ["60:463a"] = "ELM: Então gosta\nda CHIKORITA, a\vPOKéMON planta?",
  ["60:4668"] = "ELM: Pense bem\ncom calma.\fSeu parceiro é\nimportante.",
  ["60:46a2"] = "ELM: Acho esse\num ótimo\vPOKéMON também!",
  ["60:46c8"] = "{PLAYER} recebeu\n{STRBUF}!",
  ["60:46db"] = "MR.POKéMON mora\nperto de\vCHERRYGROVE.\fA próxima cidade.\nÉ quase direto\vdaqui.",
  ["60:472f"] = "Se seu POKéMON se\nmachucar, cure\fele nesta\nmáquina.",
  ["60:476c"] = "Ah, aqui está meu\ntelefone.\fMe ligue se algo\nacontecer.",
  ["60:47a9"] = "{PLAYER} anotou o\ntelefone do ELM.",
  ["60:47c3"] = "MR.POKéMON vai a\ntoda parte e acha\vraridades.\fPena que sejam só\nraras e não muito\vúteis…\f{PLAYER}, conto\ncom você!",
  ["60:4835"] = "Contém um POKéMON\ncapturado pelo\vPROF.ELM.",
  ["60:485d"] = "Será que isto faz\no quê?",
  ["60:4877"] = "Curar POKéMON?",
  ["60:4883"] = "ELM: {PLAYER}, isto\né terrível…\fAh, sim, qual foi\na descoberta do\vMR.POKéMON?",
  ["60:48c8"] = "{PLAYER} entregou\no OVO MISTERIOSO\vao PROF.ELM.",
  ["60:48ef"] = "ELM: Isto?",
  ["60:48fb"] = "Mas… Será um OVO\nde POKéMON?\fSe for, é um\ngrande achado!",
  ["60:4936"] = "ELM: O quê?!?\fO PROF.OAK lhe deu\numa POKéDEX?\f{PLAYER}, é verdade\nmesmo? I-isso é\vincrível!\fEle é ótimo em ver\no potencial das\vpessoas como\vtreinadores.\fUau, {PLAYER}. Você\npode ter o que é\fpreciso para virar\nCAMPEÃO.\fParece que você se\ndá muito bem\vcom POKéMON.\fVocê devia encarar\no desafio do\vGINÁSIO POKéMON.\fO GINÁSIO mais\nperto fica em\vVIOLET CITY.",
  ["60:4a85"] = "…{PLAYER}. O\ncaminho até o\fcampeonato vai ser\nlongo.\fAntes de partir,\nnão esqueça de\vfalar com sua mãe",
  ["60:4af2"] = "ELM: Não desista!\nEu ligo se souber\fde algo sobre\naquele OVO!",
  ["60:4b33"] = "ELM: {PLAYER}?\nVocê não achou meu\vassistente?\fEle devia lhe\nentregar o OVO\fno CENTRO POKéMON\nde VIOLET CITY.\fVocê deve ter\nperdido ele. Tente\vencontrá-lo lá.",
  ["60:4bd1"] = "ELM: Ei, aquele\nOVO mudou algo?",
  ["60:4bf6"] = "{PLAYER}? Pensei\nque o OVO chocou.\fCadê o\nPOKéMON?",
  ["60:4c28"] = "ELM: {PLAYER}, você\nestá ótimo!",
  ["60:4c41"] = "O quê?\nAquele POKéMON!?!",
  ["60:4c55"] = "O OVO chocou!\nEntão POKéMON\vnascem de OVOS…\fNão, talvez não\ntodos eles.\fUau, ainda há\nmuita pesquisa\vpela frente.",
  ["60:4cd2"] = "Obrigado, {PLAYER}!\nVocê nos ajuda a\fdesvendar os\nmistérios POKéMON\fQuero que fique\ncom isto em sinal\vda nossa gratidão",
  ["60:4d43"] = "Isso é uma\nEVERSTONE.\fCertas espécies de\nPOKéMON evoluem\fao chegar a certos\nníveis.\fUm POKéMON segu-\nrando a EVERSTONE\vnão evolui.\fDê a um POKéMON\nque você não quer\vque evolua.",
  ["60:4ded"] = "ELM: {PLAYER}, eu\nligo se algo\vacontecer.",
  ["60:4e1b"] = "…ai… Aquele\nPOKéMON roubado.\fFico pensando como\nele está.\fDizem que POKéMON\ncriado por gente\fruim fica ruim\ntambém.",
  ["60:4e86"] = "ELM: Oi, {PLAYER}!\nGraças a você,\fminha pesquisa vai\nmuito bem!\fLeve isto como\nsinal da minha\vgratidão.",
  ["60:4ee7"] = "A MASTER BALL é a\nmelhor de todas!\fÉ a BALL suprema!\nCaptura qualquer\fPOKéMON sem\nfalhar nunca.\fSó é dada a\npesquisadores\vPOKéMON de renome\fAcho que você faz\nmelhor uso dela\fdo que eu,\n{PLAYER}!",
  ["60:4fa4"] = "ELM: {PLAYER}!\nAí está você!\fLiguei porque\ntenho algo para\vvocê.\fViu? É um\nS.S.TICKET.\fAgora pode pegar\nPOKéMON em KANTO.",
  ["60:5020"] = "O navio parte de\nOLIVINE CITY.\fMas isso você já\nsabia, {PLAYER}.\fAfinal, você foi\na toda parte\vcom seus POKéMON.\fMande lembranças\nao PROF.OAK!",
  ["60:50bc"] = "É o POKéMON EGG\nque o PROF.ELM\vestá estudando.",
  ["60:50e9"] = "{PLAYER}, quero que\nfique com isto\vpara a sua missão",
  ["60:5116"] = "Somos só nós dois,\nentão vivemos\vsempre ocupados.",
  ["60:5146"] = "Houve um barulho\nalto lá fora…\fQuando fomos ver,\nroubaram um\vPOKéMON daqui.\fÉ inacreditável\nque alguém faça\visso!\f…ai… Aquele\nPOKéMON roubado.\fFico pensando como\nele está.\fDizem que POKéMON\ncriado por gente\fruim fica ruim\ntambém.",
  ["60:5229"] = "{PLAYER}!\fUse isto na sua\njornada POKéDEX!",
  ["60:524b"] = "Para completar a\nPOKéDEX, você tem\vque pegar POKéMON\fJogue POKé BALLS\nnos POKéMON\vselvagens.",
  ["60:52a1"] = "Soube que roubaram\num POKéMON aqui…\fEu estava colhendo\ninformações com o\vPROF.ELM.\fPelo visto era um\njovem de cabelo\vlongo e vermelho…\fO quê?\fVocê lutou com um\ntreinador assim?\fPor acaso soube\no nome dele?",
  ["60:5371"] = "Certo! Então\n{RIVAL} é o nome.\fObrigado por\najudar na busca!",
  ["60:53ae"] = "Janela aberta.\fUma brisa gostosa\nentra por ela.",
  ["60:53e2"] = "Ele entrou\npor aqui!",
  ["60:53fd"] = "{PLAYER} abriu um\nlivro.\fDica de viagem 1:\fAperte START para\nabrir o MENU.",
  ["60:543b"] = "{PLAYER} abriu um\nlivro.\fDica de viagem 2:\fRegistre a viagem\ncom SAVE!",
  ["60:5477"] = "{PLAYER} abriu um\nlivro.\fDica de viagem 3:\fAbra a BOLSA e\naperte SELECT para\vmover itens.",
  ["60:54c6"] = "{PLAYER} abriu um\nlivro.\fDica de viagem 4:\fVeja os movimentos\ndo POKéMON. Use\fo botão A para\ntrocar de lugar.",
  ["60:5521"] = "A embalagem do\nlanche que o PROF.\vELM comeu está aí",
  ["60:5719"] = "Ah, {PLAYER}! Nosso\nvizinho, o PROF.\fELM, estava\nprocurando você.\fDisse que queria\nque você fizesse\valgo para ele.\fAh! Quase esqueci!\nSua POKéMON GEAR\fvoltou do\nconserto.\fAqui está!",
  ["60:57d2"] = "POKéMON GEAR, ou\nsó POKéGEAR.\fÉ essencial se\nvocê quer ser um\vbom treinador.\fAh, falta ajustar\no dia da semana.\fNão pode esquecer\ndisso!",
  ["60:5857"] = "Estamos no horário\nde verão agora?",
  ["60:5878"] = "Volte para casa\npara ajustar o\frelógio no horário\nde verão.\fA propósito, você\nsabe usar o\vTELEFONE?",
  ["60:58e0"] = "Não é só ligar a\nPOKéGEAR e\fescolher o ícone\ndo TELEFONE?",
  ["60:591c"] = "Vou ler as\ninstruções.\fLigue a POKéGEAR e\nescolha o ícone\vdo TELEFONE.",
  ["60:5965"] = "Os números ficam\nsalvos na memória\fÉ só escolher o\nnome para ligar.\fQue prático,\nnão é mesmo?",
  ["60:59ca"] = "O PROF.ELM está\nesperando você.\fVá logo, querido!",
  ["60:59fa"] = "E aí, qual era\na missão do ELM?\f…\fIsso parece\nmesmo um desafio.\fMas orgulhe-se de\nque as pessoas\vcontam com você.",
  ["60:5a6c"] = "{PLAYER}, vá!\fEstou com você\naté o fim!",
  ["60:5a92"] = "Prato da mamãe!\fHAMBÚRGUER VULCÃO\nDE CINNABAR!",
  ["60:5abc"] = "A pia está\nimpecável. A mamãe\vgosta dela limpa.",
  ["60:5ae9"] = "Vamos ver o que há\nna geladeira…\fFRESH WATER e uma\nboa LEMONADE!",
  ["60:5b28"] = "Passa um filme na\nTV: estrelas no\fcéu e dois\nmeninos no trem…\fÉ melhor eu ir\nandando também!",
  ["60:5c5c"] = "POKéMON TALK DO\nPROF.OAK! Não\vperca a próxima!",
  ["60:5c8d"] = "CANAL POKéMON!",
  ["60:5c9c"] = "Aqui é a DJ MARY,\nsua parceira!",
  ["60:5cbc"] = "POKéMON!\nCANAL POKéMON…",
  ["60:5d64"] = "PIKACHU é um\nPOKéMON evoluído.\fFiquei espantado\ncom as descobertas\vdo PROF.ELM.\fEle é bem famoso\npela pesquisa da\vevolução.\f…suspiro…\fEu queria poder\nser pesquisador\vcomo ele…",
  ["60:5e09"] = "POKéMON TALK do\nPROF.OAK! Ouça\vna próxima!",
  ["60:5e3a"] = "CANAL POKéMON!",
  ["60:5e49"] = "Aqui é a DJ MARY,\nsua parceira!",
  ["60:5e69"] = "POKéMON!\nCANAL POKéMON…",
  ["60:5eb8"] = "Oi, {PLAYER}! Meu\nmarido vive tão\focupado, e espero\nque ele fique bem\fQuando mergulha na\npesquisa POKéMON,\fele até esquece\nde comer.",
  ["60:5f2c"] = "Quando eu crescer,\nvou ajudar o meu\vpai!\fVou ser um grande\nprofessor\vPOKéMON!",
  ["60:5f7d"] = "Tem comida aqui.\nDeve ser para o\vLAB.",
  ["60:5fad"] = "Tem comida aqui.\nDeve ser para os\vPOKéMON.",
  ["60:5fdc"] = "POKéMON. De onde\neles vêm?\fPara onde eles\nvão?\fPor que ninguém\nnunca viu um\vPOKéMON nascer?\fQuero saber! Vou\ndedicar a vida\fao estudo dos\nPOKéMON!\f…\fFaz parte dos\nartigos de\vpesquisa do ELM.",
  ["60:610b"] = "Seus POKéMON estão\nmeio cansados.\fÉ bom deixar eles\ndescansar.",
  ["60:6149"] = "Pronto!\fSeus POKéMON estão\ncom boa cara!\fContinue assim!",
  ["60:61b7"] = "Tem uma coisa\nescrita aqui.\fLer?",
  ["60:61e0"] = "Aos meus irmãos e\nirmãs:\fTemos orgulho de\nservir treinadores\vde POKéMON.\fQuando o treinador\nfalar com você, dê\valgo útil a ele.\fCom amor,\nMONICA\fContinuar lendo?",
  ["60:6277"] = "Segunda, MONICA\nROUTE 40\fTerça, TUSCANY\nROUTE 29\fQuarta, WESLEY\nLAKE OF RAGE\fQuinta, ARTHUR\nROUTE 36\fSexta, FRIEDA\nROUTE 32\fSábado, SANTOS\nBLACKTHORN CITY\fDomingo, SUNNY\nROUTE 37",
  ["60:6384"] = "Para onde você vai\ncom POKéMON?\fPOKéMON LEAGUE?\fSeus POKéMON são\nleais o bastante\vpara você vencer?\fDeixe eu ver…",
  ["60:63e9"] = "Ah! Seu POKéMON\nconfia muito\vem você.\fÉ bom ver um\nbom treinador.\fToma. Um presente\npara a viagem.",
  ["60:644d"] = "A TM37 é o\nSANDSTORM.\fÉ um golpe que\ncausa dano nos\vdois lados.\fÉ para treinador\navançado só.\fUse se tiver\ncoragem. Sorte!",
  ["60:64dd"] = "Se ele não passar\na confiar mais\fem você, pode ser\nduro seguir.\fConfiança é o laço\nque une POKéMON\ve treinadores.",
  ["60:657f"] = "Não dá para subir\nbarranco.\fMas dá para pular\nde cima deles e\vcortar caminho.",
  ["60:65cb"] = "Tipos diferentes\nde POKéMON surgem\vdepois daqui.\fSe quiser pegar\ntodos eles,\ftem que procurar\nem todo lugar.",
  ["61:400d"] = "Olá!\fO KARATE KING,\nmestre do DOJO,\festá numa caverna\nem JOHTO,\vtreinando.",
  ["61:4061"] = "Tudo o que vai\nvolta!",
  ["61:4081"] = "Inimigos por\ntodos os lados!",
  ["61:4180"] = "SABRINA: Eu sabia\nque você viria…\fFaz três anos eu\ntive uma visão da\vsua chegada.\fVocê quer a minha\nINSÍGNIA.\fEu não gosto de\nbatalhar, mas é\fmeu dever de LÍDER\ndar INSÍGNIAS\fa quem provar\nque é digno\vou digna.\fJá que você quer,\neu vou mostrar meu\vpoder psíquico!",
  ["61:4295"] = "SABRINA: O seu\npoder…\fVai muito além do\nque eu previ…\fTalvez não seja\npossível prever\fpor inteiro o que\no futuro guarda…\fCerto, você venceu\ne conquistou a\vMARSHBADGE.",
  ["61:4336"] = "{PLAYER} recebeu\na MARSHBADGE.",
  ["61:4346"] = "nou\nsua alma mais\vpoderosa, não\vapenas suas\vhabilidades.",
  ["61:434e"] = "SABRINA: A MARSH-\nBADGE desperta\fos seus poderes\nsubliminares…\fMesmo eu tendo\nfalhado em prever\vo seu poder com\vexatidão, disto eu\vtenho certeza.\fVocê vai se tornar\num CAMPEÃO\vamado e famoso!",
  ["61:440d"] = "SABRINA: Seu amor\npelos POKéMON\fvenceu o meu\npoder psíquico…\fO poder do amor,\neu acho, também é\fum tipo de poder\npsíquico…",
  ["61:448a"] = "A força de todos\nque você venceu\vvem para mim!",
  ["61:44bc"] = "Forte…\nForte demais…",
  ["61:44d5"] = "De onde vem a\nsua força?",
  ["61:44f8"] = "O poder psíquico\né o poder da sua\valma.",
  ["61:4522"] = "Sua alma tem mais\nforça que a minha",
  ["61:4547"] = "Você fortaleceu a\nalma, não só as\vhabilidades.",
  ["61:457e"] = "Fufufufu…\nVejo com clareza.\fEu enxergo\nna sua alma!",
  ["61:45b5"] = "Mesmo te lendo,\neu perdi…",
  ["61:45d7"] = "Droga! Esqueci\nque eu previ que\vperderia para ti",
  ["61:460d"] = "O FIGHTING DOJO\ndo lado já foi\vo GINÁSIO daqui.",
  ["61:4654"] = "O KARATE KING,\nmestre do\fFIGHTING DOJO, foi\narrasado agora\vpela SABRINA.",
  ["61:46a2"] = "Ei, futuro\nCAMPEÃO!\fUm treinador tão\nbom quanto você\fnão precisa que\ndigam como lidar\fcom POKéMON do\ntipo psíquico?\fEspero grandes\ncoisas de você!\fBoa sorte!",
  ["61:4741"] = "Foi mais uma\nbatalha e tanto!",
  ["61:486d"] = "Tem uma RADIO\nTOWER bem grande\vem LAVENDER.",
  ["61:4894"] = "Eu quero ficar\nmais forte, mas\vainda não sou…\fVocê me ensina\ncomo, um dia?",
  ["61:493b"] = "Tem uma POWER\nPLANT enorme ao\vnorte de LAVENDER",
  ["61:496e"] = "Por acaso eu\npassei pelo ROCK\fTUNNEL. Tinha um\nrebuliço lá na\vPOWER PLANT.",
  ["61:49c9"] = "Caverna desaba\ncom facilidade.\fVárias cavernas\nsumiram nos\fúltimos anos,\ncomo aquela perto\vde CERULEAN.\fComo HIKER pro,\nisso é coisa\vque se sabe.",
  ["61:4a60"] = "A SEDE da SILPH\nCO. e a ESTAÇÃO\fdo MAGNET TRAIN\nsão os lugares\fpara ver em\nSAFFRON.",
  ["61:4b33"] = "…\f…\f…\f…Já sei!\fVocê queria isto!",
  ["61:4b56"] = "A TM29 é PSYCHIC.\fEla pode baixar o\nSPECIAL do\valvo.",
  ["61:4c45"] = "Desculpe, mas o\nMAGNET TRAIN não\vestá rodando.",
  ["61:4c79"] = "Vamos partir logo\npara GOLDENROD.\fVocê vai\nembarcar?",
  ["61:4cb3"] = "Posso ver o seu\nPASS de trem?\fCerto. Por aqui,\nsenhor.",
  ["61:4cef"] = "Desculpe, mas você\nnão tem PASS.",
  ["61:4d11"] = "Esperamos ver você\nde novo.",
  ["61:4d2c"] = "Chegamos em\nSAFFRON.\fEsperamos ver você\nde novo.",
  ["61:4d63"] = "O MAGNET TRAIN\né um trem super\fmoderno que usa\neletricidade e\fímãs para chegar\na uma velocidade\vincrível.\fSó que, se não\nhouver energia\velétrica…",
  ["61:4dfa"] = "Ufa…\fQuantas vezes eu\njá fui e voltei\fentre KANTO\ne JOHTO?",
  ["61:4e44"] = "Antes de fazerem\na MAGNET TRAIN\fSTATION, tinha uma\ncasa ali.\fUma menina\nchamada COPYCAT\vmorava lá.",
  ["61:4eb9"] = "Oi. Você tem um\nPASS de trem? Eu\ftenho um. Todo\nmundo em SAFFRON\fque anda no MAGNET\nTRAIN tem um.",
  ["61:4f9c"] = "Bem-vindo. Este é\no PRÉDIO da SEDE\vda SILPH CO.",
  ["61:4fcf"] = "Só funcionário\npode subir\vas escadas.\fMas já que você\nveio de longe,\fleve esta\nlembrancinha.",
  ["61:5041"] = "É o produto mais\nnovo da SILPH CO.\fNão está à venda\nem lugar nenhum.",
  ["61:50cd"] = "Minha filha gosta\nde imitar gente.\fA imitação deu a\nela o apelido\fde COPYCAT\naqui na região.",
  ["61:512e"] = "Minha filha é tão\ncentrada nela…\fEla tem só uns\npoucos amigos.",
  ["61:516c"] = "Ela perdeu faz\npouco a POKé DOLL\fque um menino deu\na ela faz 3 anos.\fDesde então, ela\nficou ainda melhor\vem imitar…",
  ["61:52f1"] = "{PLAYER}: Oi! Você\ngosta de POKéMON?\f{PLAYER}: Ué, não,\neu que perguntei.\f{PLAYER}: Hã?\nVocê é estranha!",
  ["61:533f"] = "COPYCAT: Hum?\nParar de imitar?\fMas esse é o meu\nhobby favorito!",
  ["61:537b"] = "{PLAYER}: Oi!\nSoube que você\fperdeu a sua POKé\nDOLL favorita.\f{PLAYER}: Se eu\nachar, você me dá\vum PASS de trem?\f{PLAYER}: Vou\nachar para você.\fVocê acha que\nperdeu quando foi\va VERMILION CITY?",
  ["61:5400"] = " acha que a\nperdeu quando foi\và CIDADE\vVERMILION?",
  ["61:542d"] = "COPYCAT: Como?\fEu não deveria\ndecidir o que você\vfaz?\fMas eu estou bem\npreocupada… E se\valguém achar ela?",
  ["61:5496"] = "COPYCAT: Oba!\nÉ a minha POKé\vDOLL de CLEFAIRY!\fViu o rasgo onde a\nperna direita é\fcosturada? Essa é\na prova!",
  ["61:54f9"] = "Certo. Aqui está o\nMAGNET TRAIN PASS\vque eu prometi!",
  ["61:552b"] = "COPYCAT: Esse é\no PASS do\vMAGNET TRAIN.\fO homem da\nferrovia me deu\fquando derrubaram\na nossa casa velha\vpara a STATION.",
  ["61:55af"] = "{PLAYER}: Oi!\nMuito obrigado\vpelo PASS!\f{PLAYER}: Como?\f{PLAYER}: É tão\ndivertido imitar\vtudo o que faço?",
  ["61:560c"] = "COPYCAT: Claro!\nÉ hilário!",
  ["61:5640"] = "ESPELHO, ESPELHO\nMEU, HÁ ALGUÉM\fMAIS BELA DO QUE\nEU?",
  ["61:567b"] = "É um POKéMON\nraro! Hã?\fÉ só uma boneca…",
  ["61:5702"] = "Muitas cidades de\nJOHTO são antigas\fEu adoraria\nvisitar!",
  ["61:5766"] = "Você é de JOHTO,\nnão é?\fO que achou de\nKANTO? É bacana,\vnão concorda?",
  ["61:57ff"] = "Iiiaaah!\fEu sinto uma\nsombra sinistra\vpairando em você.\fLeve isto para\nafastar ela!",
  ["61:5851"] = "Você estava em\nperigo mortal, mas\vestá protegido.",
  ["61:5888"] = "Minha avó gosta de\nafastar o que ela\facredita serem\nespíritos ruins.\fDesculpe se ela\nassustou você.",
  ["62:402c"] = "Acabaram as\nPOKé BALLS!\fQuando será que\nchegam mais?",
  ["62:406b"] = "Tem POKé BALLS em\nestoque! Agora\vposso pegar!",
  ["62:4098"] = "Quando eu andava\nno mato, um\fPOKéMON inseto\nenvenenou o meu!\fEu segui andando,\nmas aí o meu\vPOKéMON desmaiou.\fÉ bom andar com um\nANTIDOTE.",
  ["62:4182"] = "É ótimo. Dá para\nguardar quantos\fPOKéMON quiser, e\ntudo de graça.",
  ["62:41c0"] = "Aquele PC é livre\npara qualquer\vtreinador usar.",
  ["62:41e9"] = "O CENTRO DE\nCOMUNICAÇÃO lá em\vcima é novinho.\fMas ainda estão\nterminando ele.",
  ["62:423e"] = "O CENTRO DE\nCOMUNICAÇÃO lá em\vcima é novinho.\fJá troquei POKéMON\nlá!",
  ["62:42e2"] = "Você quer ver o\nquanto é bom\fcomo treinador\nde POKéMON?\fÉ melhor visitar\nos GINÁSIOS por\ftoda JOHTO e\njuntar INSÍGNIAS.",
  ["62:435d"] = "Quando eu crescer,\neu vou ser LÍDER\vde GINÁSIO!\fBoto meus POKéMON\npara lutar\fcom os do amigo e\ndeixá-los duros.",
  ["62:4405"] = "Quando eu era\npequeno, eu era um\vtreinador craque!\fVai um conselho:\npegue um monte\vde POKéMON!\fTrate todos eles\ncom bondade!",
  ["62:44bb"] = "POKéMON ganha\nexperiência em\fbatalha e muda\nde forma.",
  ["62:44f4"] = "POKéMON muda?\fEu ia levar um\nsusto se mudasse!",
  ["62:457a"] = "Sabe, POKéMON\ncome BERRIES.\fBom, o meu POKéMON\nficou mais forte\vcomendo uma BERRY\fToma. Vou dividir\numa com você!",
  ["62:45e4"] = "Olhe as árvores\natrás de BERRIES.\vElas só caem.",
  ["62:4755"] = "Olá, olá! Você\ndeve ser {PLAYER}.\fO PROF.ELM disse\nque você viria.",
  ["62:4797"] = "Isto é o que eu\nquero que o\vPROF.ELM examine.",
  ["62:47c1"] = "{PLAYER} recebeu\no MYSTERY EGG.",
  ["62:47da"] = "Conheço um casal\nque cuida de um\vDAY-CARE.\fForam eles que me\nderam esse EGG.\fFiquei intrigado,\nentão mandei uma\vcarta ao ELM.\fEm evolução de\nPOKéMON, o ELM\vé a autoridade.",
  ["62:4881"] = "Até o PROF.OAK\naqui reconhece.",
  ["62:48a6"] = "Se a minha ideia\nestiver certa, o\vELM vai saber.",
  ["62:48dc"] = "Você vai voltar\nao PROF.ELM?\fAqui. Seus POKéMON\nprecisam de um\vdescanso.",
  ["62:4923"] = "Estou contando\ncom você!",
  ["62:4939"] = "A vida é uma\ndelícia! Sempre\fnovas descobertas\npara fazer!",
  ["62:4974"] = "OAK: Aha! Então\nvocê é {PLAYER}!\fSou o OAK! Um\npesquisador.\fEu estava só\nvisitando meu\vamigo MR.POKéMON.\fSoube que você\nfazia um favor\fpara o PROF.ELM,\ne esperei aqui.\fOh! O que é isto?\nUm POKéMON raro!\fVamos ver…\fHum, entendi!\fEntendo por que\no PROF.ELM te deu\fum POKéMON para\nesta tarefa.\fPara pesquisadores\ncomo o PROF.ELM e\feu, POKéMON são\nnossos amigos.\fEle viu que você\ntrataria os seus\fPOKéMON com amor\ne cuidado.\f…Ah!\fVocê parece ser\nde confiança.\fQue tal você\nme ajudar?\fViu? Esta é a\nversão mais nova\vda POKéDEX.\fEla grava sozinha\nos dados dos\fPOKéMON que você\nviu ou pegou.\fÉ uma enciclopédia\nde ponta!",
  ["62:4bbb"] = "{PLAYER} recebeu\na POKéDEX!",
  ["62:4bcd"] = "Vá conhecer muitos\ntipos de POKéMON\fe complete essa\nPOKéDEX!\fMas eu fiquei\ntempo demais.\fTenho que ir a\nGOLDENROD para o\vmeu programa.\f{PLAYER}, eu estou\ncontando contigo!",
  ["62:4c65"] = "Hum? Essa SCALE!\nO que é isso?\vGYARADOS rubro?\fIsso é raro!\nEu, eu quero…\f{PLAYER}, quer\ntrocar comigo?\fPosso oferecer\neste EXP.SHARE que\vganhei do OAK.",
  ["62:4cfc"] = "Que decepção.\nAcontece que isso\vé bem raro.",
  ["62:4d32"] = "Está cheio de\nrevistas de fora.\fNem dá para ler\nos títulos…",
  ["62:4d73"] = "É um computador\ngrande. Hum. Está\vquebrado.",
  ["62:4d9b"] = "Um monte de moedas\nestranhas!\fTalvez sejam de\noutro país…",
  ["62:4e29"] = "Oi, cara!\nVocê visitou a\vSPROUT TOWER?",
  ["62:4e4f"] = "Eu vim longe\ndemais. Melhor\vligar para casa!",
}
